--
-- Name: _settle_batch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._settle_batch(p_batch uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_b public.item_batches%rowtype; v_open int; v_drafted int;
begin
  update public.item_batch_cells c set status = 'failed', failure_reason = coalesce(failure_reason, 'lease expired after the last allowed attempt'), updated_at = now()
    from public.item_batches b where c.batch_id = b.id and b.id = p_batch and c.status = 'running' and c.lease_until < now() and c.attempts >= b.max_attempts;
  select * into v_b from public.item_batches where id = p_batch;
  if v_b.status in ('cancelled', 'complete', 'failed', 'budget_exhausted') then return; end if;
  select count(*) filter (where status in ('pending', 'running')), count(*) filter (where status = 'drafted') into v_open, v_drafted from public.item_batch_cells where batch_id = p_batch;
  if v_open = 0 then
    update public.item_batches set status = case when v_drafted > 0 then 'complete' else 'failed' end, finished_at = now(),
      last_error = case when v_drafted = 0 then 'No cell produced a candidate' else last_error end where id = p_batch;
  end if;
end $$;


--
-- Name: _stop_batch_budget(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._stop_batch_budget(p_batch uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.item_batch_cells set status = 'failed', lease_until = null, verdict = 'BUDGET_EXHAUSTED', defect_codes = array['BUDGET_EXHAUSTED'],
      failure_reason = coalesce(failure_reason, p_reason), updated_at = now()
    where batch_id = p_batch and status = 'pending';
  update public.item_batches set status = 'budget_exhausted', finished_at = now(), last_error = p_reason where id = p_batch and status in ('queued', 'running');
end $$;


--
-- Name: _write_item_verdict(text, integer, jsonb, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._write_item_verdict(p_item_id text, p_version integer, p_gates jsonb, p_verdict text, p_reason text, p_model text, p_extra jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare g jsonb; v_status text;
begin
  delete from public.item_validations where item_id = p_item_id and reviewer_role in ('editorial_verifier', 'numerical_verifier')
    and coalesce(item_version, 1) = p_version;
  for g in select * from jsonb_array_elements(coalesce(p_gates, '[]'::jsonb)) loop
    insert into public.item_validations(item_id, reviewer_role, status, defect_codes, detail, item_version)
    values (p_item_id, case when g->>'gate' in ('numerical', 'distractors') then 'numerical_verifier' else 'editorial_verifier' end,
            case when (g->>'passed')::boolean then 'PASS' else 'REVISE' end,
            case when (g->>'passed')::boolean then '{}'::text[] else coalesce(array(select jsonb_array_elements_text(coalesce(p_extra->'defectCodes', '[]'::jsonb))), '{}') end,
            jsonb_build_object('gate', g->>'gate', 'detail', g->>'detail'), p_version);
  end loop;
  -- The overall verdict is its own row so a verifier disagreement (HUMAN_REVIEW) stays visible to the reviewer.
  insert into public.item_validations(item_id, reviewer_role, status, defect_codes, detail, item_version)
  values (p_item_id, 'editorial_verifier', p_verdict,
          coalesce(array(select jsonb_array_elements_text(coalesce(p_extra->'defectCodes', '[]'::jsonb))), '{}'),
          jsonb_build_object('gate', 'verdict', 'detail', coalesce(p_reason, ''), 'independentAnswerIndex', p_extra->'independentAnswerIndex', 'derivation', p_extra->'derivation'), p_version);
  v_status := case when p_verdict in ('PASS', 'HUMAN_REVIEW') then 'verified' else 'draft' end;
  update public.assessment_items set review_status = v_status, verifier_model = p_model,
    verified_at = case when v_status = 'verified' then now() else null end
    where id = p_item_id and review_status in ('draft', 'verified');
  insert into public.item_revisions(item_id, item_version, kind, summary) values (p_item_id, p_version, 'verified', 'Automatic check: ' || p_verdict);
  return v_status;
end $$;


--
-- Name: accept_beta_invitation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_beta_invitation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.beta_invitations%rowtype;
begin
  if new.email_confirmed_at is null then return new; end if;
  select * into v from public.beta_invitations where email = lower(btrim(new.email)) and status in ('pending', 'accepted') for update;
  if not found then return new; end if;
  if v.status = 'pending' then
    if v.expires_at <= now() then return new; end if;
    update public.beta_invitations set status = 'accepted', accepted_user_id = new.id, accepted_at = now() where id = v.id;
  elsif v.accepted_user_id is distinct from new.id then
    return new;      -- an accepted invitation belongs to the identity that verified it
  end if;
  if v.role = 'reviewer' then
    insert into public.user_roles (user_id, role) values (new.id, 'diagnostic_reviewer') on conflict do nothing;
  end if;
  return new;
end $$;


--
-- Name: accept_current_week_plan(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_current_week_plan(p_draft_id uuid, p_expected_revision integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid(); v_draft public.plan_drafts%rowtype; v_cycle public.planning_cycles%rowtype;
  v_today date; v_added integer; v_version integer; v_problem text; v_now timestamptz;
begin
  if v_user is null then raise exception 'Not authenticated'; end if;
  if not exists(select 1 from auth.users where id=v_user and email_confirmed_at is not null)
    or not exists(select 1 from public.profiles where id=v_user and onboarding_status='complete')
    or not public.is_beta_admitted(v_user) then raise exception 'Application access required' using errcode='42501'; end if;
  perform public.scope_lock(v_user);
  select * into v_draft from public.plan_drafts where id = p_draft_id for update;
  if not found then raise exception 'Draft not found'; end if;
  if v_draft.user_id <> v_user or v_draft.purpose <> 'current_week_plan' then raise exception 'Unauthorized'; end if;

  if v_draft.status = 'accepted' then
    return (v_draft.draft_json->'receipt')::json;
  end if;
  if v_draft.status <> 'ready' then raise exception 'STALE_PROPOSAL: this proposal is no longer open'; end if;
  if v_draft.revision <> p_expected_revision then raise exception 'STALE_PROPOSAL: stale revision'; end if;

  -- Same lock order as a setup edit (profile first), so an edit and this acceptance serialise one way or the other.
  select onboarding_context_version into v_version from public.profiles where id = v_user for update;
  select * into v_cycle from public.planning_cycles where id = v_draft.cycle_id and user_id = v_user for update;
  if not found or v_cycle.status <> 'active' then raise exception 'CYCLE_CHANGED: the cycle this proposal was for is no longer the active one'; end if;
  v_now := clock_timestamp();
  v_today := (v_now at time zone coalesce(v_cycle.timezone, 'UTC'))::date;
  if v_cycle.ends_at_local < v_today then raise exception 'CYCLE_ENDED: this cycle has ended; plan the next week in the weekly review'; end if;
  if (v_draft.draft_json->>'planning_date')::date <> v_today then raise exception 'STALE_PROPOSAL: the day changed since this was prepared'; end if;
  if v_draft.onboarding_context_version is distinct from v_version then raise exception 'STALE_PROPOSAL: your setup changed'; end if;
  v_problem := public.current_week_proposal_problem(v_user,p_draft_id,clock_timestamp());
  if v_problem is not null then raise exception '%',v_problem; end if;

  insert into public.plan_blocks (
    id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day, starts_at, duration_minutes,
    duration, lm_id, repair_thread_id, rationale, assessment_scope, created_by, learning_objective, suggested_approach, completion_meaning)
  select coalesce(t->>'id', 'task-' || gen_random_uuid()::text), v_user, v_cycle.id, t->>'title',
    coalesce(t->'metadata'->>'detail', ''), coalesce(t->'metadata'->>'task_type', 'study'), coalesce(t->'metadata'->>'origin', 'planner'),
    coalesce(t->'metadata'->>'priority', 'core'), coalesce(t->'metadata'->>'placement', 'day_preferred'), 'not_started',
    (t->>'scheduled_date')::date, (t->>'scheduled_date')::date, nullif(t->'metadata'->>'starts_at', '')::timestamptz,
    (t->>'duration_minutes')::smallint, coalesce(t->>'duration_minutes', '0'), nullif(t->'metadata'->>'lm_id', ''),
    nullif(t->'metadata'->>'repair_thread_id', '')::uuid, coalesce(t->'metadata'->>'rationale', ''),
    case when jsonb_typeof(t->'metadata'->'assessment_scope') = 'object' then t->'metadata'->'assessment_scope' end, 'algorithm',
    nullif(t->'metadata'->>'learning_objective', ''), nullif(t->'metadata'->>'suggested_approach', ''), nullif(t->'metadata'->>'completion_meaning', '')
  from jsonb_array_elements(coalesce(v_draft.draft_json->'tasks', '[]'::jsonb)) t
;
  get diagnostics v_added = row_count;

  update public.plan_drafts set status = 'accepted', accepted_cycle_id = v_cycle.id, revision = revision + 1, updated_at = now(),
    draft_json = jsonb_set(draft_json, '{receipt}', jsonb_build_object('cycle_id', v_cycle.id, 'tasks_added', v_added, 'draft_id', p_draft_id, 'replayed', true))
  where id = p_draft_id;
  return json_build_object('cycle_id', v_cycle.id, 'tasks_added', v_added, 'draft_id', p_draft_id, 'replayed', false);
end $$;


--
-- Name: accept_onboarding_preview(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_onboarding_preview(p_draft_id uuid, p_expected_revision integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid;
  v_draft plan_drafts%rowtype;
  v_cycle_id uuid;
  v_task jsonb;
  v_tasks_array jsonb;
begin
  -- current-week serialization
  perform public.scope_lock(auth.uid());
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_draft
  from public.plan_drafts
  where id = p_draft_id for update;

  if not found then
    raise exception 'Draft not found';
  end if;

  if v_draft.user_id != v_user_id then
    raise exception 'Unauthorized';
  end if;

  if v_draft.status = 'accepted' then
    return json_build_object('roadmap_id', v_draft.roadmap_id, 'cycle_id', v_draft.accepted_cycle_id);
  end if;

  if v_draft.status != 'ready' then
    raise exception 'Draft is not ready';
  end if;

  if v_draft.onboarding_context_version is distinct from
     (select onboarding_context_version from public.profiles where id = v_user_id for update) then
    raise exception 'STALE_PREVIEW: your setup changed after this preview was prepared';
  end if;

  if v_draft.revision != p_expected_revision then
    raise exception 'Stale revision. Expected %, got %', p_expected_revision, v_draft.revision;
  end if;

  if v_draft.roadmap_id is not null then
    update public.study_roadmaps
    set status = 'superseded'
    where user_id = v_user_id and status = 'active';

    update public.study_roadmaps
    set status = 'active'
    where id = v_draft.roadmap_id;
  end if;

  select id into v_cycle_id
  from public.planning_cycles
  where user_id = v_user_id and status = 'active'
  for update;

  if v_cycle_id is null then
    v_cycle_id := gen_random_uuid();
    insert into public.planning_cycles (
      id, user_id, starts_at, ends_at, starts_at_local, ends_at_local, timezone, status
    ) values (
      v_cycle_id, v_user_id, now(), now() + interval '7 days',
      coalesce(v_draft.cycle_start_date, v_draft.proposed_cycle_starts_at_local),
      coalesce(v_draft.cycle_end_date, v_draft.proposed_cycle_ends_at_local),
      coalesce(v_draft.timezone, 'UTC'), 'active'
    );
  else
    update public.planning_cycles
    set starts_at_local = coalesce(v_draft.cycle_start_date, v_draft.proposed_cycle_starts_at_local),
        ends_at_local = coalesce(v_draft.cycle_end_date, v_draft.proposed_cycle_ends_at_local),
        timezone = coalesce(v_draft.timezone, 'UTC')
    where id = v_cycle_id;
  end if;

  v_tasks_array := v_draft.draft_json->'tasks';
  if jsonb_typeof(v_tasks_array) = 'array' then
    insert into public.plan_blocks (
      id, user_id, cycle_id, title, detail, task_type, origin, priority,
      placement, execution, local_date, day, starts_at, duration_minutes,
      duration, lm_id, repair_thread_id, rationale, assessment_scope, created_by,
      learning_objective, suggested_approach, completion_meaning
    )
    select
      coalesce((t->>'id')::text, 'task-' || gen_random_uuid()::text),
      v_user_id,
      v_cycle_id,
      t->>'title',
      coalesce(t->'metadata'->>'detail', ''),
      coalesce(t->'metadata'->>'task_type', 'study'),
      coalesce(t->'metadata'->>'origin', 'planner'),
      coalesce(t->'metadata'->>'priority', 'core'),
      coalesce(t->'metadata'->>'placement', 'day_preferred'),
      'not_started',
      (t->>'scheduled_date')::date,
      (t->>'scheduled_date')::date,
      nullif(t->'metadata'->>'starts_at', '')::timestamptz,
      (t->>'duration_minutes')::smallint,
      coalesce(t->>'duration_minutes', '0'),
      nullif(t->'metadata'->>'lm_id', ''),
      nullif(t->'metadata'->>'repair_thread_id', '')::uuid,
      coalesce(t->'metadata'->>'rationale', ''),
      case when jsonb_typeof(t->'metadata'->'assessment_scope') = 'object' then t->'metadata'->'assessment_scope' end,
      'algorithm',
      nullif(t->'metadata'->>'learning_objective', ''), nullif(t->'metadata'->>'suggested_approach', ''), nullif(t->'metadata'->>'completion_meaning', '')
    from jsonb_array_elements(v_tasks_array) as t
    where t->>'scheduled_date' is not null;
  end if;

  update public.plan_drafts
  set status = 'accepted', accepted_cycle_id = v_cycle_id, revision = revision + 1, updated_at = now()
  where id = p_draft_id;

  update public.profiles
  set onboarding_status = 'complete', onboarding_completed_at = now(),
      onboarding_preview_id = p_draft_id, updated_at = now()
  where id = v_user_id;

  return json_build_object('roadmap_id', v_draft.roadmap_id, 'cycle_id', v_cycle_id);
end;
$$;


--
-- Name: accept_plan_draft(uuid, integer, date, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_plan_draft(p_draft_id uuid, p_expected_revision integer, p_cycle_starts_at_local date, p_cycle_ends_at_local date, p_timezone text, p_tasks jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_user_id uuid;
  v_draft_status text;
  v_draft_revision integer;
  v_cycle_id uuid;
  v_task jsonb;
begin
  -- Get user
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Unauthorized';
  end if;

  -- Lock the draft for update
  select status, revision into v_draft_status, v_draft_revision
  from public.plan_drafts
  where id = p_draft_id and user_id = v_user_id
  for update;

  if not found then
    raise exception 'Draft not found.';
  end if;

  if v_draft_status != 'ready' then
    raise exception 'Draft is not ready for acceptance.';
  end if;

  if v_draft_revision != p_expected_revision then
    raise exception 'Stale draft revision.';
  end if;

  -- Create Cycle
  insert into public.planning_cycles (
    user_id, starts_at, ends_at, starts_at_local, ends_at_local, timezone, status
  ) values (
    v_user_id, now(), now() + interval '7 days', p_cycle_starts_at_local, p_cycle_ends_at_local, p_timezone, 'active'
  ) returning id into v_cycle_id;

  -- Insert Tasks
  for v_task in select * from jsonb_array_elements(p_tasks)
  loop
    insert into public.plan_blocks (
      user_id, cycle_id, title, detail, duration_minutes, task_type, priority, placement, execution,
      starts_at, rationale, learning_objective, suggested_approach, focus_distinction, verification_intent,
      curriculum_reference, completion_meaning, created_by
    ) values (
      v_user_id, v_cycle_id, v_task->>'title', v_task->>'detail', (v_task->>'duration_minutes')::smallint,
      v_task->>'task_type', v_task->>'priority', v_task->>'placement', v_task->>'execution',
      (v_task->>'starts_at')::timestamptz, coalesce(v_task->>'rationale', ''), v_task->>'learning_objective',
      v_task->>'suggested_approach', v_task->>'focus_distinction', v_task->>'verification_intent',
      v_task->>'curriculum_reference', v_task->>'completion_meaning', 'algorithm'
    );
  end loop;

  -- Mark Draft Accepted
  update public.plan_drafts
  set status = 'accepted', revision = revision + 1, updated_at = now()
  where id = p_draft_id;

  return v_cycle_id;
end;
$$;


--
-- Name: accept_repair_proposal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_repair_proposal(p_proposal_id uuid, p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  v_prop public.coach_proposals%rowtype;
  v_cycle public.planning_cycles%rowtype;
  v_changes jsonb;
  v_thread_ids uuid[];
  v_attempt uuid;
  v_today date;
  v_task jsonb;
  v_wait jsonb;
  v_thread public.repair_threads%rowtype;
  v_ids text[] := '{}';
  v_check_id text;
  v_minutes int;
  v_date date;
  v_receipt jsonb;
begin
  -- planning input serialization
  perform public.scope_lock(auth.uid());
  if v_user is null then raise exception 'Sign in to update your plan.' using errcode = '42501'; end if;
  if not exists (select 1 from auth.users where id = v_user and email_confirmed_at is not null) then
    raise exception 'Verify your email before using your plan.' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles where id = v_user and onboarding_status = 'complete') then
    raise exception 'Complete setup before updating your plan.' using errcode = '42501'; end if;
  if p_key is null or length(p_key) < 8 or length(p_key) > 100 then raise exception 'A request key is required.' using errcode = '22023'; end if;

  select * into v_prop from public.coach_proposals where id = p_proposal_id and user_id = v_user and intent = 'diagnostic_repair' for update;
  if not found then raise exception 'That follow-up could not be found.' using errcode = 'P0002'; end if;

  if v_prop.status = 'executed' then
    if v_prop.idempotency_key = p_key then return coalesce(v_prop.accept_receipt, '{}'::jsonb) || jsonb_build_object('replayed', true); end if;
    return jsonb_build_object('ok', false, 'code', 'ALREADY_ACCEPTED');
  end if;
  if v_prop.status <> 'pending' or v_prop.expires_at is null or v_prop.expires_at < now() then
    return jsonb_build_object('ok', false, 'code', 'PROPOSAL_UNAVAILABLE');
  end if;

  v_changes := v_prop.proposed_changes;
  v_thread_ids := array(select x::uuid from jsonb_array_elements_text(coalesce(v_changes->'threadIds', '[]'::jsonb)) x);
  v_attempt := nullif(v_changes->>'attemptId', '')::uuid;

  select * into v_cycle from public.planning_cycles where id = v_prop.target_cycle_id and user_id = v_user for update;
  if not found or v_cycle.status <> 'active' then return jsonb_build_object('ok', false, 'code', 'CYCLE_CHANGED'); end if;

  -- Lock, THEN compare: once these are locked nothing can change them between the check and the writes.
  perform 1 from public.plan_blocks where cycle_id = v_cycle.id and user_id = v_user order by id for update;
  perform 1 from public.repair_threads where id = any(v_thread_ids) and user_id = v_user order by id for update;
  perform 1 from public.availability_windows where user_id = v_user and status = 'active' order by id for share;
  perform 1 from public.calendar_commitments where user_id = v_user and status = 'active' order by id for share;
  if public.repair_source_version(v_user, v_cycle.id, v_thread_ids, v_attempt) is distinct from v_prop.source_version then
    return jsonb_build_object('ok', false, 'code', 'STALE_PROPOSAL');
  end if;
  if coalesce(array_length(v_thread_ids, 1), 0) = 0
     or (select count(*) from public.repair_threads where id = any(v_thread_ids) and user_id = v_user and status in ('open', 'proposed')) <> array_length(v_thread_ids, 1) then
    return jsonb_build_object('ok', false, 'code', 'STALE_PROPOSAL');
  end if;

  v_today := (now() at time zone coalesce(v_cycle.timezone, 'UTC'))::date;

  for v_task in select * from jsonb_array_elements(coalesce(v_changes->'tasks', '[]'::jsonb)) loop
    v_date := (v_task->>'local_date')::date;
    v_minutes := (v_task->>'duration_minutes')::int;
    select * into v_thread from public.repair_threads where id = (v_task->>'repair_thread_id')::uuid;
    if v_thread.id is null or not (v_thread.id = any(v_thread_ids)) or v_thread.user_id <> v_user then
      raise exception 'A task refers to a repair that is not part of this follow-up.' using errcode = '22023'; end if;
    if v_date is null or v_date < v_cycle.starts_at_local or v_date > v_cycle.ends_at_local or v_date < v_today then
      raise exception 'A repair must be placed today or later, inside your open week.' using errcode = '22023'; end if;
    if v_minutes is null or v_minutes not between 5 and 180 then raise exception 'A repair needs 5 to 180 minutes.' using errcode = '22023'; end if;
    insert into public.plan_blocks (id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day,
        duration_minutes, duration, rationale, suggested_approach, completion_meaning, learning_objective, is_protected_commitment, created_by,
        repair_thread_id, attempt_id, concept_id, source_pointer)
      values (v_task->>'id', v_user, v_cycle.id, v_task->>'title', coalesce(v_task->>'detail', ''), 'repair', 'diagnostic', 'core', 'day_preferred', 'not_started',
        v_date, v_date::text, v_minutes, v_minutes::text, coalesce(v_task->>'rationale', ''), nullif(v_task->>'suggested_approach', ''),
        nullif(v_task->>'completion_meaning', ''), nullif(v_task->>'learning_objective', ''), false, 'algorithm', v_thread.id, v_attempt, v_thread.concept_id,
        jsonb_build_object('kind', 'diagnostic_result', 'attemptId', v_attempt, 'proposalId', p_proposal_id));
    insert into public.task_events(user_id, task_id, event_type, payload, previous)
      values (v_user, v_task->>'id', 'created', jsonb_build_object('source', 'repair_proposal', 'proposalId', p_proposal_id, 'threadId', v_thread.id), '{}'::jsonb);
    v_ids := array_append(v_ids, v_task->>'id');
  end loop;

  -- A re-check that fits in this week is a real task, linked to exactly the repairs it checks.
  if jsonb_typeof(v_changes->'check') = 'object' then
    v_date := (v_changes->'check'->>'local_date')::date;
    v_minutes := (v_changes->'check'->>'duration_minutes')::int;
    if v_date is null or v_date < v_cycle.starts_at_local or v_date > v_cycle.ends_at_local or v_date < v_today then
      raise exception 'A re-check must be placed today or later, inside your open week.' using errcode = '22023'; end if;
    v_check_id := v_changes->'check'->>'id';
    insert into public.plan_blocks (id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day,
        duration_minutes, duration, rationale, suggested_approach, completion_meaning, learning_objective, is_protected_commitment, created_by, source_pointer)
      values (v_check_id, v_user, v_cycle.id, v_changes->'check'->>'title', coalesce(v_changes->'check'->>'detail', ''), 'recheck', 'diagnostic', 'core', 'day_preferred', 'not_started',
        v_date, v_date::text, v_minutes, v_minutes::text, coalesce(v_changes->'check'->>'rationale', ''), nullif(v_changes->'check'->>'suggested_approach', ''),
        nullif(v_changes->'check'->>'completion_meaning', ''), nullif(v_changes->'check'->>'learning_objective', ''), false, 'algorithm',
        jsonb_build_object('kind', 'diagnostic_result', 'attemptId', v_attempt, 'proposalId', p_proposal_id));
    insert into public.repair_check_threads(check_task_id, thread_id, user_id)
      select v_check_id, x::uuid, v_user from jsonb_array_elements_text(v_changes->'check'->'threadIds') x
      where x::uuid = any(v_thread_ids);
    insert into public.task_events(user_id, task_id, event_type, payload, previous)
      values (v_user, v_check_id, 'created', jsonb_build_object('source', 'repair_proposal', 'proposalId', p_proposal_id), '{}'::jsonb);
    v_ids := array_append(v_ids, v_check_id);
  end if;

  -- A re-check that cannot fit this week is an explicit waiting obligation on its repairs, with the earliest date it may happen.
  for v_wait in select * from jsonb_array_elements(coalesce(v_changes->'waitingChecks', '[]'::jsonb)) loop
    update public.repair_threads set next_recheck_due_at = ((v_wait->>'earliestDate')::date)::timestamptz, updated_at = now(), revision = revision + 1
      where id in (select x::uuid from jsonb_array_elements_text(v_wait->'threadIds') x) and id = any(v_thread_ids) and user_id = v_user;
    insert into public.repair_thread_events(thread_id, event_type, details)
      select x::uuid, 'check_waiting', jsonb_build_object('earliestDate', v_wait->>'earliestDate', 'proposalId', p_proposal_id)
      from jsonb_array_elements_text(v_wait->'threadIds') x where x::uuid = any(v_thread_ids);
  end loop;

  v_receipt := jsonb_build_object('ok', true, 'replayed', false, 'proposalId', p_proposal_id, 'taskIds', to_jsonb(v_ids),
    'checkTaskId', v_check_id, 'threadIds', to_jsonb(v_thread_ids), 'waitingChecks', coalesce(v_changes->'waitingChecks', '[]'::jsonb));
  update public.coach_proposals set status = 'executed', executed_at = now(), applied_at = now(), decided_at = now(), idempotency_key = p_key,
    applied_task_ids = null, accept_receipt = v_receipt where id = p_proposal_id;
  return v_receipt;
end; $$;


--
-- Name: accept_weekly_review(uuid, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_weekly_review(p_cycle_id uuid, p_closure_kind text, p_no_paper_reason text, p_resolutions jsonb, p_recap jsonb, p_next jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_cycle public.planning_cycles%rowtype;
  v_review public.weekly_reviews%rowtype;
  v_paper_id text;
  v_paper_attempt text;
  v_unresolved integer;
  v_unknown text[];
  v_res jsonb := coalesce(p_resolutions, '{}'::jsonb);
  v_bad integer;
  v_next uuid;
  v_next_start date;
  v_next_end date;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;
  if p_closure_kind not in ('paper_scored', 'no_paper') then
    raise exception 'Invalid closure kind';
  end if;

  select * into v_cycle from public.planning_cycles where id = p_cycle_id for update;
  if not found or v_cycle.user_id <> v_user then
    raise exception 'Unauthorized';
  end if;

  -- Idempotent: a repeated or concurrent confirmation returns the first result.
  select * into v_review from public.weekly_reviews where cycle_id = p_cycle_id;
  if found then
    return json_build_object('closed_cycle_id', p_cycle_id, 'next_cycle_id', v_review.next_cycle_id, 'already_closed', true);
  end if;

  if v_cycle.status <> 'active' then
    raise exception 'Cycle is not active';
  end if;

  -- The cycle's weekly paper, if it has one.
  select id, attempt_id into v_paper_id, v_paper_attempt
  from public.plan_blocks
  where cycle_id = p_cycle_id and user_id = v_user
    and task_type = 'diagnostic' and assessment_scope->>'kind' = 'weekly_paper'
  order by local_date desc nulls last limit 1;

  -- A weekly paper started from the student's completed scope is an attempt of this cycle even when
  -- no planner-scheduled paper block exists (or was never linked): count it.
  if v_paper_attempt is null then
    select id::text into v_paper_attempt from public.assessment_attempts
    where user_id = v_user and cycle_id = p_cycle_id and attempt_kind = 'weekly' and status = 'scored'
    order by submitted_at desc nulls last limit 1;
  end if;

  if p_closure_kind = 'paper_scored' then
    if v_paper_attempt is null or not exists (
      select 1 from public.assessment_attempts
      where id::text = v_paper_attempt and user_id = v_user and status = 'scored'
    ) then
      raise exception 'The weekly paper has not been scored';
    end if;
  else
    if coalesce(btrim(p_no_paper_reason), '') = '' then
      raise exception 'A no-paper closure needs a reason';
    end if;
    if v_paper_attempt is not null and exists (
      select 1 from public.assessment_attempts
      where id::text = v_paper_attempt and user_id = v_user and status = 'scored'
    ) then
      raise exception 'The paper was scored; close with the paper';
    end if;
  end if;

  -- Every due task must be finished, skipped, deferred, or explicitly unknown.
  if jsonb_typeof(v_res) <> 'object' then
    raise exception 'Invalid resolutions';
  end if;
  select count(*) into v_bad from jsonb_each_text(v_res)
  where value not in ('completed', 'skipped', 'deferred', 'unknown');
  if v_bad > 0 then
    raise exception 'Invalid resolution value';
  end if;

  select count(*) into v_unresolved
  from public.plan_blocks
  where cycle_id = p_cycle_id and user_id = v_user
    and local_date <= v_cycle.ends_at_local
    and execution in ('not_started', 'in_progress', 'partial')
    and id is distinct from v_paper_id
    and not (v_res ? id);
  if v_unresolved > 0 then
    raise exception 'Unresolved tasks: %', v_unresolved;
  end if;

  -- Apply the explicit resolutions (only to this cycle's own due, open tasks).
  update public.plan_blocks b
  set execution = v_res->>b.id, revision = b.revision + 1, updated_at = now()
  where b.cycle_id = p_cycle_id and b.user_id = v_user
    and b.execution in ('not_started', 'in_progress', 'partial')
    and b.id is distinct from v_paper_id
    and v_res ? b.id and v_res->>b.id in ('completed', 'skipped', 'deferred');

  select coalesce(array_agg(key), '{}') into v_unknown
  from jsonb_each_text(v_res) where value = 'unknown';

  v_next_start := (p_next->>'starts_at_local')::date;
  v_next_end := (p_next->>'ends_at_local')::date;
  if v_next_start is null or v_next_end is null or v_next_start <= v_cycle.ends_at_local then
    raise exception 'The next cycle must start after this one ends';
  end if;
  if jsonb_typeof(p_next->'rows') <> 'array' or jsonb_array_length(p_next->'rows') = 0 then
    raise exception 'The next week has no tasks';
  end if;

  update public.planning_cycles set status = 'closed', revision = revision + 1 where id = p_cycle_id;

  v_next := gen_random_uuid();
  insert into public.planning_cycles (
    id, user_id, starts_at, ends_at, starts_at_local, ends_at_local, timezone, status, anchor_day
  ) values (
    v_next, v_user, now(), now() + interval '7 days', v_next_start, v_next_end,
    coalesce(p_next->>'timezone', v_cycle.timezone, 'UTC'), 'active',
    nullif(p_next->>'anchor_day', '')::smallint
  );

  insert into public.plan_blocks (
    id, user_id, cycle_id, title, detail, task_type, origin, priority,
    placement, execution, local_date, day, starts_at, duration_minutes, duration,
    lm_id, repair_thread_id, rationale, assessment_scope, created_by
  )
  select
    r->>'id', v_user, v_next, r->>'title', r->>'detail', r->>'task_type', r->>'origin',
    r->>'priority', r->>'placement', r->>'execution', (r->>'local_date')::date, (r->>'day')::date,
    nullif(r->>'starts_at', '')::timestamptz, (r->>'duration_minutes')::smallint, r->>'duration',
    nullif(r->>'lm_id', ''), nullif(r->>'repair_thread_id', '')::uuid, r->>'rationale',
    case when jsonb_typeof(r->'assessment_scope') = 'object' then r->'assessment_scope' end, r->>'created_by'
  from jsonb_array_elements(p_next->'rows') as r;

  insert into public.weekly_reviews (
    user_id, cycle_id, next_cycle_id, closure_kind, no_paper_reason, unknown_task_ids, recap, resolutions
  ) values (
    v_user, p_cycle_id, v_next, p_closure_kind, nullif(btrim(p_no_paper_reason), ''), v_unknown,
    coalesce(p_recap, '{}'::jsonb), v_res
  );

  return json_build_object('closed_cycle_id', p_cycle_id, 'next_cycle_id', v_next, 'already_closed', false);
end;
$$;


--
-- Name: accept_weekly_transition(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_weekly_transition(p_draft_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  v_cycle_id uuid;
  v_cycle public.planning_cycles%rowtype;
  v_draft public.weekly_transition_drafts%rowtype;
  v_review public.weekly_reviews%rowtype;
  v_actions jsonb;
  v_next jsonb;
  v_action jsonb;
  v_task public.plan_blocks%rowtype;
  v_pred public.plan_blocks%rowtype;
  v_succ public.plan_blocks%rowtype;
  v_new_exec text;
  v_next_cycle uuid;
  v_next_start date;
  v_unknown text[] := '{}';
  v_continued jsonb := '[]'::jsonb;
  v_place date;
  v_minutes integer;
  v_paper_attempt text;
  v_succ_id text;
begin
  -- current-week serialization
  perform public.scope_lock(auth.uid());
  if v_user is null then raise exception 'Sign in to close your week.' using errcode = '42501'; end if;
  if not exists (select 1 from auth.users where id = v_user and email_confirmed_at is not null) then
    raise exception 'Verify your email before using your plan.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = v_user and onboarding_status = 'complete') then
    raise exception 'Complete setup before closing your week.' using errcode = '42501';
  end if;

  -- Lock order: cycle, then draft, then tasks (by id).
  select cycle_id into v_cycle_id from public.weekly_transition_drafts where id = p_draft_id and user_id = v_user;
  if v_cycle_id is null then raise exception 'That review could not be found.' using errcode = 'P0002'; end if;
  select * into v_cycle from public.planning_cycles where id = v_cycle_id and user_id = v_user for update;
  if not found then raise exception 'That week could not be found.' using errcode = 'P0002'; end if;
  select * into v_draft from public.weekly_transition_drafts where id = p_draft_id and user_id = v_user for update;

  select * into v_review from public.weekly_reviews where cycle_id = v_cycle_id;
  if found then
    if v_review.draft_id = p_draft_id then
      return jsonb_build_object('ok', true, 'alreadyClosed', true, 'closedCycleId', v_cycle_id, 'nextCycleId', v_review.next_cycle_id,
        'continued', coalesce(jsonb_array_length(v_review.continuations), 0));
    end if;
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CLOSED');
  end if;
  if v_draft.status <> 'ready' or v_draft.expires_at < now() then
    return jsonb_build_object('ok', false, 'code', 'DRAFT_UNAVAILABLE');
  end if;
  if v_cycle.status <> 'active' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_CLOSED');
  end if;
  -- Lock first, THEN compare: once the closing week's tasks are locked nothing can change them between the
  -- check and the writes. Availability and commitments are locked against edits too (an insert of a new row
  -- is not blocked; the next review sees it). Order is fixed: cycle, draft, tasks, then these.
  perform 1 from public.plan_blocks where cycle_id = v_cycle_id and user_id = v_user order by id for update;
  perform 1 from public.availability_windows where user_id = v_user and status = 'active' order by id for share;
  perform 1 from public.calendar_commitments where user_id = v_user and status = 'active' order by id for share;
  if public.weekly_source_version(v_user, v_cycle_id) is distinct from v_draft.source_version then
    return jsonb_build_object('ok', false, 'code', 'STALE_PROPOSAL');
  end if;

  -- The paper gate is re-checked here, not trusted from the preview.
  select attempt_id into v_paper_attempt from public.plan_blocks
    where cycle_id = v_cycle_id and user_id = v_user and task_type = 'diagnostic' and assessment_scope->>'kind' = 'weekly_paper'
    order by local_date desc nulls last limit 1;
  if v_draft.closure_kind = 'paper_scored' then
    if not exists (select 1 from public.assessment_attempts where user_id = v_user and status = 'scored'
        and (id::text = v_paper_attempt or (cycle_id = v_cycle_id and attempt_kind = 'weekly'))) then
      raise exception 'The weekly paper has not been scored.' using errcode = '22023';
    end if;
  else
    if coalesce(btrim(v_draft.no_paper_reason), '') = '' then
      raise exception 'A no-paper closure needs a reason.' using errcode = '22023';
    end if;
    if exists (select 1 from public.assessment_attempts where user_id = v_user and status = 'scored' and cycle_id = v_cycle_id and attempt_kind = 'weekly') then
      raise exception 'The paper was scored; close with the paper.' using errcode = '22023';
    end if;
  end if;

  v_actions := coalesce(v_draft.proposal->'actions', '[]'::jsonb);
  v_next := v_draft.proposal->'next';
  v_next_start := (v_next->>'starts_at_local')::date;
  if v_next_start is null or (v_next->>'ends_at_local') is null or v_next_start <= v_cycle.ends_at_local then
    raise exception 'The next week must start after this one ends.' using errcode = '22023';
  end if;

  -- Pass 1: what happened. Every change is recorded in the task's own history.
  for v_action in select * from jsonb_array_elements(v_actions) loop
    select * into v_task from public.plan_blocks where id = v_action->>'taskId' and cycle_id = v_cycle_id and user_id = v_user;
    if not found then raise exception 'A task in this review is no longer part of the week.' using errcode = '22023'; end if;
    v_new_exec := nullif(v_action->>'setExecution', '');
    if v_new_exec is not null and v_new_exec is distinct from v_task.execution then
      update public.plan_blocks set execution = v_new_exec, revision = revision + 1, updated_at = now() where id = v_task.id;
      insert into public.task_events(user_id, task_id, event_type, payload, previous)
        values (v_user, v_task.id, v_new_exec, jsonb_build_object('source', 'weekly_review', 'draftId', p_draft_id),
                jsonb_build_object('execution', v_task.execution, 'revision', v_task.revision));
    end if;
    if coalesce((v_action->>'cancel')::boolean, false) then
      update public.plan_blocks set cancelled_at = now(), revision = revision + 1, updated_at = now() where id = v_task.id;
      insert into public.task_events(user_id, task_id, event_type, payload, previous)
        values (v_user, v_task.id, 'cancelled', jsonb_build_object('source', 'weekly_review', 'draftId', p_draft_id),
                jsonb_build_object('execution', v_task.execution, 'revision', v_task.revision));
    end if;
    if coalesce((v_action->>'unknown')::boolean, false) then v_unknown := v_unknown || v_task.id; end if;
  end loop;

  -- The next week. A learner may have only one active cycle, so the old one is closed first.
  update public.planning_cycles set status = 'closed', revision = revision + 1 where id = v_cycle_id;
  v_next_cycle := gen_random_uuid();
  insert into public.planning_cycles (id, user_id, starts_at, ends_at, starts_at_local, ends_at_local, timezone, status, anchor_day)
    values (v_next_cycle, v_user, now(), now() + interval '7 days', v_next_start, (v_next->>'ends_at_local')::date,
            coalesce(v_next->>'timezone', v_cycle.timezone, 'UTC'), 'active', nullif(v_next->>'anchor_day', '')::smallint);

  -- An empty week is valid: a planned break or no availability must not trap the student.
  insert into public.plan_blocks (
    id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day, starts_at,
    duration_minutes, duration, lm_id, repair_thread_id, rationale, assessment_scope, created_by,
    concept_id, learning_objective, suggested_approach, completion_meaning
  )
  select r->>'id', v_user, v_next_cycle, r->>'title', r->>'detail', r->>'task_type', r->>'origin', r->>'priority', r->>'placement',
         r->>'execution', (r->>'local_date')::date, (r->>'day')::date, nullif(r->>'starts_at', '')::timestamptz,
         (r->>'duration_minutes')::smallint, r->>'duration', nullif(r->>'lm_id', ''), nullif(r->>'repair_thread_id', '')::uuid,
         r->>'rationale', case when jsonb_typeof(r->'assessment_scope') = 'object' then r->'assessment_scope' end, r->>'created_by',
         nullif(r->>'concept_id', '')::uuid, nullif(r->>'learning_objective', ''), nullif(r->>'suggested_approach', ''), nullif(r->>'completion_meaning', '')
  from jsonb_array_elements(coalesce(v_next->'rows', '[]'::jsonb)) as r;

  -- Pass 2: what happens next. A continuation copies PLANNING context (mapping, objective, method, guidance,
  -- split group, repair link). Everything specific to the occurrence is reset and stays with the week it
  -- belongs to: minutes and history (separate tables, never copied), confirmations, the attempt, the linked
  -- evidence event, the class session, any cancellation, and the date. Placement is exactly what the saved
  -- preview showed; nothing is scheduled again here.
  perform set_config('roadmap.continuation_command', 'on', true);
  for v_action in select * from jsonb_array_elements(v_actions) loop
    if v_action->'continuation' is null or jsonb_typeof(v_action->'continuation') <> 'object' then continue; end if;
    select * into v_pred from public.plan_blocks where id = v_action->>'taskId' and user_id = v_user;
    v_minutes := (v_action->'continuation'->>'minutes')::integer;
    v_place := nullif(v_action->'continuation'->'placement'->>'date', '')::date;
    if v_place is not null and (v_place < v_next_start or v_place > (v_next->>'ends_at_local')::date) then
      raise exception 'A placement must be inside the next week.' using errcode = '22023';
    end if;
    v_succ_id := 'task-' || gen_random_uuid()::text;
    v_succ := jsonb_populate_record(null::public.plan_blocks, to_jsonb(v_pred) || jsonb_build_object(
      'id', v_succ_id, 'cycle_id', v_next_cycle, 'execution', 'not_started', 'revision', 1, 'updated_at', now(),
      'local_date', v_place, 'starts_at', null,
      'day', coalesce(v_place, v_next_start)::text,                              -- plan_blocks.day is text NOT NULL
      'placement', case when v_place is null then 'floating' else 'day_preferred' end,
      'state', case when v_place is null then 'floating' else 'planned' end,
      'duration_minutes', v_minutes, 'duration', v_minutes::text,
      'cancelled_at', null, 'cancellation_reason', null, 'cancellation_source_id', null,
      'attempt_id', null, 'evidence_event_id', null, 'class_session_id', null, 'assessment_scope', null,
      'created_by', 'student', 'continued_from_task_id', v_pred.id,
      'carry_intent', v_action->'continuation'->>'intent',
      'estimate_provisional', coalesce((v_action->'continuation'->>'provisional')::boolean, false),
      'rationale', 'Continuing from last week. Your earlier progress and time stay with that week.'
    ));
    insert into public.plan_blocks select (v_succ).*;
    insert into public.task_events(user_id, task_id, event_type, payload, previous)
      values (v_user, v_pred.id, 'details_changed', jsonb_build_object('kind', 'continued', 'continuedAs', v_succ_id, 'draftId', p_draft_id), '{}'::jsonb),
             (v_user, v_succ_id, 'created', jsonb_build_object('continuedFrom', v_pred.id, 'draftId', p_draft_id, 'placedOn', v_place), '{}'::jsonb);
    v_continued := v_continued || jsonb_build_array(jsonb_build_object('from', v_pred.id, 'to', v_succ_id, 'date', v_place));
  end loop;

  insert into public.weekly_reviews (user_id, cycle_id, next_cycle_id, closure_kind, no_paper_reason, unknown_task_ids, recap, resolutions, draft_id, continuations)
    values (v_user, v_cycle_id, v_next_cycle, v_draft.closure_kind, nullif(btrim(v_draft.no_paper_reason), ''), v_unknown,
            coalesce(v_draft.proposal->'recap', '{}'::jsonb), v_draft.choices, p_draft_id, v_continued);
  update public.weekly_transition_drafts set status = 'accepted' where id = p_draft_id;

  return jsonb_build_object('ok', true, 'alreadyClosed', false, 'closedCycleId', v_cycle_id, 'nextCycleId', v_next_cycle,
    'continued', jsonb_array_length(v_continued));
end; $$;


--
-- Name: apply_class_log(uuid, text, date, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_class_log(p_cycle_id uuid, p_idempotency_key text, p_class_date date, p_kind text, p_note text, p_items jsonb, p_tasks jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_cycle public.planning_cycles%rowtype;
  v_session public.class_sessions%rowtype;
  v_task_count integer := 0;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;
  if p_kind not in ('covered', 'revision', 'missed', 'cancelled', 'none') then
    raise exception 'Invalid kind';
  end if;
  if coalesce(btrim(p_idempotency_key), '') = '' then
    raise exception 'Missing idempotency key';
  end if;

  select * into v_cycle from public.planning_cycles where id = p_cycle_id for update;
  if not found or v_cycle.user_id <> v_user or v_cycle.status <> 'active' then
    raise exception 'Unauthorized';
  end if;

  -- Idempotent replay.
  select * into v_session from public.class_sessions where user_id = v_user and idempotency_key = p_idempotency_key;
  if found then
    return json_build_object('session_id', v_session.id, 'already_applied', true,
      'tasks', (select count(*) from public.plan_blocks where class_session_id = v_session.id));
  end if;

  insert into public.class_sessions (user_id, cycle_id, class_date, kind, note, idempotency_key)
  values (v_user, p_cycle_id, p_class_date, p_kind, nullif(btrim(p_note), ''), p_idempotency_key)
  returning * into v_session;

  insert into public.class_session_items (session_id, outcome_id, extent, portion_note, studied_in_class)
  select v_session.id, i->>'outcome_id', i->>'extent', nullif(i->>'portion_note', ''), coalesce((i->>'studied_in_class')::boolean, false)
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as i;

  -- Tasks may belong to this session or to an earlier session of this user
  -- (carryover that finally found a day); each must be the user's own.
  if jsonb_typeof(coalesce(p_tasks, '[]'::jsonb)) = 'array' then
    if exists (
      select 1 from jsonb_array_elements(p_tasks) t
      where coalesce(nullif(t->>'session_id', '')::uuid, v_session.id) <> v_session.id
        and not exists (select 1 from public.class_sessions s where s.id = (t->>'session_id')::uuid and s.user_id = v_user)
    ) then
      raise exception 'Unauthorized';
    end if;
    if exists (
      select 1 from jsonb_array_elements(p_tasks) t
      where (t->>'local_date')::date <= p_class_date
         or (t->>'local_date')::date < v_cycle.starts_at_local
         or (t->>'local_date')::date >= v_cycle.ends_at_local
    ) then
      raise exception 'A task falls outside the open days of this cycle';
    end if;

    insert into public.plan_blocks (
      id, user_id, cycle_id, title, detail, task_type, origin, priority,
      placement, execution, local_date, day, duration_minutes, duration,
      lm_id, repair_thread_id, rationale, created_by, class_session_id, outcome_id
    )
    select
      t->>'id', v_user, p_cycle_id, t->>'title', t->>'detail', t->>'task_type', t->>'origin', 'core',
      'day_preferred', 'not_started', (t->>'local_date')::date, (t->>'local_date')::date,
      (t->>'duration_minutes')::smallint, t->>'duration_minutes',
      null, nullif(t->>'repair_thread_id', '')::uuid, t->>'rationale', 'algorithm',
      coalesce(nullif(t->>'session_id', '')::uuid, v_session.id), nullif(t->>'outcome_id', '')
    from jsonb_array_elements(p_tasks) t;
    get diagnostics v_task_count = row_count;
  end if;

  return json_build_object('session_id', v_session.id, 'already_applied', false, 'tasks', v_task_count);
end;
$$;


--
-- Name: apply_diagnostic_repair_proposal(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_diagnostic_repair_proposal(p_proposal_id uuid, p_tasks jsonb) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid;
  v_proposal record;
  v_task jsonb;
  v_task_id uuid;
  v_applied_ids uuid[] := '{}';
begin
  v_user_id := auth.uid();
  if v_user_id is null then raise exception 'Unauthorized'; end if;

  select * into v_proposal from public.coach_proposals where id = p_proposal_id and user_id = v_user_id for update;
  if v_proposal is null then raise exception 'Proposal not found'; end if;
  if v_proposal.status = 'executed' then return v_proposal.applied_task_ids; end if;

  for v_task in select * from jsonb_array_elements(p_tasks) loop
    v_task_id := (v_task->>'id')::uuid;
    insert into public.plan_blocks (
      id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, 
      local_date, day, starts_at, duration_minutes, duration, rationale, suggested_approach, completion_meaning, is_protected_commitment, created_by, repair_thread_id, attempt_id, concept_id
    ) values (
      v_task_id, v_user_id, (v_task->>'cycle_id')::uuid, v_task->>'title', v_task->>'detail', v_task->>'task_type', v_task->>'origin', v_task->>'priority', v_task->>'placement', v_task->>'execution',
      (nullif(v_task->>'local_date', ''))::date, v_task->>'day', (nullif(v_task->>'starts_at', ''))::timestamptz, (v_task->>'duration_minutes')::int, v_task->>'duration', v_task->>'rationale', v_task->>'suggested_approach', v_task->>'completion_meaning', false, 'algorithm', (v_task->>'repair_thread_id')::uuid, (nullif(v_task->>'attempt_id', ''))::uuid, (nullif(v_task->>'concept_id', ''))::uuid
    );
    v_applied_ids := array_append(v_applied_ids, v_task_id);
    
    if (v_task->>'repair_thread_id') is not null then
      update public.repair_threads set status = 'scheduled', updated_at = now() where id = (v_task->>'repair_thread_id')::uuid;
    end if;
  end loop;

  update public.coach_proposals set status = 'executed', applied_task_ids = v_applied_ids, applied_at = now() where id = p_proposal_id;

  return v_applied_ids;
end;
$$;


--
-- Name: apply_redistribution(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_redistribution(p_user uuid, p_source text, p_changes jsonb, p_input_hash text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_src public.plan_blocks%rowtype; v_rec public.redistribution_receipts%rowtype; v_c jsonb; v_row public.plan_blocks%rowtype;
  v_new integer; v_out jsonb := '[]'::jsonb; v_placed integer := 0; v_end timestamptz;
begin
  perform public.scope_lock(p_user);
  select * into v_src from public.plan_blocks where id = p_source and user_id = p_user for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_src.execution not in ('deferred', 'skipped') then return jsonb_build_object('ok', false, 'code', 'NOT_MISSED'); end if;
  select * into v_rec from public.redistribution_receipts where source_task_id = p_source and reversed_at is null;
  if found then return jsonb_build_object('ok', true, 'replayed', true, 'placed', v_rec.placed_minutes, 'changes', v_rec.changes); end if;
  if v_src.cycle_id is null or p_input_hash is distinct from public.current_week_source_hash(p_user, v_src.cycle_id) then
    raise exception 'REDISTRIBUTION_STALE: the week changed while this was being planned';
  end if;
  for v_c in select value from jsonb_array_elements(coalesce(p_changes, '[]'::jsonb)) order by value->>'task_id' loop
    select * into v_row from public.plan_blocks where id = v_c->>'task_id' and user_id = p_user for update;
    if not found or v_row.execution <> 'not_started' or v_row.cancelled_at is not null or v_row.revision <> (v_c->>'expected_revision')::int then
      raise exception 'REDISTRIBUTION_STALE: a session changed while this was being planned';
    end if;
    v_new := v_row.duration_minutes + (v_c->>'add_minutes')::int;
    if v_new > 180 or (v_c->>'add_minutes')::int <= 0 then raise exception 'REDISTRIBUTION_INVALID: a session cannot take that many minutes'; end if;
    if v_row.placement = 'timed' and v_row.starts_at is not null then
      v_end := v_row.starts_at + make_interval(mins => v_new);
      if exists (select 1 from public.plan_blocks o where o.user_id = p_user and o.id <> v_row.id and o.cancelled_at is null and o.execution not in ('cancelled')
                   and o.placement = 'timed' and o.starts_at is not null and o.starts_at < v_end and o.starts_at + make_interval(mins => coalesce(o.duration_minutes, 30)) > v_row.starts_at) then
        raise exception 'REDISTRIBUTION_OVERLAP: the longer session would overlap another timed task';
      end if;
    end if;
    update public.plan_blocks set duration_minutes = v_new, duration = v_new::text where id = v_row.id;
    v_out := v_out || jsonb_build_array(jsonb_build_object('task_id', v_row.id, 'title', v_row.title, 'date', v_row.local_date, 'before', v_row.duration_minutes, 'after', v_new));
    v_placed := v_placed + (v_c->>'add_minutes')::int;
  end loop;
  if v_placed = 0 then return jsonb_build_object('ok', true, 'replayed', false, 'placed', 0, 'changes', '[]'::jsonb); end if;
  insert into public.redistribution_receipts(user_id, cycle_id, source_task_id, source_minutes, placed_minutes, changes)
    values (p_user, v_src.cycle_id, p_source, v_src.duration_minutes, v_placed, v_out);
  return jsonb_build_object('ok', true, 'replayed', false, 'placed', v_placed, 'changes', v_out);
end $$;


--
-- Name: beta_invite_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.beta_invite_only() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select value from public.beta_settings where key = 'admission'), 'open') = 'invite_only'
$$;


--
-- Name: booking_refuse(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_refuse(p_title text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'SLOT_TAKEN' using errcode = 'BK409', detail = coalesce(p_title, 'Another booking');
end $$;


