-- Name: booking_tz(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_tz(p_user uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((select nullif(timezone, '') from public.profiles where id = p_user), 'UTC')
$$;


--
-- Name: bump_plan_block_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_plan_block_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Only a real content change advances the revision; re-writing identical
  -- values should not invalidate another session's read.
  if row(new.*) is distinct from row(old.*) then
    new.revision := old.revision + 1;
    new.updated_at := now();
  end if;
  return new;
end;
$$;


--
-- Name: cancel_item_batch(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_item_batch(p_batch uuid, p_reason text DEFAULT 'cancelled by operator'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_n int;
begin
  update public.item_batches set status = 'cancelled', finished_at = now(), last_error = left(p_reason, 300) where id = p_batch and status in ('queued', 'running');
  get diagnostics v_n = row_count;
  if v_n = 0 then return jsonb_build_object('ok', false, 'code', 'NOT_OPEN'); end if;
  update public.item_batch_cells set status = 'failed', lease_until = null, verdict = 'CANCELLED', defect_codes = array['CANCELLED'], failure_reason = coalesce(failure_reason, 'Batch cancelled before this cell finished.'), updated_at = now()
    where batch_id = p_batch and status in ('pending', 'running');
  update public.item_batch_attempts set outcome = 'cancelled', finished_at = now() where batch_id = p_batch and outcome is null;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: cancel_learning_sitting(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_learning_sitting(p_task_id text, p_expected_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid:=auth.uid(); v_task public.plan_blocks%rowtype; v_before jsonb;
begin
  if v_uid is null or not exists(select 1 from auth.users where id=v_uid and email_confirmed_at is not null)
    or not exists(select 1 from public.profiles where id=v_uid and onboarding_status='complete') then
    raise exception 'Complete verified setup first.' using errcode='42501';
  end if;
  select * into v_task from public.plan_blocks where id=p_task_id and user_id=v_uid for update;
  if not found or v_task.learning_activity_id is null then raise exception 'Learning log not found.' using errcode='P0002'; end if;
  if v_task.cancelled_at is not null then return jsonb_build_object('ok',true,'replayed',true); end if;
  if p_expected_revision is null or v_task.revision<>p_expected_revision then
    return jsonb_build_object('ok',false,'code','REVISION_MISMATCH','current',to_jsonb(v_task));
  end if;
  v_before:=to_jsonb(v_task);
  update public.plan_blocks set execution='cancelled',cancelled_at=now(),cancellation_reason='Removed learning log',revision=revision+1 where id=p_task_id;
  insert into public.task_events(user_id,task_id,event_type,payload,previous)
    values(v_uid,p_task_id,'cancelled','{"kind":"learning_log_removed"}',v_before);
  return jsonb_build_object('ok',true,'replayed',false);
end; $$;


--
-- Name: checkpoint_apply_choice(uuid, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_apply_choice(p_user uuid, p_week date, p_choice text, p_paper_action text, p_appt uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_paper jsonb; v_cancelled text;
begin
  if p_choice not in ('use_mock', 'keep_paper', 'later') then return jsonb_build_object('ok', false, 'code', 'INVALID_CHOICE'); end if;
  if p_choice = 'use_mock' then
    v_paper := public.checkpoint_week_paper(p_user, p_week);
    if v_paper is not null and v_paper <> 'null'::jsonb then
      if (v_paper->>'started')::boolean then return jsonb_build_object('ok', false, 'code', 'PAPER_STARTED'); end if;
      if coalesce(p_paper_action, '') <> 'replace' then return jsonb_build_object('ok', false, 'code', 'PAPER_DECISION_REQUIRED', 'paper', v_paper); end if;
      update public.plan_blocks set cancelled_at = now(), revision = revision + 1 where id = v_paper->>'taskId' and user_id = p_user and cancelled_at is null;
      insert into public.task_events (user_id, task_id, event_type, payload, previous)
        values (p_user, v_paper->>'taskId', 'cancelled', jsonb_build_object('reason', 'replaced_by_mock'), '{}'::jsonb);
      v_cancelled := v_paper->>'taskId';
    end if;
  end if;
  insert into public.cycle_assessment_choices (user_id, week_start, choice, decided_at, appointment_id) values (p_user, p_week, p_choice, now(), case when p_choice = 'use_mock' then p_appt end)
    on conflict (user_id, week_start) do update set choice = excluded.choice, decided_at = excluded.decided_at, appointment_id = excluded.appointment_id;
  return jsonb_build_object('ok', true, 'cancelledPaperTaskId', v_cancelled);
end $$;


--
-- Name: checkpoint_command(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_command(p_user uuid, p_key text, p_command text, p_hash text, p_args jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_rec public.checkpoint_commands%rowtype; v_a public.mock_appointments%rowtype; v_receipt jsonb; v_res jsonb;
  v_choice text; v_week date; v_task public.plan_blocks%rowtype; v_map public.checkpoint_suggestion_tasks%rowtype;
  v_new_id text; v_outcome_id uuid; v_next public.mock_appointments%rowtype; v_status text;
begin
  -- current-week serialization
  perform public.scope_lock(p_user);
  perform pg_advisory_xact_lock(hashtextextended('checkpoint:' || p_user::text, 0));
  select * into v_rec from public.checkpoint_commands where user_id = p_user and key = p_key;
  if found then
    if v_rec.payload_hash <> p_hash or v_rec.command <> p_command then return jsonb_build_object('ok', false, 'code', 'KEY_REUSED'); end if;
    return v_rec.receipt || jsonb_build_object('replayed', true);
  end if;
  perform 1 from public.profiles where id = p_user for update;
  if not found then raise exception 'no profile for user'; end if;
  select * into v_next from public.mock_appointments where user_id = p_user and status = 'planned' order by planned_date, created_at, id limit 1;

  -- Every command except add/keep/remove-related is made against a specific appointment and version.
  if p_command in ('save', 'cancel', 'choice', 'outcome', 'add_suggestion') then
    if (p_args->>'checkpointId') is null then
      if p_command <> 'save' then return jsonb_build_object('ok', false, 'code', 'NO_CHECKPOINT'); end if;
      if v_next.id is not null then return jsonb_build_object('ok', false, 'code', 'CHECKPOINT_CHANGED', 'currentId', v_next.id, 'currentVersion', v_next.version); end if;
    else
      select * into v_a from public.mock_appointments where id = (p_args->>'checkpointId')::uuid and user_id = p_user for update;
      if not found or v_a.status <> 'planned' or (p_args->>'expectedVersion')::int is distinct from v_a.version then
        return jsonb_build_object('ok', false, 'code', 'CHECKPOINT_CHANGED', 'currentId', v_next.id, 'currentVersion', v_next.version);
      end if;
    end if;
  end if;

  if p_command in ('save', 'add') then
    if v_a.id is not null and p_command = 'save' then
      if (v_a.kind = 'internal_rehearsal') is distinct from ((p_args->>'kind') = 'internal_rehearsal') then
        if exists (select 1 from public.mock_rehearsals r where r.appointment_id = v_a.id and r.status in ('ready', 'in_progress', 'complete')) then
          return jsonb_build_object('ok', false, 'code', 'KIND_LOCKED'); end if;
      end if;
      update public.mock_appointments set planned_date = (p_args->>'date')::date, kind = p_args->>'kind', label = nullif(p_args->>'label', ''),
        start_time = nullif(p_args->>'startTime', '')::time, duration_minutes = nullif(p_args->>'durationMinutes', '')::smallint where id = v_a.id returning * into v_a;
      if (p_args->>'oldWeekStart') is not null then
        delete from public.cycle_assessment_choices where user_id = p_user and week_start = (p_args->>'oldWeekStart')::date and (appointment_id = v_a.id or appointment_id is null);
      end if;
    else
      insert into public.mock_appointments (user_id, kind, planned_date, label, start_time, duration_minutes)
        values (p_user, p_args->>'kind', (p_args->>'date')::date, nullif(p_args->>'label', ''), nullif(p_args->>'startTime', '')::time, nullif(p_args->>'durationMinutes', '')::smallint) returning * into v_a;
    end if;
    update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user;
    v_receipt := jsonb_build_object('ok', true, 'command', p_command, 'checkpointId', v_a.id, 'version', v_a.version);

  elsif p_command = 'cancel' then
    if exists (select 1 from public.mock_rehearsals r where r.appointment_id = v_a.id and r.status = 'in_progress') then return jsonb_build_object('ok', false, 'code', 'REHEARSAL_STARTED'); end if;
    update public.mock_appointments set status = 'cancelled' where id = v_a.id;
    update public.mock_rehearsals set status = 'cancelled' where appointment_id = v_a.id and status = 'ready';
    delete from public.cycle_assessment_choices where user_id = p_user and week_start = (p_args->>'weekStart')::date and (appointment_id = v_a.id or appointment_id is null);
    update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user;
    v_receipt := jsonb_build_object('ok', true, 'command', 'cancel', 'cancelledId', v_a.id);

  elsif p_command = 'choice' then
    v_res := public.checkpoint_apply_choice(p_user, (p_args->>'weekStart')::date, p_args->>'choice', p_args->>'paperAction', v_a.id);
    if not (v_res->>'ok')::boolean then return v_res; end if;
    update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user;
    v_receipt := jsonb_build_object('ok', true, 'command', 'choice', 'choice', p_args->>'choice', 'weekStart', p_args->>'weekStart', 'appointmentId', v_a.id, 'cancelledPaperTaskId', v_res->>'cancelledPaperTaskId');

  elsif p_command = 'outcome' then
    v_week := (p_args->>'weekStart')::date;
    if p_args->>'outcome' not in ('taken', 'postponed', 'not_taken') then return jsonb_build_object('ok', false, 'code', 'INVALID_OUTCOME'); end if;
    if v_a.kind = 'internal_rehearsal' and p_args->>'outcome' = 'taken' then return jsonb_build_object('ok', false, 'code', 'INTERNAL_RESULT'); end if;
    if p_args->>'outcome' = 'taken' and ((p_args->>'actualDate') is null or (p_args->>'actualDate')::date > (p_args->>'today')::date) then
      return jsonb_build_object('ok', false, 'code', 'INVALID_ACTUAL_DATE'); end if;
    if p_args->>'outcome' <> 'taken' and (nullif(p_args->>'result', '') is not null or (p_args->>'actualDate') is not null) then
      return jsonb_build_object('ok', false, 'code', 'INVALID_RESULT'); end if;
    select choice into v_choice from public.cycle_assessment_choices where user_id = p_user and week_start = v_week and (appointment_id = v_a.id or appointment_id is null);
    if (p_args->>'choice') is not null and coalesce(v_choice, 'later') = 'later' then
      v_res := public.checkpoint_apply_choice(p_user, v_week, p_args->>'choice', p_args->>'paperAction', v_a.id);
      if not (v_res->>'ok')::boolean then return v_res; end if;
      v_choice := p_args->>'choice';
    end if;
    insert into public.mock_outcomes (user_id, checkpoint_id, planned_date, kind, label, outcome, reported_result, notes, actual_date, choice_at_record)
      values (p_user, v_a.id, v_a.planned_date, v_a.kind, v_a.label, p_args->>'outcome', nullif(p_args->>'result', ''), nullif(p_args->>'notes', ''), nullif(p_args->>'actualDate', '')::date, coalesce(v_choice, 'later'))
      returning id into v_outcome_id;
    if p_args->>'outcome' = 'postponed' and (p_args->>'newDate') is not null then
      update public.mock_appointments set planned_date = (p_args->>'newDate')::date where id = v_a.id;
    else
      v_status := case p_args->>'outcome' when 'taken' then 'completed' when 'postponed' then 'postponed' else 'missed' end;
      update public.mock_appointments set status = v_status where id = v_a.id;
      update public.mock_rehearsals set status = 'cancelled' where appointment_id = v_a.id and status = 'ready';
    end if;
    delete from public.cycle_assessment_choices where user_id = p_user and week_start = v_week and (appointment_id = v_a.id or appointment_id is null);
    update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user;
    v_receipt := jsonb_build_object('ok', true, 'command', 'outcome', 'outcomeId', v_outcome_id, 'outcome', p_args->>'outcome',
      'plannedDate', v_a.planned_date, 'choice', coalesce(v_choice, 'later'), 'moved', (p_args->>'outcome' = 'postponed' and (p_args->>'newDate') is not null));

  elsif p_command = 'add_suggestion' then
    select * into v_map from public.checkpoint_suggestion_tasks where user_id = p_user and checkpoint_id = v_a.id and suggestion_id = p_args->>'suggestionId';
    if found then
      select * into v_task from public.plan_blocks where id = v_map.task_id;
      if v_task.cancelled_at is null and v_task.execution <> 'cancelled' then
        v_receipt := jsonb_build_object('ok', true, 'command', 'add_suggestion', 'taskId', v_map.task_id, 'alreadyAdded', true);
        insert into public.checkpoint_commands (user_id, key, command, payload_hash, receipt) values (p_user, p_key, p_command, p_hash, v_receipt);
        return v_receipt;
      end if;
      delete from public.checkpoint_suggestion_tasks where user_id = p_user and checkpoint_id = v_a.id and suggestion_id = p_args->>'suggestionId';
    end if;
    v_new_id := 'ckpt-' || replace(gen_random_uuid()::text, '-', '');
    insert into public.plan_blocks (id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day, starts_at,
                                    duration_minutes, duration, rationale, is_protected_commitment, created_by)
      values (v_new_id, p_user, (p_args->>'cycleId')::uuid, p_args->>'title', coalesce(p_args->>'detail', ''), 'review', 'student', 'optional',
              case when nullif(p_args->>'startsAt', '') is null then 'day_preferred' else 'timed' end, 'not_started',
              (p_args->>'date')::date, (p_args->>'date')::date, nullif(p_args->>'startsAt', '')::timestamptz,
              (p_args->>'minutes')::smallint, p_args->>'minutes', 'You added this from your mock checkpoint suggestions.', false, 'student');
    insert into public.task_events (user_id, task_id, event_type, payload, previous)
      values (p_user, v_new_id, 'created', jsonb_build_object('source', 'checkpoint_suggestion', 'suggestion', p_args->>'suggestionId', 'checkpointId', v_a.id), '{}'::jsonb);
    insert into public.checkpoint_suggestion_tasks (user_id, checkpoint_id, suggestion_id, task_id, version_added)
      values (p_user, v_a.id, p_args->>'suggestionId', v_new_id, v_a.version);
    v_receipt := jsonb_build_object('ok', true, 'command', 'add_suggestion', 'taskId', v_new_id, 'alreadyAdded', false);

  elsif p_command = 'remove_related' then
    select m.* into v_map from public.checkpoint_suggestion_tasks m where m.user_id = p_user and m.task_id = p_args->>'taskId';
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_RELATED'); end if;
    select * into v_task from public.plan_blocks where id = v_map.task_id and user_id = p_user for update;
    if v_task.cancelled_at is not null then
      v_receipt := jsonb_build_object('ok', true, 'command', 'remove_related', 'taskId', v_task.id, 'alreadyRemoved', true);
    elsif v_task.execution not in ('not_started', 'deferred') then return jsonb_build_object('ok', false, 'code', 'TASK_STARTED');
    elsif v_task.revision is distinct from (p_args->>'expectedRevision')::int then return jsonb_build_object('ok', false, 'code', 'REVISION_MISMATCH');
    else
      update public.plan_blocks set cancelled_at = now(), revision = revision + 1 where id = v_task.id;
      insert into public.task_events (user_id, task_id, event_type, payload, previous)
        values (p_user, v_task.id, 'cancelled', jsonb_build_object('reason', 'checkpoint_changed'), '{}'::jsonb);
      v_receipt := jsonb_build_object('ok', true, 'command', 'remove_related', 'taskId', v_task.id, 'alreadyRemoved', false);
    end if;

  elsif p_command = 'keep_related' then
    update public.checkpoint_suggestion_tasks set reviewed_at = now() where user_id = p_user and task_id = p_args->>'taskId';
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_RELATED'); end if;
    v_receipt := jsonb_build_object('ok', true, 'command', 'keep_related', 'taskId', p_args->>'taskId');

  else
    return jsonb_build_object('ok', false, 'code', 'UNKNOWN_COMMAND');
  end if;

  insert into public.checkpoint_commands (user_id, key, command, payload_hash, receipt) values (p_user, p_key, p_command, p_hash, v_receipt);
  return v_receipt;
end $$;


--
-- Name: checkpoint_suggestion_tasks_basis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_suggestion_tasks_basis() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' or (new.reviewed_at is not null and new.reviewed_at is distinct from old.reviewed_at) then
    select a.planned_date into new.basis_date from public.mock_appointments a where a.id = new.checkpoint_id;
    if tg_op = 'UPDATE' and new.basis_date is null then new.basis_date := old.basis_date; end if;
  end if;
  return new;
end $$;


--
-- Name: checkpoint_week_paper(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_week_paper(p_user uuid, p_week_start date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((
    select jsonb_build_object(
      'taskId', b.id, 'revision', b.revision, 'cycleId', c.id,
      'started', (b.execution <> 'not_started' or b.attempt_id is not null or exists (
        select 1 from public.assessment_attempts a where a.user_id = p_user and a.cycle_id = c.id and a.attempt_kind = 'weekly')))
    from public.plan_blocks b join public.planning_cycles c on c.id = b.cycle_id
    where b.user_id = p_user and c.user_id = p_user and c.starts_at_local = p_week_start
      and b.task_type = 'diagnostic' and b.assessment_scope->>'kind' = 'weekly_paper' and b.cancelled_at is null and b.execution <> 'cancelled'
    order by b.local_date desc, b.id desc limit 1), 'null'::jsonb)
$$;


--
-- Name: claim_batch_cell(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_batch_cell(p_batch uuid, p_lease_seconds integer DEFAULT 600) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_b public.item_batches%rowtype; v_c public.item_batch_cells%rowtype; v_tok uuid := gen_random_uuid();
begin
  select * into v_b from public.item_batches where id = p_batch for update;
  if not found or v_b.status in ('cancelled', 'complete', 'failed', 'budget_exhausted') then return null; end if;
  if v_b.budget is not null and v_b.started_at is not null and coalesce((v_b.budget->>'wallSeconds')::int, 0) > 0
     and v_b.started_at + make_interval(secs => (v_b.budget->>'wallSeconds')::int) < now() then
    perform public._stop_batch_budget(p_batch, 'The batch wall-clock limit was reached.'); return null;
  end if;
  if v_b.budget is not null and coalesce((v_b.budget->>'maxRequests')::int, 0) > 0 and v_b.requests_reserved >= (v_b.budget->>'maxRequests')::int then
    perform public._stop_batch_budget(p_batch, 'The batch provider-request budget was used up.'); return null;
  end if;
  if v_b.status = 'queued' then update public.item_batches set status = 'running', started_at = now() where id = p_batch; end if;
  select * into v_c from public.item_batch_cells
    where batch_id = p_batch and attempts < v_b.max_attempts and (status = 'pending' or (status = 'running' and lease_until < now()))
    order by ordinal limit 1 for update skip locked;
  if not found then perform public._settle_batch(p_batch); return null; end if;
  update public.item_batch_attempts set outcome = 'lease_expired', finished_at = now() where batch_id = p_batch and ordinal = v_c.ordinal and outcome is null;
  update public.item_batch_cells set status = 'running', attempts = attempts + 1, claim_token = v_tok, lease_until = now() + make_interval(secs => p_lease_seconds), updated_at = now()
    where batch_id = p_batch and ordinal = v_c.ordinal returning * into v_c;
  insert into public.item_batch_attempts(batch_id, ordinal, attempt, claim_token) values (p_batch, v_c.ordinal, v_c.attempts, v_tok);
  return to_jsonb(v_c) || jsonb_build_object('claimToken', v_tok);
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: reminder_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reminder_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    ref_id text NOT NULL,
    job_key text NOT NULL,
    send_at timestamp with time zone NOT NULL,
    link text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    lease_until timestamp with time zone,
    last_error text,
    cancelled_reason text,
    sent_at timestamp with time zone,
    provider_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reminder_jobs_kind_check CHECK ((kind = ANY (ARRAY['assessment_upcoming'::text, 'weekly_review_ready'::text]))),
    CONSTRAINT reminder_jobs_link_check CHECK ((link ~~ '/app%'::text)),
    CONSTRAINT reminder_jobs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'cancelled'::text, 'failed'::text, 'uncertain'::text])))
);


--
-- Name: claim_reminder_jobs(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_reminder_jobs(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.reminder_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  update public.reminder_jobs j set status = 'sending', attempts = j.attempts + 1, lease_until = now() + make_interval(secs => p_lease_seconds), updated_at = now()
   where j.id in (select id from public.reminder_jobs where send_at <= now() and (status = 'pending' or (status = 'sending' and lease_until < now() and attempts < 3)) order by send_at limit p_limit for update skip locked)
  returning j.*;
end $$;


--
-- Name: coach_clear_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_clear_history(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_r int; v_m int;
begin
  perform pg_advisory_xact_lock(hashtextextended('coach_turn:' || p_user::text, 0));
  update public.coach_proposals set status = 'rejected', decided_at = now() where user_id = p_user and origin = 'coach' and status = 'pending';
  get diagnostics v_r = row_count;
  delete from public.coach_messages where user_id = p_user;
  get diagnostics v_m = row_count;
  return jsonb_build_object('rejected', v_r, 'deleted', v_m);
end $$;


--
-- Name: coach_model_reserve(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_model_reserve(p_user uuid, p_key text, p_token uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_n int; v_id bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended('coach_turn:' || p_user::text, 0));
  if not exists (select 1 from public.coach_messages where user_id = p_user and turn_key = p_key and role = 'student' and lease_token = p_token and lease_until > now()) then
    return jsonb_build_object('ok', false, 'reason', 'fenced');
  end if;
  select count(*) into v_n from public.coach_model_calls where user_id = p_user and created_at >= now() - interval '1 hour';
  if v_n >= p_limit then return jsonb_build_object('ok', false, 'reason', 'budget'); end if;
  insert into public.coach_model_calls (user_id, turn_key, token) values (p_user, p_key, p_token) returning id into v_id;
  return jsonb_build_object('ok', true, 'callId', v_id);
end $$;


--
-- Name: coach_model_settle(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_model_settle(p_user uuid, p_call bigint, p_state text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.coach_model_calls set state = p_state where id = p_call and user_id = p_user and state = 'reserved' and p_state in ('succeeded', 'failed', 'indeterminate');
$$;


--
-- Name: coach_turn_begin(uuid, text, text, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_turn_begin(p_user uuid, p_key text, p_body text, p_intent text, p_limit integer, p_hash text, p_lease_secs integer DEFAULT 45) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_s public.coach_messages%rowtype; v_c public.coach_messages%rowtype; v_n int; v_tok uuid := gen_random_uuid();
begin
  if p_key is null or char_length(p_key) not between 8 and 80 then raise exception 'bad turn key'; end if;
  if p_hash is null or char_length(p_hash) not between 8 and 128 then raise exception 'bad request hash'; end if;
  perform pg_advisory_xact_lock(hashtextextended('coach_turn:' || p_user::text, 0));
  select * into v_s from public.coach_messages where user_id = p_user and turn_key = p_key and role = 'student';
  if found then
    if v_s.request_hash is distinct from p_hash then return jsonb_build_object('state', 'conflict'); end if;
    select * into v_c from public.coach_messages where user_id = p_user and turn_key = p_key and role = 'coach';
    if found then return jsonb_build_object('state', 'replay', 'studentId', v_s.id, 'coachId', v_c.id); end if;
    if v_s.lease_until is not null and v_s.lease_until > now() then return jsonb_build_object('state', 'busy', 'studentId', v_s.id); end if;
    -- The previous worker's lease ran out: whatever it had in flight is unknowable, so it is recorded as indeterminate and fenced out.
    update public.coach_model_calls set state = 'indeterminate' where user_id = p_user and turn_key = p_key and state = 'reserved';
    update public.coach_messages set lease_token = v_tok, lease_until = now() + make_interval(secs => p_lease_secs) where id = v_s.id;
    return jsonb_build_object('state', 'resume', 'studentId', v_s.id, 'token', v_tok);
  end if;
  select count(*) into v_n from public.coach_messages where user_id = p_user and role = 'student' and created_at >= now() - interval '1 hour';
  if v_n >= p_limit then return jsonb_build_object('state', 'limited'); end if;
  insert into public.coach_messages (user_id, role, body, intent, turn_key, request_hash, lease_token, lease_until)
    values (p_user, 'student', left(p_body, 4000), p_intent, p_key, p_hash, v_tok, now() + make_interval(secs => p_lease_secs)) returning * into v_s;
  return jsonb_build_object('state', 'new', 'studentId', v_s.id, 'token', v_tok);
end $$;


--
-- Name: coach_turn_finish(uuid, text, uuid, text, text, jsonb, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coach_turn_finish(p_user uuid, p_key text, p_token uuid, p_body text, p_intent text, p_links jsonb, p_cycle uuid, p_proposals jsonb, p_meta jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_s public.coach_messages%rowtype; v_c public.coach_messages%rowtype; v_ids uuid[]; v_p jsonb; v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('coach_turn:' || p_user::text, 0));
  select * into v_c from public.coach_messages where user_id = p_user and turn_key = p_key and role = 'coach';
  if found then return jsonb_build_object('coachId', v_c.id, 'replayed', true); end if;
  select * into v_s from public.coach_messages where user_id = p_user and turn_key = p_key and role = 'student';
  if not found then return jsonb_build_object('error', 'NO_TURN'); end if;   -- cleared mid-turn: nothing is added
  if v_s.lease_token is distinct from p_token then return jsonb_build_object('error', 'FENCED'); end if;
  insert into public.coach_messages (user_id, role, body, intent, links, turn_key, turn_meta)
    values (p_user, 'coach', left(p_body, 4000), p_intent, coalesce(p_links, '[]'::jsonb), p_key, p_meta) returning * into v_c;
  v_ids := '{}';
  for v_p in select value from jsonb_array_elements(coalesce(p_proposals, '[]'::jsonb)) loop
    insert into public.coach_proposals (user_id, message_id, intent, kind, title, reasoning, proposed_changes, origin, status, target_cycle_id)
      values (p_user, v_c.id, v_p->>'kind', v_p->>'kind', v_p->>'title', v_p->>'reasoning', v_p->'changes', 'coach', 'pending', p_cycle) returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  update public.coach_messages set proposal_ids = v_ids where id = v_c.id;
  update public.coach_messages set lease_until = null where id = v_s.id;
  return jsonb_build_object('coachId', v_c.id, 'replayed', false);
end $$;


--
-- Name: commit_pulse_week(uuid, date, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_pulse_week(p_user_id uuid, p_starts_at_local date, p_ends_at_local date, p_timezone text, p_rows jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cycle_id uuid;
begin
  if auth.uid() is not null and auth.uid() <> p_user_id then
    raise exception 'Unauthorized';
  end if;

  select id into v_cycle_id
  from public.planning_cycles
  where user_id = p_user_id and status = 'active'
  for update;

  if v_cycle_id is null then
    v_cycle_id := gen_random_uuid();
    insert into public.planning_cycles (
      id, user_id, starts_at, ends_at, starts_at_local, ends_at_local, timezone, status
    ) values (
      v_cycle_id, p_user_id, now(), now() + interval '7 days',
      p_starts_at_local, p_ends_at_local, p_timezone, 'active'
    );
  else
    update public.planning_cycles
    set starts_at_local = p_starts_at_local, ends_at_local = p_ends_at_local, timezone = p_timezone
    where id = v_cycle_id;
  end if;

  insert into public.plan_blocks (
    id, user_id, cycle_id, title, detail, task_type, origin, priority,
    placement, execution, local_date, day, starts_at, duration_minutes, duration,
    lm_id, repair_thread_id, rationale, assessment_scope, created_by
  )
  select
    r->>'id', p_user_id, v_cycle_id, r->>'title', r->>'detail', r->>'task_type', r->>'origin',
    r->>'priority', r->>'placement', r->>'execution', (r->>'local_date')::date, (r->>'day')::date,
    nullif(r->>'starts_at', '')::timestamptz, (r->>'duration_minutes')::smallint, r->>'duration',
    nullif(r->>'lm_id', ''), nullif(r->>'repair_thread_id', '')::uuid, r->>'rationale',
    case when jsonb_typeof(r->'assessment_scope') = 'object' then r->'assessment_scope' end, r->>'created_by'
  from jsonb_array_elements(p_rows) as r;

  return json_build_object('cycle_id', v_cycle_id);
end;
$$;


--
-- Name: commitments_booking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commitments_booking_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m record; v_id uuid; v_user uuid; v_title text;
begin
  if tg_op = 'DELETE' then
    v_id := old.commitment_id; v_user := old.user_id;
  elsif tg_table_name = 'calendar_commitments' then
    v_id := new.id; v_user := new.user_id;
    if tg_op = 'UPDATE' and (old.status, old.recurrence, old.weekdays, old.start_time, old.end_time, old.starts_on, old.ends_on, old.starts_at, old.ends_at, old.is_protected, old.kind)
       is not distinct from (new.status, new.recurrence, new.weekdays, new.start_time, new.end_time, new.starts_on, new.ends_on, new.starts_at, new.ends_at, new.is_protected, new.kind) then return null; end if;
  else
    v_id := new.commitment_id; v_user := new.user_id;
  end if;
  perform public.scope_lock(v_user);
  for m in select * from public.mock_appointments a where a.user_id = v_user and a.status = 'planned' and a.start_time is not null and a.duration_minutes is not null loop
    select p.title into v_title from public.protected_occurrences(v_user, public.mock_booking_range(v_user, m.planned_date, m.start_time, m.duration_minutes)) p
     where p.source_id = v_id limit 1;
    if v_title is not null then
      raise exception 'SLOT_TAKEN' using errcode = 'BK409', detail = coalesce(nullif(m.label, ''), 'Your mock'), hint = v_title;
    end if;
  end loop;
  return null;
end $$;


--
-- Name: confirm_coach_move(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_coach_move(p_proposal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid(); v_p public.coach_proposals%rowtype; v_m jsonb; v_t public.plan_blocks%rowtype;
  v_tz text; v_today date; v_to date; v_starts timestamptz; v_cs date; v_ce date; v_ev uuid; v_placement text; v_stale text;
begin
  if v_uid is null then raise exception 'Sign in to confirm a suggestion.' using errcode = '42501'; end if;
  select * into v_p from public.coach_proposals where id = p_proposal_id and user_id = v_uid for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_p.status = 'executed' then return jsonb_build_object('ok', true, 'replayed', true, 'applied', 1, 'receipt', v_p.proposed_changes->'receipt'); end if;
  if v_p.status <> 'pending' then return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'not_pending'); end if;
  if v_p.kind <> 'move_task' or coalesce((v_p.proposed_changes->>'version')::int, 0) <> 3 then
    update public.coach_proposals set status = 'stale', decided_at = now() where id = p_proposal_id;
    return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'unreviewed_format');
  end if;
  v_m := v_p.proposed_changes->'move';
  v_to := (v_m->>'toDate')::date;
  v_starts := nullif(v_m->>'startsAt', '')::timestamptz;
  select * into v_t from public.plan_blocks where id = v_m->>'id' and user_id = v_uid for update;
  select coalesce(nullif(timezone, ''), 'UTC') into v_tz from public.profiles where id = v_uid;
  v_today := (now() at time zone v_tz)::date;
  v_stale := case
    when not found or v_t.revision <> (v_m->>'revision')::int then 'task_changed'
    when v_t.execution <> 'not_started' or v_t.is_protected_commitment or v_t.cancelled_at is not null or v_t.learning_activity_id is not null
      or v_t.task_type in ('diagnostic', 'recheck') then 'task_not_movable'
    when v_t.local_date is distinct from (v_m->>'fromDate')::date then 'task_changed'
    when exists (select 1 from public.plan_blocks s where s.continued_from_task_id = v_t.id) then 'continued'
    when v_to < v_today then 'past_day'
    when v_starts is not null and (v_starts at time zone v_tz)::date <> v_to then 'bad_slot'
  end;
  if v_stale is null and v_t.cycle_id is not null then
    select starts_at_local::date, ends_at_local::date into v_cs, v_ce from public.planning_cycles where id = v_t.cycle_id and user_id = v_uid;
    if v_cs is not null and (v_to < v_cs or v_to > v_ce) then v_stale := 'outside_cycle'; end if;
  end if;
  if v_stale is null and v_starts is not null and exists (
    select 1 from public.plan_blocks o where o.user_id = v_uid and o.id <> v_t.id and o.cancelled_at is null and o.starts_at is not null
      and o.execution not in ('skipped', 'deferred')
      and o.starts_at < v_starts + make_interval(mins => coalesce(v_t.duration_minutes, 30)) and o.starts_at + make_interval(mins => coalesce(o.duration_minutes, 30)) > v_starts) then
    v_stale := 'slot_taken';
  end if;
  if v_stale is not null then
    update public.coach_proposals set status = 'stale', decided_at = now() where id = p_proposal_id;
    return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', v_stale);
  end if;

  v_placement := case when v_starts is null then 'day_preferred' else 'timed' end;
  begin
    update public.plan_blocks set local_date = v_to, day = v_to, starts_at = v_starts, placement = v_placement where id = v_t.id and user_id = v_uid;
  exception when sqlstate 'BK409' then
    -- the protected-booking guard: the whole move is refused, nothing else was written yet
    update public.coach_proposals set status = 'stale', decided_at = now() where id = p_proposal_id;
    return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'protected_booking');
  end;
  insert into public.task_events (user_id, task_id, event_type, payload, previous, notes)
    values (v_uid, v_t.id, 'moved',
      jsonb_build_object('local_date', v_to, 'starts_at', v_starts, 'duration_minutes', v_t.duration_minutes, 'placement', v_placement),
      jsonb_build_object('local_date', v_t.local_date, 'starts_at', v_t.starts_at, 'duration_minutes', v_t.duration_minutes, 'placement', v_t.placement, 'execution', v_t.execution, 'revision', v_t.revision),
      'Moved on your confirmation from the Coach')
    returning id into v_ev;
  update public.coach_proposals set status = 'executed', executed_at = now(), decided_at = now(),
    proposed_changes = proposed_changes || jsonb_build_object('applied', 1, 'receipt', jsonb_build_object('kind', 'placement', 'taskId', v_t.id, 'eventId', v_ev,
      'toDate', v_to, 'startsAt', v_starts, 'placement', v_placement, 'at', now()))
   where id = p_proposal_id;
  return jsonb_build_object('ok', true, 'replayed', false, 'applied', 1,
    'receipt', jsonb_build_object('kind', 'placement', 'taskId', v_t.id, 'eventId', v_ev, 'toDate', v_to, 'startsAt', v_starts, 'placement', v_placement));
end $$;


--
-- Name: confirm_coach_proposal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_coach_proposal(p_proposal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_p public.coach_proposals%rowtype;
  v_moves jsonb; v_m jsonb; v_t public.plan_blocks%rowtype; v_res jsonb;
  v_events jsonb := '[]'::jsonb; v_n int := 0;
begin
  -- planning input serialization
  perform public.scope_lock(auth.uid());
  if v_uid is null then raise exception 'Sign in to confirm a suggestion.' using errcode = '42501'; end if;
  select * into v_p from public.coach_proposals where id = p_proposal_id and user_id = v_uid for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_p.status = 'executed' then
    return jsonb_build_object('ok', true, 'replayed', true, 'applied', coalesce((v_p.proposed_changes->>'applied')::int, 0), 'receipt', v_p.proposed_changes->'receipt');
  end if;
  if v_p.status <> 'pending' then return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'not_pending'); end if;
  -- Only a proposal that carries the task identities, revisions and dates the student reviewed can be applied.
  if v_p.kind <> 'defer_today' or coalesce((v_p.proposed_changes->>'version')::int, 1) < 2 then
    update public.coach_proposals set status = 'stale', decided_at = now() where id = p_proposal_id;
    return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'unreviewed_format');
  end if;
  v_moves := v_p.proposed_changes->'moves';
  if jsonb_typeof(v_moves) <> 'array' or jsonb_array_length(v_moves) = 0 or jsonb_array_length(v_moves) > 12 then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'reason', 'bad_moves');
  end if;

  -- Validate first, locking in a fixed order. Nothing is written unless every reviewed task is exactly as reviewed.
  for v_m in select value from jsonb_array_elements(v_moves) order by value->>'id' loop
    select * into v_t from public.plan_blocks where id = v_m->>'id' and user_id = v_uid for update;
    if not found or v_t.revision <> (v_m->>'revision')::int or v_t.execution <> 'not_started' or v_t.is_protected_commitment
       or v_t.cancelled_at is not null or v_t.learning_activity_id is not null
       or v_t.local_date is distinct from (v_m->>'date')::date
       or exists (select 1 from public.plan_blocks s where s.continued_from_task_id = v_t.id) then
      update public.coach_proposals set status = 'stale', decided_at = now() where id = p_proposal_id;
      return jsonb_build_object('ok', false, 'code', 'STALE', 'reason', 'task_changed', 'taskId', v_m->>'id');
    end if;
  end loop;

  -- Apply through the existing atomic execution command. Any failure raises and rolls back the whole proposal.
  for v_m in select value from jsonb_array_elements(v_moves) order by value->>'id' loop
    v_res := public.set_task_execution(v_uid, v_m->>'id', (v_m->>'revision')::int, 'deferred', null, 'Moved on your confirmation from the Coach');
    if coalesce((v_res->>'ok')::boolean, false) is not true then raise exception 'COACH_APPLY_FAILED for %', v_m->>'id' using errcode = 'P0001'; end if;
    v_events := v_events || jsonb_build_array(jsonb_build_object('taskId', v_m->>'id', 'eventId', v_res->>'eventId'));
    v_n := v_n + 1;
  end loop;

  update public.coach_proposals set status = 'executed', executed_at = now(), decided_at = now(),
    proposed_changes = proposed_changes || jsonb_build_object('applied', v_n, 'receipt', jsonb_build_object('events', v_events, 'at', now()))
   where id = p_proposal_id;
  return jsonb_build_object('ok', true, 'replayed', false, 'applied', v_n, 'receipt', jsonb_build_object('events', v_events));
end $$;


--
-- Name: confirm_item_difficulty(text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_item_difficulty(p_item_id text, p_expected_version integer, p_level text, p_rationale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_item public.assessment_items%rowtype; v_last record;
begin
  if auth.uid() is null or not public.is_item_reviewer() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can confirm a difficulty level.');
  end if;
  if p_level not in ('foundation', 'standard', 'difficult', 'stretch') then
    return jsonb_build_object('ok', false, 'code', 'BAD_LEVEL', 'message', 'Level must be foundation, standard, difficult or stretch.');
  end if;
  if char_length(btrim(coalesce(p_rationale, ''))) < 10 then
    return jsonb_build_object('ok', false, 'code', 'RATIONALE_REQUIRED', 'message', 'Say in a sentence what cognitive demand justifies this level.');
  end if;
  select * into v_item from public.assessment_items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown item.'); end if;
  if v_item.item_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'STALE_VERSION', 'message', 'This item changed after you opened it. Reload to see the current version.');
  end if;
  if v_item.review_status = 'deprecated' then return jsonb_build_object('ok', false, 'code', 'RETIRED', 'message', 'This item is retired.'); end if;
  select level, rationale into v_last from public.item_confirmed_difficulty where item_id = p_item_id and item_version = v_item.item_version;
  if found and v_last.level = p_level and v_last.rationale = btrim(p_rationale) then
    return jsonb_build_object('ok', true, 'repeated', true, 'itemId', p_item_id, 'version', v_item.item_version, 'level', p_level);
  end if;
  insert into public.item_difficulty_reviews(item_id, item_version, level, rationale, reviewer_id) values (p_item_id, v_item.item_version, p_level, btrim(p_rationale), auth.uid());
  return jsonb_build_object('ok', true, 'itemId', p_item_id, 'version', v_item.item_version, 'level', p_level);
end $$;


--
-- Name: confirm_item_family(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_item_family(p_item_id text, p_expected_version integer, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_item public.assessment_items%rowtype;
begin
  if v_uid is null or not public.is_item_reviewer() then return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can confirm a family.'); end if;
  if char_length(coalesce(btrim(p_note), '')) < 3 then return jsonb_build_object('ok', false, 'code', 'NOTE_REQUIRED', 'message', 'Say why this is its own construction.'); end if;
  select * into v_item from public.assessment_items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown item.'); end if;
  if v_item.item_version <> p_expected_version then return jsonb_build_object('ok', false, 'code', 'STALE_VERSION', 'message', 'This item changed after you opened it.'); end if;
  if v_item.family_id is null then return jsonb_build_object('ok', false, 'code', 'NO_FAMILY', 'message', 'This item has no family to confirm.'); end if;
  update public.item_families set construction_status = 'confirmed', confirmed_by = v_uid, confirmed_at = now() where id = v_item.family_id and construction_status = 'provisional';
  insert into public.item_revisions(item_id, item_version, kind, actor_id, summary) values (p_item_id, v_item.item_version, 'family', v_uid, 'Family confirmed: ' || btrim(p_note));
  return jsonb_build_object('ok', true, 'familyId', v_item.family_id);
end $$;


--
-- Name: confirm_task_scope(uuid, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_task_scope(p_user_id uuid, p_task_id text, p_expected_revision integer, p_outcome_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_task public.plan_blocks%rowtype;
  v_ids text[];
  v_old text[];
  v_before jsonb;
begin
  if auth.uid() is null or auth.uid() is distinct from p_user_id
    or not exists (select 1 from auth.users where id = auth.uid() and email_confirmed_at is not null)
    or not exists (select 1 from public.profiles where id = auth.uid() and onboarding_status = 'complete') then
    raise exception 'Verify your account and finish setup before confirming scope.' using errcode = '42501';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 or p_outcome_ids is null or cardinality(p_outcome_ids) > 40 or array_position(p_outcome_ids,null) is not null then
    raise exception 'Supply a valid revision and up to 40 learning outcomes.' using errcode = '22023';
  end if;
  select * into v_task from public.plan_blocks where id=p_task_id and user_id=p_user_id for update;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  if v_task.cancelled_at is not null or v_task.execution not in ('completed','partial')
    or not exists (select 1 from public.planning_cycles where id=v_task.cycle_id and user_id=p_user_id and status='active') then
    raise exception 'Confirm completed or partly completed work in your open cycle.' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct x order by x),'{}'::text[]) into v_ids from unnest(p_outcome_ids) as x;
  if exists (select 1 from unnest(v_ids) as x where not exists (
    select 1 from public.reading_los o where o.id=x and
      ((v_task.outcome_id is not null and o.id=v_task.outcome_id) or (v_task.outcome_id is null and o.reading_id=v_task.lm_id))
  )) then raise exception 'Choose only learning outcomes mapped to this task.' using errcode = '22023'; end if;
  select coalesce(array_agg(outcome_id order by outcome_id),'{}'::text[]) into v_old
    from public.block_scope_confirmations where user_id=p_user_id and block_id=p_task_id;
  if v_old = v_ids then return jsonb_build_object('ok',true,'task',to_jsonb(v_task),'confirmed',cardinality(v_ids),'replayed',true); end if;
  if v_task.revision <> p_expected_revision then
    return jsonb_build_object('ok',false,'code','REVISION_MISMATCH','current',to_jsonb(v_task));
  end if;
  v_before := to_jsonb(v_task) || jsonb_build_object('confirmed_outcomes',v_old);
  delete from public.block_scope_confirmations where block_id=p_task_id and user_id=p_user_id;
  insert into public.block_scope_confirmations(user_id,block_id,outcome_id) select p_user_id,p_task_id,x from unnest(v_ids) as x;
  update public.plan_blocks set revision=revision+1 where id=p_task_id and user_id=p_user_id returning * into v_task;
  insert into public.task_events(user_id,task_id,event_type,payload,previous) values
    (p_user_id,p_task_id,'details_changed',jsonb_build_object('kind','scope_confirmation','confirmed_outcomes',v_ids),v_before);
  return jsonb_build_object('ok',true,'task',to_jsonb(v_task),'confirmed',cardinality(v_ids),'replayed',false);
end; $$;


--
-- Name: create_beta_invitation(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_beta_invitation(p_email text, p_role text, p_days integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_email text := lower(btrim(p_email)); v_id uuid;
begin
  if p_role not in ('candidate', 'reviewer') or p_days not between 1 and 60 then return jsonb_build_object('ok', false, 'code', 'INVALID'); end if;
  update public.beta_invitations set status = 'revoked' where email = v_email and status = 'pending' and expires_at <= now();
  if exists (select 1 from public.beta_invitations where email = v_email and status in ('pending', 'accepted')) then return jsonb_build_object('ok', false, 'code', 'ALREADY_INVITED'); end if;
  insert into public.beta_invitations (email, role, expires_at, note) values (v_email, p_role, now() + make_interval(days => p_days), p_note) returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;


--
-- Name: create_item_batch(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_item_batch(p_request_key text, p_config_hash text, p_batch jsonb, p_cells jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_existing public.item_batches%rowtype; v_id uuid; v_n int; v_rights text := coalesce(p_batch->>'rights_status', 'unconfirmed');
begin
  if coalesce(btrim(p_request_key), '') = '' or coalesce(btrim(p_config_hash), '') = '' then return jsonb_build_object('ok', false, 'code', 'BAD_REQUEST'); end if;
  if jsonb_typeof(p_cells) <> 'array' or jsonb_array_length(p_cells) = 0 then return jsonb_build_object('ok', false, 'code', 'NO_CELLS'); end if;
  if v_rights = 'cleared' and coalesce(btrim(p_batch->>'rights_ref'), '') = '' then return jsonb_build_object('ok', false, 'code', 'RIGHTS_AUTHORITY_REQUIRED'); end if;
  perform pg_advisory_xact_lock(hashtext('batch:' || p_request_key));
  select * into v_existing from public.item_batches where request_key = p_request_key;
  if found then
    select count(*) into v_n from public.item_batch_cells where batch_id = v_existing.id;
    if v_existing.config_hash is distinct from p_config_hash then return jsonb_build_object('ok', false, 'code', 'KEY_CONFLICT', 'batchId', v_existing.id); end if;
    if v_n <> v_existing.requested_count then return jsonb_build_object('ok', false, 'code', 'INCOMPLETE_BATCH', 'batchId', v_existing.id); end if;
    return jsonb_build_object('ok', true, 'created', false, 'batchId', v_existing.id, 'cells', v_n);
  end if;
  insert into public.item_batches(request_key, label, manifest_id, curriculum_version, source_provenance, rights_status, rights_ref, prompt_version, model_versions,
      requested_count, max_attempts, config_hash, config, budget, parent_batch_id)
    values (p_request_key, p_batch->>'label', (p_batch->>'manifest_id')::uuid, p_batch->>'curriculum_version', coalesce(p_batch->'source_provenance', '{}'::jsonb), v_rights,
      nullif(btrim(p_batch->>'rights_ref'), ''), p_batch->>'prompt_version', coalesce(p_batch->'model_versions', '{}'::jsonb), jsonb_array_length(p_cells),
      coalesce((p_batch->>'max_attempts')::int, 2), p_config_hash, p_batch->'config', p_batch->'budget', nullif(p_batch->>'parent_batch_id', '')::uuid)
    returning id into v_id;
  insert into public.item_batch_cells(batch_id, ordinal, cell, status, verdict, defect_codes, failure_reason)
    select v_id, t.ord::int, t.cell,
      case when jsonb_array_length(coalesce(t.cell->'blocked', '[]'::jsonb)) > 0 then 'failed' else 'pending' end,
      case when jsonb_array_length(coalesce(t.cell->'blocked', '[]'::jsonb)) > 0 then 'BLOCKED' end,
      case when jsonb_array_length(coalesce(t.cell->'blocked', '[]'::jsonb)) > 0 then (select array_agg(x) from jsonb_array_elements_text(t.cell->'blocked') x) else '{}'::text[] end,
      case when jsonb_array_length(coalesce(t.cell->'blocked', '[]'::jsonb)) > 0 then left(coalesce(t.cell->>'blockedDetail', 'Grounding is missing or contradictory.'), 600) end
    from jsonb_array_elements(p_cells) with ordinality as t(cell, ord);
  if not exists (select 1 from public.item_batch_cells where batch_id = v_id and status = 'pending') then
    update public.item_batches set status = 'failed', finished_at = now(), last_error = 'Every cell was blocked before any provider call.' where id = v_id;
  end if;
  return jsonb_build_object('ok', true, 'created', true, 'batchId', v_id, 'cells', jsonb_array_length(p_cells));
end $$;


--
-- Name: current_week_available_minutes(uuid, date, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_week_available_minutes(p_user uuid, p_date date, p_zone text, p_now timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with ranges as (
  select coalesce(range_agg(int4range((extract(hour from start_time)*60+extract(minute from start_time))::int,
    (extract(hour from end_time)*60+extract(minute from end_time))::int,'[)')),'{}'::int4multirange) as available
  from public.availability_windows where user_id=p_user and status='active' and weekday=extract(dow from p_date)::int
), weekly as (
  select c.*, d.original_date, e.kind as exception_kind,e.new_date,e.new_start_time,e.new_end_time
  from public.calendar_commitments c
  cross join lateral (select p_date as original_date union select x.occurrence_date from public.commitment_exceptions x
    where x.commitment_id=c.id and x.user_id=p_user and x.kind='moved' and x.new_date=p_date) d
  left join public.commitment_exceptions e on e.commitment_id=c.id and e.occurrence_date=d.original_date and e.user_id=p_user
  where c.user_id=p_user and c.status='active' and c.is_protected and c.recurrence='weekly'
    and extract(dow from d.original_date)::int=any(c.weekdays)
    and (c.starts_on is null or d.original_date>=c.starts_on) and (c.ends_on is null or d.original_date<=c.ends_on)
    and c.start_time is not null and c.end_time is not null and coalesce(e.kind,'')<>'skipped'
), occurrences as (
  select coalesce(new_date,original_date) as day,
    (extract(hour from coalesce(new_start_time,start_time))*60+extract(minute from coalesce(new_start_time,start_time)))::int as start_min,
    case when exception_kind='moved' and new_end_time is not null
      then (extract(hour from new_end_time)*60+extract(minute from new_end_time))::int
      else (extract(hour from coalesce(new_start_time,start_time))*60+extract(minute from coalesce(new_start_time,start_time)))::int
        +greatest(15,(extract(epoch from (end_time-start_time))/60)::int) end as end_min
  from weekly
), blockers as (
  select int4range(greatest(0,start_min),least(1440,end_min),'[)') as span from occurrences where day=p_date and end_min>start_min
  union all
  select int4range(
    case when c.starts_at <= p_date::timestamp at time zone p_zone then 0
      else floor(extract(epoch from (c.starts_at at time zone p_zone)::time)/60)::int end,
    case when c.ends_at >= (p_date+1)::timestamp at time zone p_zone then 1440
      else ceil(extract(epoch from (c.ends_at at time zone p_zone)::time)/60)::int end,'[)')
  from public.calendar_commitments c where c.user_id=p_user and c.status='active' and c.is_protected and c.recurrence='none'
    and c.starts_at < (p_date+1)::timestamp at time zone p_zone and c.ends_at > p_date::timestamp at time zone p_zone
  union all
  select int4range((extract(hour from start_time)*60+extract(minute from start_time))::int,
    least(1440,(extract(hour from start_time)*60+extract(minute from start_time))::int+duration_minutes),'[)')
  from public.mock_appointments where user_id=p_user and planned_date=p_date and status='planned' and start_time is not null and duration_minutes>0
), free as (
  select available-coalesce((select range_agg(span) from blockers),'{}'::int4multirange) as spans from ranges
), remaining as (
  select spans * int4multirange(int4range(
    case when p_date>(p_now at time zone p_zone)::date then 0
      when p_date<(p_now at time zone p_zone)::date then 1440
      else least(1440,ceil(extract(epoch from (p_now at time zone p_zone)::time)/60)::int) end,1440,'[)')) as spans from free
)
select coalesce(sum(upper(r)-lower(r)),0)::int from remaining,lateral unnest(spans) r;
$$;


--
-- Name: current_week_proposal_problem(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_week_proposal_problem(p_user uuid, p_draft uuid, p_now timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d public.plan_drafts%rowtype; c public.planning_cycles%rowtype; v_today date; t jsonb; r record;
begin
  select * into d from public.plan_drafts where id=p_draft and user_id=p_user and purpose='current_week_plan';
  if not found then return 'NOT_FOUND'; end if;
  select * into c from public.planning_cycles where id=d.cycle_id and user_id=p_user;
  if not found or c.status<>'active' then return 'CYCLE_CHANGED'; end if;
  v_today := (p_now at time zone coalesce(c.timezone,'UTC'))::date;
  if c.ends_at_local<v_today then return 'CYCLE_ENDED'; end if;
  if (d.draft_json->>'planning_date')::date is distinct from v_today
    or d.cycle_start_date is distinct from c.starts_at_local or d.cycle_end_date is distinct from c.ends_at_local
    or d.timezone is distinct from coalesce(c.timezone,'UTC')
    or d.context_fingerprint is distinct from public.current_week_source_hash(p_user,c.id) then return 'STALE_PROPOSAL'; end if;
  if jsonb_typeof(d.draft_json->'tasks') is distinct from 'array' or jsonb_array_length(d.draft_json->'tasks')=0 then return 'INVALID_PROPOSAL'; end if;
  for t in select value from jsonb_array_elements(d.draft_json->'tasks') loop
    if (t->>'scheduled_date')::date is null or (t->>'scheduled_date')::date<c.starts_at_local or (t->>'scheduled_date')::date>c.ends_at_local
      or (t->>'scheduled_date')::date<v_today or coalesce((t->>'duration_minutes')::int,0)<=0 then return 'INVALID_PROPOSAL'; end if;
  end loop;
  for r in select (x->>'scheduled_date')::date as day,sum((x->>'duration_minutes')::int) as minutes
    from jsonb_array_elements(d.draft_json->'tasks') x where coalesce(x->'metadata'->>'task_type','study') not in ('diagnostic','mock','admin')
    group by (x->>'scheduled_date')::date loop
    if r.minutes>public.current_week_available_minutes(p_user,r.day,coalesce(c.timezone,'UTC'),p_now) then return 'STALE_PROPOSAL'; end if;
  end loop;
  return null;
exception when data_exception then return 'INVALID_PROPOSAL';
end $$;


--
-- Name: current_week_source_hash(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_week_source_hash(p_user uuid, p_cycle uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select md5(jsonb_build_object(
    'cycle', (select to_jsonb(c) from public.planning_cycles c where id=p_cycle and user_id=p_user),
    'profile', (select jsonb_build_array(onboarding_context_version,timezone,exam_date,exam_window_id,prep_mode,class_pattern,
        stage,max_session_minutes,classes_completed_at,week_availability_mode) from public.profiles where id=p_user),
    'plan_blocks', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.plan_blocks r where user_id=p_user), '[]'::jsonb),
    'task_events', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.task_events r where user_id=p_user), '[]'::jsonb),
    'calendar_commitments', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.calendar_commitments r where user_id=p_user), '[]'::jsonb),
    'commitment_exceptions', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.commitment_exceptions r where user_id=p_user), '[]'::jsonb),
    'availability_windows', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.availability_windows r where user_id=p_user), '[]'::jsonb),
    'class_sessions', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.class_sessions r where user_id=p_user), '[]'::jsonb),
    'user_module_state', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.user_module_state r where user_id=p_user), '[]'::jsonb),
    'user_topic_exposure', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.user_topic_exposure r where user_id=p_user), '[]'::jsonb),
    'user_entry_uncertainty', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.user_entry_uncertainty r where user_id=p_user), '[]'::jsonb),
    'block_scope_confirmations', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.block_scope_confirmations r where user_id=p_user), '[]'::jsonb),
    'repair_threads', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.repair_threads r where user_id=p_user), '[]'::jsonb),
    'evidence_events', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.evidence_events r where user_id=p_user), '[]'::jsonb),
    'assessment_attempts', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.assessment_attempts r where user_id=p_user), '[]'::jsonb),
    'mock_appointments', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.mock_appointments r where user_id=p_user), '[]'::jsonb),
    'study_roadmaps', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.study_roadmaps r where user_id=p_user), '[]'::jsonb),
    'exam_completion', coalesce((select jsonb_agg(to_jsonb(r) order by to_jsonb(r)::text) from public.exam_completion r where user_id=p_user), '[]'::jsonb),
    'class_items', coalesce((select jsonb_agg(to_jsonb(i) order by i.id) from public.class_session_items i
      join public.class_sessions c on c.id=i.session_id where c.user_id=p_user),'[]'::jsonb)
  )::text);
$$;


--
-- Name: decide_item_review(text, integer, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_item_review(p_item_id text, p_expected_version integer, p_decision text, p_note text DEFAULT ''::text, p_ack_disagreement boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_item public.assessment_items%rowtype;
  v_note text := coalesce(btrim(p_note), '');
  v_blockers text[] := '{}';
  v_prior text;
  v_validation_status text;
begin
  if v_uid is null or not public.is_item_reviewer() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can decide an item.');
  end if;
  if p_decision not in ('approve', 'reject', 'return', 'retire') then
    return jsonb_build_object('ok', false, 'code', 'BAD_DECISION', 'message', 'Decision must be approve, reject, return or retire.');
  end if;
  select * into v_item from public.assessment_items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown item.'); end if;

  select decision into v_prior from public.item_review_decisions
    where item_id = p_item_id and item_version = p_expected_version and decision in (p_decision) limit 1;
  if v_prior is not null then
    return jsonb_build_object('ok', true, 'repeated', true, 'itemId', p_item_id, 'decision', p_decision, 'status', v_item.review_status, 'version', v_item.item_version);
  end if;
  if v_item.item_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'STALE_VERSION', 'message', 'This item changed after you opened it. Reload to see the current version.');
  end if;
  select decision into v_prior from public.item_review_decisions
    where item_id = p_item_id and item_version = v_item.item_version and decision in ('approve', 'reject', 'return') limit 1;
  if v_prior is not null and p_decision <> 'retire' then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_DECIDED', 'message', 'This version already has a different decision (' || v_prior || ').');
  end if;
  if p_decision in ('reject', 'return', 'retire') and char_length(v_note) < 3 then
    return jsonb_build_object('ok', false, 'code', 'NOTE_REQUIRED', 'message', 'Say what is wrong. The reason is the record.');
  end if;

  if p_decision = 'approve' then
    v_blockers := public.item_publish_blockers(p_item_id, coalesce(p_ack_disagreement, false));
    if not exists (select 1 from public.item_confirmed_difficulty c where c.item_id = p_item_id and c.item_version = v_item.item_version) then
      v_blockers := v_blockers || 'A reviewer must confirm the difficulty level and give its rationale for this exact version.';
    end if;
    if array_length(v_blockers, 1) > 0 then
      return jsonb_build_object('ok', false, 'code', 'BLOCKED', 'message', 'Publication is blocked.', 'blockers', to_jsonb(v_blockers));
    end if;
  elsif p_decision in ('reject', 'return') then
    if v_item.review_status not in ('draft', 'verified') then
      return jsonb_build_object('ok', false, 'code', 'NOT_AWAITING_REVIEW', 'message', 'This item is "' || v_item.review_status || '"; only an unpublished item can be ' || p_decision || 'ed.');
    end if;
  else -- retire
    if v_item.review_status <> 'reviewed' then
      return jsonb_build_object('ok', false, 'code', 'NOT_PUBLISHED', 'message', 'Only a published item can be retired.');
    end if;
  end if;

  perform set_config('app.review_command', 'on', true);
  begin
    if p_decision = 'approve' then
      update public.assessment_items set review_status = 'reviewed', reviewed_at = now() where id = p_item_id;
      v_validation_status := 'PASS';
      if v_item.supersedes_item_id is not null then
        update public.assessment_items set review_status = 'deprecated', reviewed_at = coalesce(reviewed_at, now()) where id = v_item.supersedes_item_id and review_status <> 'deprecated';
        insert into public.item_revisions(item_id, item_version, kind, actor_id, summary)
          select id, item_version, 'superseded', v_uid, 'Replaced by ' || p_item_id from public.assessment_items where id = v_item.supersedes_item_id;
      end if;
    elsif p_decision = 'reject' or p_decision = 'retire' then
      update public.assessment_items set review_status = 'deprecated', reviewed_at = now() where id = p_item_id;
      v_validation_status := 'VOID';
    else -- return: the decision consumes this version; the corrected item is a new version
      update public.assessment_items set review_status = 'draft', verified_at = null, item_version = item_version + 1 where id = p_item_id;
      v_validation_status := 'REVISE';
    end if;

    insert into public.item_review_decisions(item_id, item_version, decision, reviewer_id, note, acknowledged_disagreement)
      values (p_item_id, v_item.item_version, p_decision, v_uid, v_note, coalesce(p_ack_disagreement, false));
    -- Kept so verifier-human agreement stays measurable from one table.
    insert into public.item_validations(item_id, reviewer_role, status, defect_codes, detail, item_version)
      values (p_item_id, 'human_reviewer', v_validation_status, case when p_decision = 'approve' then '{}'::text[] else array['HUMAN_' || upper(p_decision)] end,
              jsonb_build_object('decision', p_decision, 'note', v_note, 'reviewerId', v_uid, 'at', now()), v_item.item_version);
    insert into public.item_revisions(item_id, item_version, kind, actor_id, summary)
      values (p_item_id, v_item.item_version, case p_decision when 'approve' then 'approved' when 'reject' then 'rejected' when 'return' then 'returned' else 'retired' end, v_uid, v_note);
  exception when others then
    perform set_config('app.review_command', '', true);
    raise;
  end;
  perform set_config('app.review_command', '', true);

  return jsonb_build_object('ok', true, 'itemId', p_item_id, 'decision', p_decision,
    'status', (select review_status from public.assessment_items where id = p_item_id),
    'version', (select item_version from public.assessment_items where id = p_item_id));
end $$;


--
-- Name: derived_week_closing_day(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derived_week_closing_day(p_user uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_end date; v_day integer; v_zone text; v_next date; v_today date;
begin
  select ends_at_local into v_end from public.planning_cycles where user_id=p_user and status='active';
  if v_end is not null then return extract(dow from v_end)::int; end if;
  with days as (
    select distinct d::int as day from public.calendar_commitments c cross join lateral unnest(c.weekdays) d
    where c.user_id=p_user and c.kind='class' and c.status='active' and c.recurrence='weekly'
  ), gaps as (
    select day,coalesce(lag(day) over w,last_value(day) over (w rows between unbounded preceding and unbounded following)) as previous
    from days window w as (order by (day+6)%7)
  )
  select (day+6)%7 into v_day from gaps order by coalesce(nullif((day-previous+7)%7,0),7) desc,(day+6)%7 limit 1;
  if v_day is not null then return v_day; end if;
  select timezone into v_zone from public.profiles where id=p_user;
  v_zone:=coalesce(v_zone,'UTC'); v_today:=(now() at time zone v_zone)::date;
  select (starts_at at time zone v_zone)::date into v_next from public.calendar_commitments
    where user_id=p_user and kind='class' and status='active' and recurrence='none' and defines_cycle and starts_at>now()
    order by starts_at limit 1;
  if v_next-v_today between 2 and 13 then return extract(dow from v_next-1)::int; end if;
  return 0;
end $$;


--
-- Name: difficulty_evidence_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.difficulty_evidence_version(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(
    coalesce((select count(*) filter (where validity = 'valid') || ':' || count(*) filter (where validity <> 'valid') || ':' || coalesce(max(created_at)::text, '')
                from public.evidence_events where user_id = p_user and evidence_mode = 'evidence'), '')
    || '|' || coalesce((select count(*) || ':' || coalesce(max(result_revision), 0) || ':' || coalesce(max(completed_at)::text, '')
                from public.assessment_attempts where user_id = p_user and attempt_kind in ('weekly', 'reading', 'subject') and status in ('scored', 'rescored', 'partially_voided')), ''))
$$;


--
-- Name: dismiss_current_week_plan(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_current_week_plan(p_draft_id uuid, p_expected_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_user uuid:=auth.uid(); d public.plan_drafts%rowtype; v_problem text;
begin
  if v_user is null or not exists(select 1 from auth.users where id=v_user and email_confirmed_at is not null)
    or not exists(select 1 from public.profiles where id=v_user and onboarding_status='complete')
    or not public.is_beta_admitted(v_user) then raise exception 'Application access required' using errcode='42501'; end if;
  perform public.scope_lock(v_user);
  select * into d from public.plan_drafts where id=p_draft_id and user_id=v_user and purpose='current_week_plan' for update;
  if not found then return jsonb_build_object('ok',false,'code','NOT_FOUND'); end if;
  if d.status='accepted' then return jsonb_build_object('ok',true,'outcome','accepted','receipt',d.draft_json->'receipt'); end if;
  if d.status='discarded' then return jsonb_build_object('ok',true,'outcome','already_dismissed'); end if;
  if d.status<>'ready' or d.revision is distinct from p_expected_revision then return jsonb_build_object('ok',false,'code','STALE_PROPOSAL'); end if;
  v_problem:=public.current_week_proposal_problem(v_user,p_draft_id,clock_timestamp());
  if v_problem is not null then return jsonb_build_object('ok',false,'code',v_problem); end if;
  update public.plan_drafts set status='discarded',revision=revision+1,updated_at=now() where id=d.id;
  return jsonb_build_object('ok',true,'outcome','dismissed');
end $$;


--
-- Name: edit_item(text, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_item(p_item_id text, p_expected_version integer, p_patch jsonb, p_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_item public.assessment_items%rowtype;
  v_new_id text; v_base text; v_existing text; v_new_version int;
  v_options jsonb; v_stem text; v_key int; v_outcome text; v_lm text; v_new_mode boolean;
  v_note text := coalesce(btrim(p_note), '');
begin
  if v_uid is null or not public.is_item_reviewer() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can edit an item.');
  end if;
  select * into v_item from public.assessment_items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown item.'); end if;
  if v_item.item_version <> p_expected_version then
    return jsonb_build_object('ok', false, 'code', 'STALE_VERSION', 'message', 'This item changed after you opened it. Reload to see the current version.');
  end if;
  if v_item.review_status = 'deprecated' then
    return jsonb_build_object('ok', false, 'code', 'RETIRED', 'message', 'A retired item cannot be edited.');
  end if;

  v_options := case when p_patch ? 'options' then p_patch->'options' else v_item.options end;
  v_stem := case when p_patch ? 'stem' then btrim(p_patch->>'stem') else v_item.stem end;
  v_key := case when p_patch ? 'key_index' then (p_patch->>'key_index')::int else v_item.key_index end;
  if char_length(coalesce(v_stem, '')) < 20 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'message', 'The question text is too short.'); end if;
  if jsonb_typeof(v_options) <> 'array' or jsonb_array_length(v_options) <> 3
     or (select count(distinct lower(btrim(o))) from jsonb_array_elements_text(v_options) o) <> 3
     or (select count(*) from jsonb_array_elements_text(v_options) o where btrim(o) = '') > 0 then
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'message', 'A question needs exactly three distinct, non-empty options.');
  end if;
  if v_key is null or v_key not between 0 and 2 then return jsonb_build_object('ok', false, 'code', 'INVALID', 'message', 'Choose which option is correct.'); end if;
  v_outcome := case when p_patch ? 'outcome_id' then nullif(p_patch->>'outcome_id', '') else v_item.outcome_id end;
  v_lm := v_item.lm_id;
  if p_patch ? 'outcome_id' and v_outcome is not null then
    select reading_id into v_lm from public.reading_los where id = v_outcome;
    if v_lm is null then return jsonb_build_object('ok', false, 'code', 'INVALID', 'message', 'That outcome does not exist.'); end if;
  end if;

  v_new_mode := v_item.review_status = 'reviewed'
    or exists (select 1 from public.assessment_responses r where r.item_id = p_item_id)
    or exists (select 1 from public.form_items f where f.item_id = p_item_id);
  v_new_version := v_item.item_version + 1;

  perform set_config('app.review_command', 'on', true);
  if v_new_mode then
    select id into v_existing from public.assessment_items where supersedes_item_id = p_item_id and review_status <> 'deprecated' limit 1;
    if v_existing is not null then
      perform set_config('app.review_command', '', true);
      return jsonb_build_object('ok', false, 'code', 'SUCCESSOR_EXISTS', 'message', 'A newer candidate version of this item already exists.', 'itemId', v_existing);
    end if;
    v_base := regexp_replace(p_item_id, '-v[0-9]+$', '');
    v_new_id := v_base || '-v' || v_new_version;
    insert into public.assessment_items(id, lm_id, learning_objective, verification_intent, difficulty, stem, options, per_option_feedback, provenance,
        review_status, concept_id, cognition, item_form, intended_difficulty, item_version, key_index, item_card, semantic_fingerprint, generator_model, outcome_id,
        family_id, held_out, supersedes_item_id)
      values (v_new_id, v_lm, v_item.learning_objective, v_item.verification_intent, v_item.difficulty, v_stem, v_options,
        case when p_patch ? 'per_option_feedback' then p_patch->'per_option_feedback' else v_item.per_option_feedback end,
        coalesce(v_item.provenance, '') || ' (revised from ' || p_item_id || ')', 'draft',
        case when p_patch ? 'concept_id' then nullif(p_patch->>'concept_id', '')::uuid else v_item.concept_id end,
        coalesce(p_patch->>'cognition', v_item.cognition), coalesce(p_patch->>'item_form', v_item.item_form), coalesce(p_patch->>'intended_difficulty', v_item.intended_difficulty),
        v_new_version, v_key, case when p_patch ? 'item_card' then p_patch->'item_card' else v_item.item_card end,
        p_patch->>'semantic_fingerprint', v_item.generator_model, v_outcome, v_item.family_id, v_item.held_out, p_item_id);
    insert into public.item_revisions(item_id, item_version, kind, actor_id, summary, snapshot)
      values (v_new_id, v_new_version, 'new_version', v_uid, coalesce(nullif(v_note, ''), 'New candidate version of ' || p_item_id),
              (select to_jsonb(i) - 'item_card' from public.assessment_items i where i.id = v_new_id));
    perform set_config('app.review_command', '', true);
    return jsonb_build_object('ok', true, 'mode', 'new_version', 'itemId', v_new_id, 'version', v_new_version, 'supersedes', p_item_id);
  end if;

  update public.assessment_items set
    stem = v_stem, options = v_options, key_index = v_key, lm_id = v_lm, outcome_id = v_outcome,
    per_option_feedback = case when p_patch ? 'per_option_feedback' then p_patch->'per_option_feedback' else per_option_feedback end,
    item_card = case when p_patch ? 'item_card' then p_patch->'item_card' else item_card end,
    concept_id = case when p_patch ? 'concept_id' then nullif(p_patch->>'concept_id', '')::uuid else concept_id end,
    cognition = coalesce(p_patch->>'cognition', cognition), item_form = coalesce(p_patch->>'item_form', item_form),
    intended_difficulty = coalesce(p_patch->>'intended_difficulty', intended_difficulty),
    semantic_fingerprint = coalesce(p_patch->>'semantic_fingerprint', semantic_fingerprint),
    item_version = v_new_version, review_status = 'draft', verified_at = null
    where id = p_item_id;
  insert into public.item_revisions(item_id, item_version, kind, actor_id, summary, snapshot)
    values (p_item_id, v_new_version, 'edited', v_uid, v_note, (select to_jsonb(i) - 'item_card' from public.assessment_items i where i.id = p_item_id));
  perform set_config('app.review_command', '', true);
  return jsonb_build_object('ok', true, 'mode', 'in_place', 'itemId', p_item_id, 'version', v_new_version);
end $_$;


--
-- Name: enforce_beta_invitation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_beta_invitation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if public.beta_invite_only() and not exists (
    select 1 from public.beta_invitations i where i.email = lower(btrim(new.email)) and (i.status = 'accepted' or (i.status = 'pending' and i.expires_at > now()))) then
    raise exception 'NOT_INVITED: this email has no valid beta invitation' using errcode = 'P0001';
  end if;
  return new;
end $$;


--
-- Name: extend_batch_cell(uuid, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_batch_cell(p_batch uuid, p_ordinal integer, p_claim uuid, p_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_n int;
begin
  update public.item_batch_cells c set lease_until = now() + make_interval(secs => least(greatest(p_seconds, 1), 900)), updated_at = now()
    from public.item_batches b where c.batch_id = p_batch and c.ordinal = p_ordinal and c.claim_token = p_claim and c.status = 'running' and b.id = c.batch_id and b.status = 'running';
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', v_n = 1, 'code', case when v_n = 1 then null else 'STALE_CLAIM' end);
end $$;


--
-- Name: fail_batch_cell(uuid, integer, uuid, text, text[], text, jsonb, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_batch_cell(p_batch uuid, p_ordinal integer, p_claim uuid, p_reason text, p_codes text[], p_verdict text, p_usage jsonb, p_ms integer, p_reject jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_c public.item_batch_cells%rowtype; v_b public.item_batches%rowtype;
begin
  select * into v_b from public.item_batches where id = p_batch for share;
  select * into v_c from public.item_batch_cells where batch_id = p_batch and ordinal = p_ordinal for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_c.claim_token is distinct from p_claim then
    update public.item_batch_attempts set outcome = 'stale_refused', finished_at = now() where batch_id = p_batch and ordinal = p_ordinal and claim_token = p_claim and outcome is null;
    return jsonb_build_object('ok', false, 'code', 'STALE_CLAIM');
  end if;
  if v_c.status <> 'running' then return jsonb_build_object('ok', false, 'code', 'NOT_RUNNING'); end if;
  if p_reject is not null then
    insert into public.rejected_item_drafts(concept_id, blueprint_cell, draft, verifier_status, defect_codes, reason, generator_model, verifier_model, stage)
      values ((p_reject->>'concept_id')::uuid, p_reject->'blueprint_cell', p_reject->'draft', p_reject->>'verifier_status', coalesce(p_codes, '{}'), left(p_reason, 600),
              p_reject->>'generator_model', p_reject->>'verifier_model', coalesce(p_reject->>'stage', 'verification'));
  end if;
  update public.item_batch_cells set status = case when attempts >= v_b.max_attempts or v_b.status in ('cancelled', 'budget_exhausted') then 'failed' else 'pending' end, lease_until = null,
    failure_reason = left(p_reason, 600), defect_codes = coalesce(p_codes, '{}'), verdict = p_verdict, generate_ms = p_ms, provider_usage = p_usage, updated_at = now()
    where batch_id = p_batch and ordinal = p_ordinal;
  update public.item_batch_attempts set outcome = 'failed', code = p_verdict, finished_at = now(), ms = p_ms, usage = p_usage where batch_id = p_batch and ordinal = p_ordinal and claim_token = p_claim;
  perform public._settle_batch(p_batch);
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: finalize_assessment_attempt(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_assessment_attempt(p_attempt_id uuid, p_scoring_policy text, p_evidence_policy text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid;
  v_attempt record;
  v_response record;
  v_item record;
  v_total int := 0;
  v_correct int := 0;
  v_score int;
  v_evidence_written int := 0;
  v_evidence_mode text;
  v_evidence_state text;
  v_error_code text;
  v_trust_tier text;
  v_diagnoses jsonb;
  v_manifest_id uuid;
  v_purpose text;
  v_is_check boolean;
  v_concept record;
  v_thread record;
  v_state text;
  v_check_state text;
  v_policy jsonb := public.repair_resolution_policy();
  v_pol text;
  v_paper boolean;
  v_delivered int;
  v_answered int := 0;
  v_answered_correct int := 0;
  v_voided int := 0;
begin
  v_user_id := auth.uid();
  if v_user_id is null then raise exception 'Unauthorized'; end if;

  select * into v_attempt from public.assessment_attempts
  where id = p_attempt_id and user_id = v_user_id for update;
  if v_attempt is null then raise exception 'Attempt not found'; end if;

  if v_attempt.status = 'scored' then
    return json_build_object('ok', true, 'alreadyScored', true, 'score', v_attempt.score, 'evidenceWritten', 0)::jsonb;
  end if;

  -- The RESERVED FORM owns the scoring policy. The caller's argument cannot choose a more favourable one.
  select coalesce(f.scoring_policy, '1.0') into v_pol from public.assessment_forms f where f.id = v_attempt.form_id;
  v_pol := coalesce(v_pol, '1.0');
  v_paper := v_pol = 'paper-score.1';

  select count(distinct c.item_id) into v_voided from public.item_challenges c where c.attempt_id = p_attempt_id and c.user_id = v_user_id and c.status = 'resolved_voided'
    and exists (select 1 from public.form_items fi where fi.form_id = v_attempt.form_id and fi.item_id = c.item_id);
  for v_response in select * from public.assessment_responses where attempt_id = p_attempt_id
      and item_id not in (select c.item_id from public.item_challenges c where c.attempt_id = p_attempt_id and c.status = 'resolved_voided') loop
    v_total := v_total + 1;
    if v_response.is_correct then v_correct := v_correct + 1; end if;
    if v_response.selected_option_index is not null then
      v_answered := v_answered + 1;
      if v_response.is_correct then v_answered_correct := v_answered_correct + 1; end if;
    end if;
  end loop;
  if v_paper then
    -- paper-score.1: correct over DELIVERED form items. An omission earns no mark and is not evidence of a miss.
    select count(*) into v_delivered from public.form_items where form_id = v_attempt.form_id;
    v_total := v_answered; v_correct := v_answered_correct;
    v_score := case when v_delivered - v_voided > 0 then round((v_correct::numeric / greatest(v_delivered - v_voided, 1)::numeric) * 100) else null end;
  else
    if v_total = 0 then raise exception 'No responses found'; end if;
    v_delivered := v_total;
    v_score := round((v_correct::numeric / v_total::numeric) * 100);
  end if;

  v_evidence_mode := 'evidence';
  if v_attempt.attempt_kind = 'practice' then v_evidence_mode := 'practice'; end if;
  for v_item in select ai.id, ai.review_status from public.assessment_items ai join public.assessment_responses ar on ai.id = ar.item_id where ar.attempt_id = p_attempt_id loop
    if not (v_item.review_status = 'reviewed' or exists (select 1 from public.item_review_decisions d where d.item_id = v_item.id and d.decision = 'approve')) then v_evidence_mode := 'practice'; end if;
  end loop;

  if v_paper then
    -- An item the student never answered is still on the form: its trust tier decides whether the paper can be evidence.
    for v_item in select ai.id, ai.review_status from public.form_items fi join public.assessment_items ai on ai.id = fi.item_id where fi.form_id = v_attempt.form_id loop
      if not (v_item.review_status = 'reviewed' or exists (select 1 from public.item_review_decisions d where d.item_id = v_item.id and d.decision = 'approve')) then v_evidence_mode := 'practice'; end if;
    end loop;
  end if;

  update public.assessment_attempts set
    delivered_count = v_delivered, omitted_count = greatest(v_delivered - v_voided - v_total, 0), scoreable_count = case when v_paper then v_delivered - v_voided else v_total end,
    status = 'scored', score = v_score, completed_at = coalesce(completed_at, now()), evidence_mode = v_evidence_mode,
    scoring_policy_version = v_pol, evidence_policy_version = p_evidence_policy,
    valid_response_count = v_total, correct_response_count = v_correct
  where id = p_attempt_id;

  if v_attempt.form_id is not null then
    select b.manifest_id, b.purpose into v_manifest_id, v_purpose
      from public.assessment_forms f join public.assessment_blueprints b on b.id = f.blueprint_id where f.id = v_attempt.form_id;
  end if;
  if v_manifest_id is null then select id into v_manifest_id from public.curriculum_manifests where is_active = true limit 1; end if;
  v_is_check := coalesce(v_purpose, '') = 'repair_recheck';

  if v_evidence_mode = 'evidence' then
    for v_response in select ar.*, ai.concept_id, ai.item_card, ai.review_status from public.assessment_responses ar join public.assessment_items ai on ar.item_id = ai.id where ar.attempt_id = p_attempt_id
          and ar.item_id not in (select c.item_id from public.item_challenges c where c.attempt_id = p_attempt_id and c.status = 'resolved_voided') loop
      if v_response.concept_id is not null then
        v_evidence_state := 'insufficient';
        if v_response.is_correct = false then v_evidence_state := 'needs_repair';
        elsif v_response.is_correct = true and v_response.self_reported_confidence is not null and v_response.self_reported_confidence <= 2 then v_evidence_state := 'unstable';
        elsif v_response.is_correct = true then v_evidence_state := 'supported'; end if;

        v_error_code := null;
        if v_response.is_correct = false then
          begin
            v_diagnoses := v_response.item_card->'distractorDiagnoses';
            select obj->>'errorCode' into v_error_code from jsonb_array_elements(v_diagnoses) obj where (obj->>'optionIndex')::int = v_response.selected_option_index limit 1;
          exception when others then v_error_code := null; end;
        end if;
        v_trust_tier := v_response.review_status;

        insert into public.evidence_events (
          user_id, attempt_id, item_id, concept_id, validity, is_correct, evidence_state, error_code, response_id, assessment_purpose, evidence_mode, item_trust_tier, self_reported_confidence, scoring_policy_version
        ) values (
          v_user_id, p_attempt_id, v_response.item_id, v_response.concept_id, 'valid', v_response.is_correct, v_evidence_state, v_error_code, v_response.id, coalesce(v_purpose, 'practice'), v_evidence_mode, v_trust_tier, v_response.self_reported_confidence, v_pol
        ) on conflict (attempt_id, item_id, scoring_policy_version) do nothing;
        v_evidence_written := v_evidence_written + 1;
      end if;
    end loop;

    update public.evidence_events e set validity = 'disputed', validity_reason = 'challenge_pending'
      where e.attempt_id = p_attempt_id and e.user_id = v_user_id and e.validity = 'valid'
        and e.item_id in (select c.item_id from public.item_challenges c where c.attempt_id = p_attempt_id and c.status = 'pending');
    -- ONE decision per concept per paper. Several wrong answers on a concept in the same paper are one episode.
    for v_concept in
      select e.concept_id, count(*) as n,
             bool_or(e.evidence_state = 'needs_repair') as miss, bool_or(e.evidence_state = 'unstable') as unstable
      from public.evidence_events e
      where e.attempt_id = p_attempt_id and e.user_id = v_user_id and e.validity = 'valid'
      group by e.concept_id
    loop
      v_state := case when v_concept.miss then 'needs_repair' when v_concept.unstable then 'unstable' else 'supported' end;
      select * into v_thread from public.repair_threads t
        where t.user_id = v_user_id and t.concept_id = v_concept.concept_id and t.manifest_id = v_manifest_id
          and t.status not in ('closed', 'cancelled', 'superseded') for update;

      if v_state in ('needs_repair', 'unstable') then
        v_check_state := case when v_state = 'needs_repair' then 'still_needs_work' else 'uncertain' end;
        if v_thread.id is null then
          insert into public.repair_threads (user_id, concept_id, manifest_id, status, severity, occurrence_count, opened_from_attempt_id, latest_evidence_at, updated_at, policy_version, latest_attempt_id)
            values (v_user_id, v_concept.concept_id, v_manifest_id, 'open', v_state, 1, p_attempt_id, now(), now(), p_evidence_policy, p_attempt_id)
            returning * into v_thread;
          insert into public.repair_thread_events(thread_id, event_type, details)
            values (v_thread.id, 'opened', jsonb_build_object('attemptId', p_attempt_id, 'state', v_state, 'questions', v_concept.n));
        elsif v_thread.latest_attempt_id is distinct from p_attempt_id then
          update public.repair_threads set
            severity = v_state, occurrence_count = occurrence_count + 1, latest_evidence_at = now(), updated_at = now(),
            revision = revision + 1, latest_attempt_id = p_attempt_id,
            status = case when status = 'awaiting_recheck' then 'open' else status end,
            -- A check's verdict describes the evidence at that time. Newer evidence from an ordinary paper retires it,
            -- so an older "supported" can never sit beside a newer miss.
            latest_check_state = case when v_is_check then v_check_state else null end,
            latest_check_attempt_id = case when v_is_check then p_attempt_id else null end,
            latest_check_at = case when v_is_check then now() else null end
          where id = v_thread.id;
          insert into public.repair_thread_events(thread_id, event_type, details)
            values (v_thread.id, case when v_is_check then 'check_' || v_check_state else 'new_evidence' end,
                    jsonb_build_object('attemptId', p_attempt_id, 'state', v_state, 'questions', v_concept.n));
        end if;
      elsif v_is_check and v_thread.id is not null and v_thread.status = 'awaiting_recheck' then
        -- Supported on THIS check. It is recorded; it does not close the gap unless the policy says how many answers resolve one.
        update public.repair_threads set latest_check_state = 'supported', latest_check_attempt_id = p_attempt_id, latest_check_at = now(),
          updated_at = now(), revision = revision + 1,
          status = case when coalesce((v_policy->>'autoClose')::boolean, false) and v_concept.n >= coalesce((v_policy->>'minValidQuestions')::int, 2147483647) then 'closed' else status end,
          closed_at = case when coalesce((v_policy->>'autoClose')::boolean, false) and v_concept.n >= coalesce((v_policy->>'minValidQuestions')::int, 2147483647) then now() else closed_at end,
          closure_reason = case when coalesce((v_policy->>'autoClose')::boolean, false) and v_concept.n >= coalesce((v_policy->>'minValidQuestions')::int, 2147483647) then 'supported_on_check:' || (v_policy->>'version') else closure_reason end
        where id = v_thread.id;
        insert into public.repair_thread_events(thread_id, event_type, details)
          values (v_thread.id, 'check_supported', jsonb_build_object('attemptId', p_attempt_id, 'questions', v_concept.n, 'policy', v_policy->>'version'));
      end if;
    end loop;

    -- A re-check names the repairs it was for. One it could not assess stays open and says so; it is never closed by omission.
    if v_is_check then
      for v_thread in
        select t.* from public.repair_threads t
        join public.repair_check_threads l on l.thread_id = t.id
        join public.plan_blocks b on b.id = l.check_task_id and b.attempt_id = p_attempt_id
        where t.user_id = v_user_id and t.status not in ('closed', 'cancelled', 'superseded')
          and not exists (select 1 from public.evidence_events e where e.attempt_id = p_attempt_id and e.concept_id = t.concept_id and e.validity = 'valid')
        for update of t
      loop
        update public.repair_threads set latest_check_state = 'not_assessed', latest_check_attempt_id = p_attempt_id, latest_check_at = now(), updated_at = now(), revision = revision + 1 where id = v_thread.id;
        insert into public.repair_thread_events(thread_id, event_type, details) values (v_thread.id, 'check_not_assessed', jsonb_build_object('attemptId', p_attempt_id));
      end loop;
    end if;
  end if;

  return json_build_object('ok', true, 'attemptId', p_attempt_id, 'score', v_score, 'evidenceWritten', v_evidence_written, 'mode', v_evidence_mode, 'policy', v_pol, 'delivered', v_delivered, 'answered', v_total, 'omitted', greatest(v_delivered - v_voided - v_total, 0))::jsonb;
end;
$$;


--
-- Name: form_items_boundary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.form_items_boundary() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v record;
begin
  select review_status, held_out, item_version into v from public.assessment_items where id = new.item_id;
  if v.review_status is distinct from 'reviewed' then raise exception 'ITEM_NOT_REVIEWED: only human-reviewed questions can enter a paper'; end if;
  if v.held_out and coalesce(current_setting('app.holdout_form', true), '') <> 'on' then
    raise exception 'ITEM_HELD_OUT: a held-out question cannot enter a routine paper';
  end if;
  if not exists (select 1 from public.item_review_decisions d where d.item_id = new.item_id and d.item_version = v.item_version and d.decision = 'approve') then
    raise exception 'ITEM_NOT_APPROVED: no recorded approval exists for this version of the question';
  end if;
  new.item_version := v.item_version;
  return new;
end $$;


--
-- Name: form_items_freeze_difficulty(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.form_items_freeze_difficulty() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_ver int; v_prop text; v record;
begin
  if new.difficulty_basis is not null then return new; end if;
  select item_version, intended_difficulty into v_ver, v_prop from public.assessment_items where id = new.item_id;
  select c.level, c.review_id into v from public.item_confirmed_difficulty c where c.item_id = new.item_id and c.item_version = coalesce(new.item_version, v_ver);
  if v.level is not null then new.difficulty_level := v.level; new.difficulty_basis := 'confirmed'; new.difficulty_review_id := v.review_id;
  else new.difficulty_level := null; new.difficulty_basis := case when v_prop is not null then 'proposed' else 'unclassified' end; end if;
  return new;
end $$;


--
-- Name: group_items_in_family(text[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.group_items_in_family(p_item_ids text[], p_family_id uuid DEFAULT NULL::uuid, p_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_family uuid := p_family_id; v_n int; v_id text;
begin
  if v_uid is null or not public.is_item_reviewer() then return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can group items.'); end if;
  select count(*) into v_n from public.assessment_items where id = any(p_item_ids);
  if coalesce(array_length(p_item_ids, 1), 0) = 0 or v_n <> array_length(p_item_ids, 1) then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'One or more items do not exist.'); end if;
  if v_family is null then
    insert into public.item_families(family_key, note) values ('fam-' || gen_random_uuid()::text, nullif(btrim(p_note), '')) returning id into v_family;
  elsif not exists (select 1 from public.item_families where id = v_family) then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown family.');
  end if;
  update public.item_families set construction_status = 'confirmed', confirmed_by = v_uid, confirmed_at = now() where id = v_family;
  update public.assessment_items set family_id = v_family where id = any(p_item_ids);
  for v_id in select unnest(p_item_ids) loop
    insert into public.item_revisions(item_id, item_version, kind, actor_id, summary)
      select id, item_version, 'family', v_uid, 'Grouped in family ' || v_family from public.assessment_items where id = v_id;
  end loop;
  return jsonb_build_object('ok', true, 'familyId', v_family);
end $$;


--
-- Name: guard_confirmation_on_superseded(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_confirmation_on_superseded() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_block text := coalesce(new.block_id, old.block_id);
begin
  if pg_trigger_depth() > 1 then return coalesce(new, old); end if;
  if exists (select 1 from public.plan_blocks s where s.continued_from_task_id = v_block) then
    raise exception 'This task continues in a later week; its confirmed outcomes are history.' using errcode = '22023';
  end if;
  return coalesce(new, old);
end; $$;


--
-- Name: guard_superseded_task(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_superseded_task() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if pg_trigger_depth() > 1 then return old; end if;
    if old.continued_from_task_id is not null then
      raise exception 'A continuation cannot be deleted. Remove it from the plan instead.' using errcode = '22023';
    end if;
    if exists (select 1 from public.plan_blocks s where s.continued_from_task_id = old.id) then
      raise exception 'This task continues in a later week and can no longer be deleted.' using errcode = '22023';
    end if;
    return old;
  end if;
  if exists (select 1 from public.plan_blocks s where s.continued_from_task_id = old.id)
     and (new.execution, new.local_date, new.starts_at, new.duration_minutes, new.placement, new.cancelled_at, new.scope_group_id, new.cycle_id, new.outcome_id, new.lm_id)
         is distinct from
         (old.execution, old.local_date, old.starts_at, old.duration_minutes, old.placement, old.cancelled_at, old.scope_group_id, old.cycle_id, old.outcome_id, old.lm_id) then
    raise exception 'This task continues in a later week and can no longer be changed.' using errcode = '22023';
  end if;
  return new;
end; $$;


--
-- Name: guard_task_lineage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_task_lineage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_pred public.plan_blocks%rowtype;
begin
  if tg_op = 'UPDATE' then
    -- Foreign-key actions (e.g. an account or cycle being deleted) run nested and may unlink.
    if pg_trigger_depth() > 1 then return new; end if;
    if new.continued_from_task_id is distinct from old.continued_from_task_id
       or new.carry_intent is distinct from old.carry_intent
       or new.estimate_provisional is distinct from old.estimate_provisional then
      raise exception 'Continuation links cannot be changed.' using errcode = '22023';
    end if;
    return new;
  end if;
  -- Outside the weekly-review command a row carries no lineage. This matters for two cases: a forged link
  -- has no effect, and a row copied from a continuation (e.g. a split sitting) is a sibling, not a second
  -- successor of the same task.
  if coalesce(current_setting('roadmap.continuation_command', true), '') <> 'on' then
    new.continued_from_task_id := null; new.carry_intent := null; new.estimate_provisional := false;
    return new;
  end if;
  if new.continued_from_task_id is null then
    new.carry_intent := null; new.estimate_provisional := false;
    return new;
  end if;
  select * into v_pred from public.plan_blocks where id = new.continued_from_task_id;
  if not found or v_pred.user_id is distinct from new.user_id then
    raise exception 'A continuation must continue one of your own tasks.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.planning_cycles a, public.planning_cycles b
    where a.id = v_pred.cycle_id and b.id = new.cycle_id and a.user_id = new.user_id and b.user_id = new.user_id
      and b.starts_at_local > a.starts_at_local
  ) then
    raise exception 'A continuation must belong to a later week than the task it continues.' using errcode = '22023';
  end if;
  return new;
end; $$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1)))
  on conflict (id) do nothing;
  return new;
end;
$$;


