$$;


--
-- Name: log_learning_with_coverage(text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_learning_with_coverage(p_activity_type text, p_description text, p_lm_id text DEFAULT NULL::text, p_related_task_id text DEFAULT NULL::text, p_duration_minutes integer DEFAULT NULL::integer, p_self_reported_confidence text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_activity_id uuid;
  v_coverage text;
  v_source text;
begin
  if v_user_id is null then raise exception 'Unauthorized'; end if;
  if p_activity_type not in ('class', 'independent_study', 'external_practice') then
    raise exception 'Invalid activity type';
  end if;
  if p_description is null or length(btrim(p_description)) < 1 or length(p_description) > 1000 then
    raise exception 'Describe what you covered in 1 to 1000 characters';
  end if;
  if p_duration_minutes is not null and (p_duration_minutes < 1 or p_duration_minutes > 720) then
    raise exception 'Invalid duration';
  end if;
  if p_self_reported_confidence is not null and
     p_self_reported_confidence not in ('low', 'medium', 'high', 'unknown') then
    raise exception 'Invalid confidence';
  end if;
  if p_lm_id is not null and not exists (
    select 1 from public.learning_modules where id = p_lm_id and is_active = true
  ) then raise exception 'Choose a current curriculum module'; end if;
  if p_related_task_id is not null and not exists (
    select 1 from public.plan_blocks where id = p_related_task_id and user_id = v_user_id
  ) then raise exception 'Invalid task reference'; end if;

  insert into public.learning_activities (
    user_id, activity_type, description, lm_id, related_task_id,
    duration_minutes, self_reported_confidence
  ) values (
    v_user_id, p_activity_type, btrim(p_description), p_lm_id,
    p_related_task_id, p_duration_minutes, p_self_reported_confidence
  ) returning id into v_activity_id;

  if p_lm_id is not null then
    v_coverage := case when p_activity_type = 'class' then 'taught' else 'studied' end;
    v_source := case when p_activity_type = 'class' then 'class' else 'self_report' end;
    insert into public.user_module_state (user_id, lm_id, coverage_state, source, updated_at)
    values (v_user_id, p_lm_id, v_coverage, v_source, now())
    on conflict (user_id, lm_id) do update set
      coverage_state = case
        when public.user_module_state.coverage_state = 'verified' then 'verified'
        when public.user_module_state.coverage_state = 'studied' and v_coverage = 'taught' then 'studied'
        else v_coverage
      end,
      source = case
        when public.user_module_state.coverage_state = 'verified' then public.user_module_state.source
        when public.user_module_state.coverage_state = 'studied' and v_coverage = 'taught' then public.user_module_state.source
        else v_source
      end,
      updated_at = now();
  end if;
  return v_activity_id;
end;
$$;


--
-- Name: mock_apply_projection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mock_apply_projection(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_n public.mock_appointments%rowtype; v_has boolean;
begin
  select * into v_n from public.mock_appointments where user_id = p_user and status = 'planned' order by planned_date, created_at, id limit 1;
  v_has := found;
  perform set_config('app.mock_projection', 'on', true);
  if v_has then
    update public.profiles set mock_id = v_n.id, mock_version = v_n.version, mock_date = v_n.planned_date, mock_kind = v_n.kind, mock_label = v_n.label,
      mock_start_time = v_n.start_time, mock_duration_minutes = v_n.duration_minutes where id = p_user;
  else
    update public.profiles set mock_id = null, mock_date = null, mock_kind = null, mock_label = null, mock_start_time = null, mock_duration_minutes = null where id = p_user;
  end if;
  perform set_config('app.mock_projection', 'off', true);
end $$;


--
-- Name: mock_appointments_booking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mock_appointments_booking_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_range tstzrange; v_title text;
begin
  if new.status <> 'planned' or new.start_time is null or new.duration_minutes is null then return new; end if;
  if tg_op = 'UPDATE' and old.status = 'planned' and old.planned_date = new.planned_date
     and old.start_time is not distinct from new.start_time and old.duration_minutes is not distinct from new.duration_minutes then return new; end if;
  perform public.scope_lock(new.user_id);
  v_range := public.mock_booking_range(new.user_id, new.planned_date, new.start_time, new.duration_minutes);
  select p.title into v_title from public.protected_occurrences(new.user_id, v_range) p limit 1;
  if v_title is null then
    select coalesce(nullif(m.label, ''), 'Another mock') into v_title from public.mock_appointments m
     where m.user_id = new.user_id and m.id <> new.id and m.status = 'planned' and m.start_time is not null and m.duration_minutes is not null
       and public.mock_booking_range(m.user_id, m.planned_date, m.start_time, m.duration_minutes) && v_range limit 1;
  end if;
  if v_title is null then
    select b.title into v_title from public.plan_blocks b
     where b.user_id = new.user_id and b.placement = 'timed' and b.starts_at is not null and b.cancelled_at is null and b.execution <> 'cancelled'
       and b.learning_activity_id is null
       and tstzrange(b.starts_at, b.starts_at + make_interval(mins => coalesce(b.duration_minutes, 30)), '[)') && v_range limit 1;
  end if;
  if v_title is not null then perform public.booking_refuse(v_title); end if;
  return new;
end $$;


--
-- Name: mock_appointments_project(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mock_appointments_project() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('app.mock_from_profile', true), '') = 'on' then return null; end if;
  perform public.mock_apply_projection(coalesce(new.user_id, old.user_id));
  return null;
end $$;


--
-- Name: mock_appointments_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mock_appointments_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and (old.planned_date, old.kind, old.label, old.start_time, old.duration_minutes, old.status)
       is distinct from (new.planned_date, new.kind, new.label, new.start_time, new.duration_minutes, new.status) then
    new.version := old.version + 1; new.updated_at := now();
  end if;
  return new;
end $$;


--
-- Name: mock_booking_range(uuid, date, time without time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mock_booking_range(p_user uuid, p_date date, p_start time without time zone, p_minutes integer) RETURNS tstzrange
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case when p_date is null or p_start is null or p_minutes is null then null
    else tstzrange(((p_date + p_start)::timestamp at time zone public.booking_tz(p_user)),
                   ((p_date + p_start)::timestamp at time zone public.booking_tz(p_user)) + make_interval(mins => p_minutes), '[)') end
$$;


--
-- Name: onboarding_commit_step(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_commit_step(p_user uuid, p_step text, p_args jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_version integer; v_next jsonb;
begin
  -- current-week serialization
  perform public.scope_lock(p_user);
  perform 1 from public.profiles where id = p_user for update;
  if not found then raise exception 'Profile not found'; end if;

  if p_step = 'exam' then
    update public.profiles set
      timezone = p_args->>'timezone', registered = (p_args->>'registered')::boolean, exam_window_id = (p_args->>'exam_window_id')::uuid,
      exam_sitting = p_args->>'exam_sitting', exam_year = (p_args->>'exam_year')::int, exam_date = nullif(p_args->>'exam_date', '')::date
    where id = p_user;
  elsif p_step = 'route' then
    v_next := case when jsonb_typeof(p_args->'next_class') = 'object' then p_args->'next_class' else null end;
    perform public.onboarding_replace_route(p_user, p_args->>'prep_mode', p_args->>'class_pattern', p_args->'classes', v_next);
  elsif p_step = 'position' then
    perform public.onboarding_replace_position(
      p_user, p_args->>'stage', p_args->'exposure',
      case when jsonb_typeof(p_args->'readings') = 'array' then p_args->'readings' end,
      case when jsonb_typeof(p_args->'uncertainty') = 'array' then p_args->'uncertainty' end,
      coalesce((p_args->>'mock_set')::boolean, false),
      case when jsonb_typeof(p_args->'mock') = 'object' then p_args->'mock' end);
    if jsonb_typeof(p_args->'mock_timing') = 'object' then
      update public.profiles set
        mock_label = case when p_args->'mock_timing' ? 'mock_label' then nullif(p_args->'mock_timing'->>'mock_label', '') else mock_label end,
        mock_start_time = case when p_args->'mock_timing' ? 'mock_start_time' then nullif(p_args->'mock_timing'->>'mock_start_time', '')::time else mock_start_time end,
        mock_duration_minutes = case when p_args->'mock_timing' ? 'mock_duration_minutes' then nullif(p_args->'mock_timing'->>'mock_duration_minutes', '')::int else mock_duration_minutes end
      where id = p_user;
    end if;
  elsif p_step = 'week' then
    perform public.onboarding_replace_week(p_user, (p_args->>'max_session')::int, p_args->>'mode', p_args->'windows', p_args->'commitments');
  else
    raise exception 'Unknown setup step %', p_step;
  end if;

  if p_step in ('route','exam') then
    update public.profiles set diagnostic_day=public.derived_week_closing_day(p_user) where id=p_user;
  end if;
  update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user
    returning onboarding_context_version into v_version;
  return v_version;
end $$;


--
-- Name: onboarding_replace_position(uuid, text, jsonb, jsonb, jsonb, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_replace_position(p_user uuid, p_stage text, p_exposure jsonb, p_readings jsonb DEFAULT NULL::jsonb, p_uncertainty jsonb DEFAULT NULL::jsonb, p_mock_set boolean DEFAULT false, p_mock jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare e jsonb; v_state text;
begin
  update public.profiles set stage = p_stage, entry_reported_at = now() where id = p_user;
  if not found then raise exception 'no profile for user'; end if;

  -- As before, this screen rewrites the student's own self-reported taught/studied rows. Class and diagnostic rows are never
  -- touched, and a claim never replaces one of those (do nothing on conflict). Logged study is re-derived from completed blocks.
  delete from public.user_topic_exposure where user_id = p_user and source = 'self_report';
  delete from public.user_module_state
   where user_id = p_user and source = 'self_report' and coverage_state in ('taught', 'studied');

  for e in select * from jsonb_array_elements(coalesce(p_exposure, '[]'::jsonb)) loop
    insert into public.user_topic_exposure (user_id, topic_id, recency, source)
    values (p_user, e->>'topic_id', e->>'recency', 'self_report');

    v_state := case e->>'recency' when 'current' then 'taught' else 'studied' end;
    insert into public.user_module_state (user_id, lm_id, coverage_state, source, updated_at)
    select p_user, m.id, v_state, 'self_report', now()
      from public.learning_modules m
     where m.topic_id = e->>'topic_id'
    on conflict (user_id, lm_id) do nothing;
  end loop;

  for e in select * from jsonb_array_elements(coalesce(p_readings, '[]'::jsonb)) loop
    delete from public.user_module_state
     where user_id = p_user and lm_id = e->>'lm_id' and source = 'self_report' and coverage_state in ('taught', 'studied');
    if e->>'state' in ('partly', 'covered') then
      insert into public.user_module_state (user_id, lm_id, coverage_state, source, updated_at)
      values (p_user, e->>'lm_id', case e->>'state' when 'partly' then 'taught' else 'studied' end, 'self_report', now())
      on conflict (user_id, lm_id) do nothing;
    end if;
  end loop;

  if p_uncertainty is not null then
    delete from public.user_entry_uncertainty where user_id = p_user;
    insert into public.user_entry_uncertainty (user_id, topic_id, level, lm_ids)
    select p_user, u->>'topic_id', u->>'level', coalesce(array(select jsonb_array_elements_text(u->'lm_ids')), '{}')
      from jsonb_array_elements(p_uncertainty) u;
  end if;

  if p_mock_set then
    update public.profiles set mock_date = (p_mock->>'date')::date, mock_kind = p_mock->>'kind' where id = p_user;
  end if;
end $$;


--
-- Name: onboarding_replace_route(uuid, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_replace_route(p_user uuid, p_prep_mode text, p_class_pattern text, p_classes jsonb, p_next_class jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare c jsonb;
begin
  update public.profiles set prep_mode = p_prep_mode, class_pattern = p_class_pattern where id = p_user;
  if not found then raise exception 'no profile for user'; end if;

  update public.calendar_commitments set status = 'archived'
   where user_id = p_user and kind = 'class' and source = 'onboarding' and status = 'active';

  for c in select * from jsonb_array_elements(coalesce(p_classes, '[]'::jsonb)) loop
    if (c->>'end_time')::time <= (c->>'start_time')::time then
      raise exception 'a class must end after it starts';
    end if;
    insert into public.calendar_commitments
      (user_id, label, kind, weekdays, start_time, end_time, starts_at, ends_at, ends_on, status, source, recurrence, is_protected)
    values
      (p_user, coalesce(nullif(c->>'label', ''), 'Class'), 'class',
       array(select jsonb_array_elements_text(c->'weekdays')::int),
       (c->>'start_time')::time, (c->>'end_time')::time,
       '1970-01-01T00:00:00Z', '2100-01-01T00:00:00Z', nullif(c->>'ends_on', '')::date,
       'active', 'onboarding', 'weekly', true);
  end loop;

  if p_next_class is not null and p_next_class <> 'null'::jsonb then
    if (p_next_class->>'ends_at')::timestamptz <= (p_next_class->>'starts_at')::timestamptz then
      raise exception 'the next class must end after it starts';
    end if;
    insert into public.calendar_commitments
      (user_id, label, kind, starts_at, ends_at, status, source, recurrence, is_protected, defines_cycle)
    values
      (p_user, coalesce(nullif(p_next_class->>'label', ''), 'Class'), 'class',
       (p_next_class->>'starts_at')::timestamptz, (p_next_class->>'ends_at')::timestamptz,
       'active', 'onboarding', 'none', true, true);
  end if;
end $$;


--
-- Name: onboarding_replace_week(uuid, integer, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboarding_replace_week(p_user uuid, p_max_session integer, p_mode text, p_windows jsonb, p_commitments jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare w jsonb;
begin
  update public.profiles set max_session_minutes = p_max_session, week_availability_mode = p_mode where id = p_user;
  if not found then raise exception 'no profile for user'; end if;

  update public.calendar_commitments set status = 'archived'
   where user_id = p_user and kind <> 'class' and source = 'onboarding' and status = 'active';

  for w in select * from jsonb_array_elements(coalesce(p_commitments, '[]'::jsonb)) loop
    if (w->>'end_time')::time <= (w->>'start_time')::time then
      raise exception 'a commitment must end after it starts';
    end if;
    insert into public.calendar_commitments
      (user_id, label, kind, weekdays, start_time, end_time, starts_at, ends_at, status, source, recurrence)
    values
      (p_user, coalesce(nullif(w->>'label', ''), 'Commitment'), coalesce(nullif(w->>'kind', ''), 'other'),
       array(select jsonb_array_elements_text(w->'weekdays')::int),
       (w->>'start_time')::time, (w->>'end_time')::time,
       '1970-01-01T00:00:00Z', '2100-01-01T00:00:00Z', 'active', 'onboarding', 'weekly');
  end loop;

  update public.availability_windows set status = 'archived' where user_id = p_user and status = 'active';

  for w in select * from jsonb_array_elements(coalesce(p_windows, '[]'::jsonb)) loop
    if (w->>'end_time')::time <= (w->>'start_time')::time then
      raise exception 'a study window must end after it starts';
    end if;
    insert into public.availability_windows (user_id, weekday, start_time, end_time, source, status)
    values (p_user, (w->>'weekday')::int, (w->>'start_time')::time, (w->>'end_time')::time, 'onboarding', 'active');
  end loop;
end $$;


--
-- Name: paper_item_defects(uuid, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.paper_item_defects(p_user uuid, p_item_ids text[], p_require_family boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with ids as (select x.id, x.ord from unnest(p_item_ids) with ordinality as x(id, ord)),
  exposed as (
    select r.item_id from public.assessment_responses r where r.user_id = p_user
    union
    select fi.item_id from public.form_items fi join public.assessment_attempts a on a.form_id = fi.form_id
     where a.user_id = p_user and a.status not in ('ready', 'assembling')),
  seen_fam as (select distinct i.family_id from exposed e join public.assessment_items i on i.id = e.item_id where i.family_id is not null),
  rows as (
    select ids.id, ids.ord, i.family_id, i.review_status, i.held_out, i.item_version,
           row_number() over (partition by ids.id order by ids.ord) as dup_item,
           case when i.family_id is null then 1 else row_number() over (partition by i.family_id order by ids.ord) end as dup_family
      from ids left join public.assessment_items i on i.id = ids.id)
  select coalesce(jsonb_agg(jsonb_build_object('itemId', d.id, 'code', d.code) order by d.ord), '[]'::jsonb) from (
    select r.id, r.ord, case
      when r.review_status is null then 'NOT_FOUND'
      when r.dup_item > 1 then 'DUPLICATE_ITEM'
      when r.review_status <> 'reviewed' then 'NOT_REVIEWED'
      when r.held_out then 'HELD_OUT'
      when not exists (select 1 from public.item_review_decisions d where d.item_id = r.id and d.item_version = r.item_version and d.decision = 'approve') then 'NO_APPROVAL'
      when exists (select 1 from exposed e where e.item_id = r.id) then 'SEEN'
      when r.family_id is not null and exists (select 1 from seen_fam s where s.family_id = r.family_id) then 'SEEN_FAMILY'
      when p_require_family and r.family_id is null then 'UNKNOWN_FAMILY'
      when r.dup_family > 1 then 'DUPLICATE_FAMILY'
      else null end as code
    from rows r) d
  where d.code is not null
$$;


--
-- Name: paper_scope_source(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.paper_scope_source(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(concat_ws('|',
    (select coalesce(string_agg(concat_ws(':', id, revision, execution, coalesce(cancelled_at::text, ''), coalesce(outcome_id, ''), coalesce(lm_id, ''), coalesce(scope_group_id::text, ''), coalesce(learning_activity_id::text, ''), coalesce(cycle_id::text, '')), ',' order by id), '')
       from public.plan_blocks where user_id = p_user),
    (select coalesce(string_agg(c.block_id || ':' || c.outcome_id, ',' order by c.block_id, c.outcome_id), '') from public.block_scope_confirmations c where c.user_id = p_user),
    (select coalesce(string_agg(s.id::text || ':' || s.kind || ':' || coalesce(i.outcome_id, ''), ',' order by s.id::text, i.outcome_id), '')
       from public.class_sessions s left join public.class_session_items i on i.session_id = s.id where s.user_id = p_user),
    (select coalesce(string_agg(m.lm_id || ':' || m.coverage_state, ',' order by m.lm_id), '') from public.user_module_state m where m.user_id = p_user),
    (select coalesce(md5(string_agg(e.id::text || ':' || e.validity, ',' order by e.id::text)), '') from public.evidence_events e where e.user_id = p_user)
  ))
$$;


--
-- Name: place_repair_check(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_repair_check(p_thread_ids uuid[], p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid := auth.uid(); v_cycle public.planning_cycles%rowtype; v_id text; v_today date; v_due date; v_date date; v_n int;
begin
  -- planning input serialization
  perform public.scope_lock(auth.uid());
  if v_user is null then raise exception 'Sign in to update your plan.' using errcode = '42501'; end if;
  if not exists (select 1 from auth.users where id = v_user and email_confirmed_at is not null) then raise exception 'Verify your email before using your plan.' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles where id = v_user and onboarding_status = 'complete') then raise exception 'Complete setup before updating your plan.' using errcode = '42501'; end if;
  if p_key is null or length(p_key) < 8 or length(p_key) > 100 then raise exception 'A request key is required.' using errcode = '22023'; end if;
  if coalesce(array_length(p_thread_ids, 1), 0) = 0 then raise exception 'Choose the repairs to check.' using errcode = '22023'; end if;
  v_id := 'task-chk-' || p_key;
  if exists (select 1 from public.plan_blocks where id = v_id and user_id = v_user) then return jsonb_build_object('ok', true, 'replayed', true, 'checkTaskId', v_id); end if;

  select * into v_cycle from public.planning_cycles where user_id = v_user and status = 'active' for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NO_OPEN_WEEK'); end if;
  perform 1 from public.repair_threads where id = any(p_thread_ids) and user_id = v_user order by id for update;
  select count(*) into v_n from public.repair_threads where id = any(p_thread_ids) and user_id = v_user and status = 'awaiting_recheck';
  if v_n <> array_length(p_thread_ids, 1) then return jsonb_build_object('ok', false, 'code', 'NOT_READY'); end if;
  if exists (select 1 from public.repair_check_threads l join public.plan_blocks b on b.id = l.check_task_id
              where l.thread_id = any(p_thread_ids) and b.cancelled_at is null and b.execution in ('not_started', 'in_progress', 'partial', 'deferred')) then
    return jsonb_build_object('ok', false, 'code', 'ALREADY_PLANNED');
  end if;
  v_today := (now() at time zone coalesce(v_cycle.timezone, 'UTC'))::date;
  select max(coalesce(next_recheck_due_at::date, v_today)) into v_due from public.repair_threads where id = any(p_thread_ids);
  v_date := greatest(v_today, v_due, v_cycle.starts_at_local);
  if v_date > v_cycle.ends_at_local then return jsonb_build_object('ok', false, 'code', 'NOT_THIS_WEEK', 'earliestDate', v_date); end if;
  insert into public.plan_blocks (id, user_id, cycle_id, title, detail, task_type, origin, priority, placement, execution, local_date, day, duration_minutes, duration,
      rationale, completion_meaning, learning_objective, is_protected_commitment, created_by)
    values (v_id, v_user, v_cycle.id, 'Re-check: ' || v_n || ' repaired concept' || case when v_n = 1 then '' else 's' end, 'A short check on exactly what you repaired, using questions you have not seen.',
      'recheck', 'diagnostic', 'core', 'day_preferred', 'not_started', v_date, v_date::text, case when v_n <= 2 then 15 else 30 end, (case when v_n <= 2 then 15 else 30 end)::text,
      'Your repairs are finished, so the re-check is due.', 'You took the check. What it shows comes from the scored result.', 'Show whether the repaired concepts hold.', false, 'algorithm');
  insert into public.repair_check_threads(check_task_id, thread_id, user_id) select v_id, x, v_user from unnest(p_thread_ids) x;
  insert into public.task_events(user_id, task_id, event_type, payload, previous) values (v_user, v_id, 'created', jsonb_build_object('source', 'place_repair_check'), '{}'::jsonb);
  return jsonb_build_object('ok', true, 'replayed', false, 'checkTaskId', v_id, 'date', v_date);
end; $$;


--
-- Name: plan_blocks_booking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_blocks_booking_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_range tstzrange; v_title text;
begin
  if new.placement is distinct from 'timed' or new.starts_at is null or new.cancelled_at is not null
     or new.execution in ('cancelled', 'completed', 'skipped') or new.learning_activity_id is not null then return new; end if;
  if tg_op = 'UPDATE' and old.starts_at is not distinct from new.starts_at and old.duration_minutes is not distinct from new.duration_minutes
     and old.placement is not distinct from new.placement and old.cancelled_at is null and old.execution not in ('cancelled', 'completed', 'skipped') then return new; end if;
  perform public.scope_lock(new.user_id);
  v_range := tstzrange(new.starts_at, new.starts_at + make_interval(mins => coalesce(new.duration_minutes, 30)), '[)');
  select coalesce(nullif(m.label, ''), 'Your mock') into v_title from public.mock_appointments m
   where m.user_id = new.user_id and m.status = 'planned' and m.start_time is not null and m.duration_minutes is not null
     and public.mock_booking_range(m.user_id, m.planned_date, m.start_time, m.duration_minutes) && v_range limit 1;
  if v_title is not null then perform public.booking_refuse(v_title); end if;
  return new;
end $$;


--
-- Name: practice_run_receipt(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.practice_run_receipt(p_user uuid, p_request_key text, p_run uuid, p_def jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_r public.practice_run_receipts%rowtype; v_run public.practice_runs%rowtype;
begin
  if p_request_key is null then return null; end if;
  select * into v_r from public.practice_run_receipts where user_id = p_user and request_key = p_request_key;
  if not found then return null; end if;
  if v_r.scope_hash is distinct from public._practice_def_hash(p_def) or (p_run is null) is distinct from (v_r.op = 'start') or (p_run is not null and v_r.run_id <> p_run) then
    return jsonb_build_object('ok', false, 'code', 'KEY_CONFLICT');
  end if;
  select * into v_run from public.practice_runs where id = v_r.run_id;
  return jsonb_build_object('ok', true, 'resumed', true, 'replay', true, 'runId', v_r.run_id, 'attemptId', v_r.attempt_id, 'block', v_r.block_no, 'revision', v_run.revision, 'runStatus', v_run.status);
end $$;


--
-- Name: practice_run_reserve(uuid, uuid, text, integer, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.practice_run_reserve(p_user uuid, p_run uuid, p_request_key text, p_expected_revision integer, p_def jsonb, p_decision jsonb, p_paper jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_run public.practice_runs%rowtype; v_block int; v_last record; v_total int; v_res jsonb; v_rc jsonb; v_size int := jsonb_array_length(p_paper->'itemIds');
begin
  perform pg_advisory_xact_lock(hashtextextended('practice-runs:' || p_user::text, 0));
  -- A successful operation is resolved FIRST: it never re-checks cap, stopped state, revision or inventory.
  v_rc := public.practice_run_receipt(p_user, p_request_key, p_run, p_def);
  if v_rc is not null then return v_rc; end if;
  if v_size <> 5 then return jsonb_build_object('ok', false, 'code', 'BAD_SET'); end if;
  if p_run is null then
    v_block := 1;
  else
    select * into v_run from public.practice_runs where id = p_run and user_id = p_user for update;
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
    select s.attempt_id, s.block_no, a.status into v_last from public.practice_run_sets s join public.assessment_attempts a on a.id = s.attempt_id where s.run_id = v_run.id order by s.block_no desc limit 1;
    if v_run.status <> 'active' then return jsonb_build_object('ok', false, 'code', 'RUN_CLOSED'); end if;
    if v_run.revision <> p_expected_revision then return jsonb_build_object('ok', false, 'code', 'STALE_RUN', 'revision', v_run.revision); end if;
    if v_last.status not in ('submitted', 'scored', 'rescored', 'partially_voided', 'expired') then return jsonb_build_object('ok', false, 'code', 'SET_OPEN', 'attemptId', v_last.attempt_id); end if;
    select coalesce(sum(size), 0) into v_total from public.practice_run_sets where run_id = v_run.id;
    if v_total + v_size > v_run.cap then return jsonb_build_object('ok', false, 'code', 'CAP_REACHED'); end if;
    v_block := v_last.block_no + 1;
  end if;
  if not public._lock_check_levels(p_paper->'itemIds', p_paper->'levels') then return jsonb_build_object('ok', false, 'code', 'DECISION_CHANGED'); end if;
  if p_run is null then
    insert into public.practice_runs(user_id, request_key, last_request_key, reading_id, outcome_ids, cap, policy_version)
      values (p_user, p_request_key, p_request_key, p_def->>'readingId', array(select jsonb_array_elements_text(coalesce(p_def->'outcomeIds', '[]'::jsonb)) order by 1), (p_def->>'cap')::int, p_def->>'policy')
      returning * into v_run;
  end if;
  v_res := public._reserve_paper_json(p_user, p_paper || jsonb_build_object('openKey', 'practice-run:' || v_run.id || ':' || v_block));
  if coalesce((v_res->>'ok')::boolean, false) is not true then
    if p_run is null then delete from public.practice_runs where id = v_run.id; end if;
    return v_res;
  end if;
  insert into public.practice_run_sets(run_id, block_no, attempt_id, size, decision) values (v_run.id, v_block, (v_res->>'attemptId')::uuid, v_size, p_decision);
  insert into public.practice_run_receipts(user_id, request_key, op, run_id, block_no, attempt_id, scope_hash)
    values (p_user, p_request_key, case when p_run is null then 'start' else 'next' end, v_run.id, v_block, (v_res->>'attemptId')::uuid, public._practice_def_hash(p_def));
  update public.practice_runs set revision = revision + 1, last_request_key = p_request_key, updated_at = now() where id = v_run.id returning * into v_run;
  return jsonb_build_object('ok', true, 'resumed', false, 'runId', v_run.id, 'attemptId', v_res->>'attemptId', 'revision', v_run.revision, 'block', v_block);
end $$;


--
-- Name: practice_run_stop(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.practice_run_stop(p_user uuid, p_run uuid, p_expected_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_run public.practice_runs%rowtype; v_last record;
begin
  perform pg_advisory_xact_lock(hashtextextended('practice-runs:' || p_user::text, 0));
  select * into v_run from public.practice_runs where id = p_run and user_id = p_user for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_run.status = 'stopped' then return jsonb_build_object('ok', true, 'repeated', true, 'revision', v_run.revision); end if;
  select a.status, s.attempt_id into v_last from public.practice_run_sets s join public.assessment_attempts a on a.id = s.attempt_id where s.run_id = v_run.id order by s.block_no desc limit 1;
  if v_last.status not in ('submitted', 'scored', 'rescored', 'partially_voided', 'expired') then return jsonb_build_object('ok', false, 'code', 'SET_OPEN', 'attemptId', v_last.attempt_id); end if;
  if p_expected_revision is not null and v_run.revision <> p_expected_revision then return jsonb_build_object('ok', false, 'code', 'STALE_RUN', 'revision', v_run.revision); end if;
  update public.practice_runs set status = 'stopped', revision = revision + 1, updated_at = now() where id = p_run returning * into v_run;
  return jsonb_build_object('ok', true, 'revision', v_run.revision);
end $$;


--
-- Name: prepare_concept_stubs(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_concept_stubs(p_manifest uuid, p_stubs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_s jsonb; v_made int := 0; v_existing int := 0; v_cid uuid;
begin
  if not exists (select 1 from public.curriculum_manifests where id = p_manifest) then return jsonb_build_object('ok', false, 'code', 'NO_MANIFEST'); end if;
  for v_s in select * from jsonb_array_elements(p_stubs) loop
    -- an outcome already mapped to a concept IN THIS MANIFEST is left exactly as it is
    if exists (select 1 from public.concept_outcome_map m join public.curriculum_concepts c on c.id = m.concept_id where c.manifest_id = p_manifest and m.outcome_id = v_s->>'outcome_id') then v_existing := v_existing + 1; continue; end if;
    v_cid := (v_s->>'concept_id')::uuid;
    insert into public.curriculum_concepts(id, manifest_id, topic, reading, module, los, name, importance, lm_id, verification_status, scope_notes)
      values (v_cid, p_manifest, v_s->>'topic', v_s->>'reading', v_s->>'module', v_s->>'los', v_s->>'name', 'core', v_s->>'lm_id', 'pending', v_s->>'scope_notes')
      on conflict (id) do nothing;
    insert into public.concept_outcome_map(concept_id, outcome_id, approximate) values (v_cid, v_s->>'outcome_id', true) on conflict (concept_id) do nothing;
    v_made := v_made + 1;
  end loop;
  return jsonb_build_object('ok', true, 'created', v_made, 'existing', v_existing);
end $$;


--
-- Name: profiles_clear_mock_timing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_clear_mock_timing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_a public.mock_appointments%rowtype; v_n public.mock_appointments%rowtype; v_has boolean;
begin
  if coalesce(current_setting('app.mock_projection', true), '') = 'on' then return new; end if;
  if tg_op = 'UPDATE' and (old.mock_date, old.mock_kind, old.mock_label, old.mock_start_time, old.mock_duration_minutes)
       is not distinct from (new.mock_date, new.mock_kind, new.mock_label, new.mock_start_time, new.mock_duration_minutes) then
    return new;
  end if;
  perform set_config('app.mock_from_profile', 'on', true);
  if tg_op = 'UPDATE' and old.mock_id is not null then
    select * into v_a from public.mock_appointments where id = old.mock_id and user_id = new.id and status = 'planned' for update;
  end if;
  if new.mock_date is null then
    if v_a.id is not null then
      if exists (select 1 from public.mock_rehearsals r where r.appointment_id = v_a.id and r.status = 'in_progress') then
        raise exception 'REHEARSAL_STARTED: a rehearsal that has started cannot be removed from setup';
      end if;
      update public.mock_appointments set status = 'cancelled' where id = v_a.id;
      update public.mock_rehearsals set status = 'cancelled' where appointment_id = v_a.id and status = 'ready';
      delete from public.cycle_assessment_choices where user_id = new.id and appointment_id = v_a.id;
    end if;
  elsif v_a.id is not null then
    update public.mock_appointments set planned_date = new.mock_date, label = new.mock_label, start_time = new.mock_start_time, duration_minutes = new.mock_duration_minutes,
      kind = case when v_a.kind = 'internal_rehearsal' then v_a.kind else coalesce(new.mock_kind, v_a.kind) end where id = v_a.id;
  elsif new.mock_kind is not null then
    insert into public.mock_appointments (user_id, kind, planned_date, label, start_time, duration_minutes)
      values (new.id, new.mock_kind, new.mock_date, new.mock_label, new.mock_start_time, new.mock_duration_minutes);
  end if;
  select * into v_n from public.mock_appointments where user_id = new.id and status = 'planned' order by planned_date, created_at, id limit 1;
  v_has := found;
  perform set_config('app.mock_from_profile', 'off', true);
  if v_has then
    new.mock_id := v_n.id; new.mock_version := v_n.version; new.mock_date := v_n.planned_date; new.mock_kind := v_n.kind; new.mock_label := v_n.label;
    new.mock_start_time := v_n.start_time; new.mock_duration_minutes := v_n.duration_minutes;
  else
    new.mock_id := null; new.mock_date := null; new.mock_kind := null; new.mock_label := null; new.mock_start_time := null; new.mock_duration_minutes := null;
  end if;
  return new;
end $$;


--
-- Name: protect_learning_log_time(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_learning_log_time() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists(select 1 from public.plan_blocks where id=new.task_id and learning_activity_id is not null) then
    if new.event_type='completed' and not exists(select 1 from public.task_events where task_id=new.task_id and event_type='completed') then return new; end if;
    if new.event_type in ('details_changed','cancelled') and new.actual_duration_minutes is null then return new; end if;
    raise exception 'A logged sitting has one reported-time observation.' using errcode='22023';
  end if;
  return new;
end; $$;


--
-- Name: protect_learning_sitting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_learning_sitting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.learning_activity_id is null then
    if tg_op='DELETE' then return old; end if;
    return new;
  end if;
  if not exists(select 1 from auth.users where id=old.user_id) then
    if tg_op='DELETE' then return old; end if;
    return new;
  end if;
  if tg_op='DELETE' then
    if exists(select 1 from auth.users where id=old.user_id) then
      raise exception 'Remove this learning log through the logged-sitting command.' using errcode='22023';
    end if;
    return old;
  end if;
  if row(new.user_id,new.learning_activity_id,new.local_date,new.day,new.starts_at,new.duration_minutes,new.duration,
    new.lm_id,new.outcome_id,new.scope_group_id,new.continued_from_task_id,new.placement,new.cycle_id)
    is distinct from row(old.user_id,old.learning_activity_id,old.local_date,old.day,old.starts_at,old.duration_minutes,old.duration,
    old.lm_id,old.outcome_id,old.scope_group_id,old.continued_from_task_id,old.placement,old.cycle_id)
    or new.execution not in ('completed','cancelled')
    or (old.cancelled_at is not null and new.cancelled_at is null)
    or (new.execution='cancelled' and new.cancelled_at is null) then
    raise exception 'This is recorded learning. Remove an incorrect log and record it again.' using errcode='22023';
  end if;
  return new;
end; $$;


--
-- Name: protected_occurrences(uuid, tstzrange); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protected_occurrences(p_user uuid, p_range tstzrange) RETURNS TABLE(source_id uuid, title text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_tz text := public.booking_tz(p_user);
  v_from date := ((lower(p_range) at time zone v_tz)::date) - 1;
  v_to date := ((upper(p_range) at time zone v_tz)::date) + 1;
begin
  return query
  select c.id, c.label from public.calendar_commitments c
   where c.user_id = p_user and c.status = 'active' and c.recurrence = 'none' and (c.is_protected or c.kind = 'class')
     and tstzrange(c.starts_at, greatest(c.ends_at, c.starts_at + interval '15 minutes'), '[)') && p_range;

  -- ordinary weekly occurrences (not skipped or moved on that date)
  return query
  select c.id, c.label
    from public.calendar_commitments c
    cross join lateral generate_series(v_from::timestamp, v_to::timestamp, interval '1 day') g(ts)
   where c.user_id = p_user and c.status = 'active' and c.recurrence = 'weekly' and (c.is_protected or c.kind = 'class')
     and c.start_time is not null and c.end_time is not null
     and extract(dow from g.ts)::smallint = any (c.weekdays)
     and (c.starts_on is null or g.ts::date >= c.starts_on) and (c.ends_on is null or g.ts::date <= c.ends_on)
     and not exists (select 1 from public.commitment_exceptions e where e.commitment_id = c.id and e.occurrence_date = g.ts::date)
     and tstzrange((g.ts::date + c.start_time)::timestamp at time zone v_tz,
                   ((g.ts::date + c.start_time)::timestamp at time zone v_tz) + greatest(c.end_time - c.start_time, interval '15 minutes'), '[)') && p_range;

  -- moved occurrences, at their new date and time (the original occurrence must have been a real one)
  return query
  select c.id, c.label
    from public.commitment_exceptions e
    join public.calendar_commitments c on c.id = e.commitment_id
   where e.user_id = p_user and e.kind = 'moved' and c.status = 'active' and c.recurrence = 'weekly' and (c.is_protected or c.kind = 'class')
     and c.start_time is not null and c.end_time is not null
     and extract(dow from e.occurrence_date)::smallint = any (c.weekdays)
     and (c.starts_on is null or e.occurrence_date >= c.starts_on) and (c.ends_on is null or e.occurrence_date <= c.ends_on)
     and coalesce(e.new_date, e.occurrence_date) between v_from and v_to
     and tstzrange((coalesce(e.new_date, e.occurrence_date) + coalesce(e.new_start_time, c.start_time))::timestamp at time zone v_tz,
                   ((coalesce(e.new_date, e.occurrence_date) + coalesce(e.new_start_time, c.start_time))::timestamp at time zone v_tz)
                     + greatest(coalesce(e.new_end_time - coalesce(e.new_start_time, c.start_time), c.end_time - c.start_time), interval '15 minutes'), '[)') && p_range;
end $$;


--
-- Name: raise_item_challenge(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_item_challenge(p_attempt_id uuid, p_item_id text, p_comment text, p_reason_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid; v_att record; v_id uuid; v_challenge_id uuid; v_seen boolean; v_have boolean;
begin
  v_user_id := auth.uid();
  if v_user_id is null then raise exception 'Unauthorized'; end if;
  select * into v_att from public.assessment_attempts where id = p_attempt_id and user_id = v_user_id for update;
  v_have := found;
  if v_have then
    v_seen := (v_att.status in ('in_progress', 'submitted', 'scored', 'partially_voided', 'rescored', 'expired')
               and (exists (select 1 from public.form_items fi where fi.form_id = v_att.form_id and fi.item_id = p_item_id)
                    or exists (select 1 from public.assessment_responses r where r.attempt_id = p_attempt_id and r.item_id = p_item_id and r.user_id = v_user_id)))
              or exists (select 1 from public.attempt_item_progress p where p.attempt_id = p_attempt_id and p.item_id = p_item_id and p.user_id = v_user_id);
  end if;
  -- One message for every refusal: a foreign attempt, an unseen question and a question not on the form look alike.
  if not v_have or not coalesce(v_seen, false) then raise exception 'Response not found'; end if;
  select id into v_id from public.item_challenges where attempt_id = p_attempt_id and item_id = p_item_id and user_id = v_user_id order by created_at limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.item_challenges (user_id, item_id, attempt_id, comment, reason_code, status)
    values (v_user_id, p_item_id, p_attempt_id, p_comment, coalesce(p_reason_code, 'other'), 'pending') returning id into v_challenge_id;
  update public.evidence_events set validity = 'disputed', validity_reason = 'challenge_pending'
    where attempt_id = p_attempt_id and item_id = p_item_id and user_id = v_user_id and validity = 'valid';
  return v_challenge_id;
end;
$$;


--
-- Name: record_assessment_response(uuid, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_assessment_response(p_attempt_id uuid, p_item_id text, p_selected_option integer, p_confidence integer, p_elapsed_seconds integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid;
  v_attempt record;
  v_item record;
  v_form_item record;
  v_is_correct boolean;
  v_response_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Unauthorized';
  end if;

  select id, status, form_id into v_attempt
  from public.assessment_attempts
  where id = p_attempt_id and user_id = v_user_id
  for update;

  if v_attempt is null then
    raise exception 'Attempt not found';
  end if;

  if v_attempt.status not in ('ready', 'in_progress', 'assembling') then
    raise exception 'Attempt is %', v_attempt.status;
  end if;

  select id, key_index into v_item
  from public.assessment_items
  where id = p_item_id;

  if v_item is null then
    raise exception 'Item not found';
  end if;

  if v_attempt.form_id is not null then
    select item_id into v_form_item
    from public.form_items
    where form_id = v_attempt.form_id and item_id = p_item_id;
    if v_form_item is null then
      raise exception 'Item not in form';
    end if;
  end if;

  v_is_correct := (p_selected_option = v_item.key_index);

  insert into public.assessment_responses (
    user_id, attempt_id, item_id, selected_option_index, is_correct, self_reported_confidence, elapsed_seconds
  ) values (
    v_user_id, p_attempt_id, p_item_id, p_selected_option, v_is_correct, p_confidence, p_elapsed_seconds
  ) on conflict (attempt_id, item_id) do update set
    selected_option_index = excluded.selected_option_index,
    is_correct = excluded.is_correct,
    self_reported_confidence = excluded.self_reported_confidence,
    elapsed_seconds = excluded.elapsed_seconds
  returning id into v_response_id;

  if v_attempt.status = 'ready' or v_attempt.status = 'assembling' then
    update public.assessment_attempts set status = 'in_progress', started_at = coalesce(started_at, now()) where id = p_attempt_id;
  end if;

  return v_response_id;
end;
$$;


--
-- Name: record_exam_status(uuid, text, date, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_exam_status(p_user uuid, p_action text, p_sat_on date DEFAULT NULL::date, p_today date DEFAULT NULL::date, p_result text DEFAULT NULL::text, p_psm text DEFAULT NULL::text, p_retake_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row public.exam_completion%rowtype;
begin
  -- current-week serialization
  perform public.scope_lock(p_user);
  perform pg_advisory_xact_lock(hashtextextended('exam:' || p_user::text, 0));
  if p_action = 'sat' then
    if p_sat_on is null or p_today is null or p_sat_on > p_today then return jsonb_build_object('ok', false, 'code', 'INVALID_DATE'); end if;
    insert into public.exam_completion (user_id, sat_on) values (p_user, p_sat_on)
      on conflict (user_id) do update set sat_on = excluded.sat_on;
    update public.exam_attempts set status = 'complete', updated_at = now() where user_id = p_user and status in ('active', 'paused');
  elsif p_action = 'undo' then
    delete from public.exam_completion where user_id = p_user;
    update public.exam_attempts set status = 'active', updated_at = now()
      where id = (select id from public.exam_attempts where user_id = p_user and status = 'complete' order by updated_at desc limit 1)
        and not exists (select 1 from public.exam_attempts x where x.user_id = p_user and x.status = 'active');
  elsif p_action = 'follow_up' then
    select * into v_row from public.exam_completion where user_id = p_user for update;
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_SAT'); end if;
    if p_psm is not null and p_psm not in ('done', 'not_done', 'unsure') then return jsonb_build_object('ok', false, 'code', 'INVALID_PSM'); end if;
    update public.exam_completion set reported_result = coalesce(nullif(btrim(p_result), ''), reported_result), psm_status = coalesce(p_psm, psm_status),
      retake_requested_at = case when p_retake_note is not null then coalesce(retake_requested_at, now()) else retake_requested_at end,
      retake_note = coalesce(nullif(btrim(p_retake_note), ''), retake_note) where user_id = p_user;
  else
    return jsonb_build_object('ok', false, 'code', 'UNKNOWN_ACTION');
  end if;
  update public.profiles set onboarding_context_version = coalesce(onboarding_context_version, 1) + 1 where id = p_user;
  return jsonb_build_object('ok', true, 'action', p_action);
end $$;


--
-- Name: record_item_progress(uuid, uuid, text, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_item_progress(p_attempt uuid, p_user uuid, p_item text, p_active integer, p_interrupted integer, p_visit boolean, p_flagged boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_a public.assessment_attempts%rowtype; v_prev public.attempt_item_progress%rowtype; v_has boolean;
  v_wall numeric; v_allowed int; v_rep_a int := greatest(coalesce(p_active, 0), 0); v_rep_i int := greatest(coalesce(p_interrupted, 0), 0);
  v_active int; v_int int;
begin
  select * into v_a from public.assessment_attempts where id = p_attempt and user_id = p_user for share;
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found'); end if;
  if v_a.status not in ('ready', 'in_progress') then return jsonb_build_object('ok', false, 'code', 'closed'); end if;
  if not exists (select 1 from public.form_items where form_id = v_a.form_id and item_id = p_item) then return jsonb_build_object('ok', false, 'code', 'bad_item'); end if;
  select * into v_prev from public.attempt_item_progress where attempt_id = p_attempt and item_id = p_item for update;
  v_has := found;
  v_wall := case when v_has then extract(epoch from (now() - v_prev.last_seen_at))
                 when v_a.started_at is null then 120 else least(3600, greatest(0, extract(epoch from (now() - v_a.started_at)))) end;
  v_allowed := greatest(0, floor(v_wall))::int + 3;
  v_active := least(v_rep_a, coalesce(v_prev.active_seconds, 0) + v_allowed);
  v_int := least(v_rep_i, coalesce(v_prev.interrupted_seconds, 0) + greatest(0, v_allowed - greatest(0, v_active - coalesce(v_prev.active_seconds, 0))));
  v_active := greatest(coalesce(v_prev.active_seconds, 0), v_active); v_int := greatest(coalesce(v_prev.interrupted_seconds, 0), v_int);
  insert into public.attempt_item_progress(attempt_id, item_id, user_id, active_seconds, interrupted_seconds, visits, flagged, last_seen_at)
    values (p_attempt, p_item, p_user, v_active, v_int, 1, coalesce(p_flagged, false), now())
    on conflict (attempt_id, item_id) do update set active_seconds = v_active, interrupted_seconds = v_int,
      visits = public.attempt_item_progress.visits + case when p_visit then 1 else 0 end,
      flagged = coalesce(p_flagged, public.attempt_item_progress.flagged), last_seen_at = now();
  if p_flagged is not null then update public.assessment_responses set flagged = p_flagged where attempt_id = p_attempt and item_id = p_item; end if;
  return jsonb_build_object('ok', true, 'activeSeconds', v_active, 'interruptedSeconds', v_int);
end $$;


--
-- Name: record_learning_sitting(text, text, text, text[], integer, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_learning_sitting(p_activity_type text, p_description text, p_lm_id text, p_outcome_ids text[], p_duration_minutes integer, p_local_date date, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid(); v_tz text; v_today date; v_date date; v_ids text[];
  v_request jsonb; v_result jsonb; v_receipt public.learning_log_commands%rowtype;
  v_task_id text; v_activity_id uuid; v_cycle_id uuid; v_title text; v_cancelled boolean;
begin
  if v_uid is null or not exists (select 1 from auth.users where id=v_uid and email_confirmed_at is not null)
    or not exists (select 1 from public.profiles where id=v_uid and onboarding_status='complete') then
    raise exception 'Verify your email and complete setup before logging learning.' using errcode='42501';
  end if;
  if p_activity_type is null or p_activity_type not in ('class','independent_study','external_practice')
    or p_description is null or length(btrim(p_description)) not between 1 and 1000
    or p_lm_id is null or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_-]{8,60}$'
    or p_outcome_ids is null or cardinality(p_outcome_ids) not between 1 and 40 or array_position(p_outcome_ids,null) is not null
    or (p_duration_minutes is not null and p_duration_minutes not between 1 and 720) then
    raise exception 'Choose a reading, covered outcomes and valid minutes, or leave time unknown.' using errcode='22023';
  end if;
  select coalesce(timezone,'UTC') into v_tz from public.profiles where id=v_uid;
  v_today := (now() at time zone v_tz)::date;
  v_date := coalesce(p_local_date,v_today);
  select array_agg(distinct x order by x) into v_ids from unnest(p_outcome_ids) x;
  -- Preserve null in the canonical request: a retry after midnight still
  -- replays the original date instead of silently becoming tomorrow's study.
  v_request := jsonb_build_object('kind',p_activity_type,'description',btrim(p_description),'reading',p_lm_id,
    'outcomes',v_ids,'minutes',p_duration_minutes,'date',p_local_date);
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || ':' || p_idempotency_key,0));
  select * into v_receipt from public.learning_log_commands where user_id=v_uid and idempotency_key=p_idempotency_key;
  if found then
    if v_receipt.request is distinct from v_request then
      return jsonb_build_object('ok',false,'code','IDEMPOTENCY_CONFLICT');
    end if;
    select cancelled_at is not null into v_cancelled from public.plan_blocks where id=v_receipt.task_id and user_id=v_uid;
    if v_receipt.task_id is null or coalesce(v_cancelled,true) then
      return jsonb_build_object('ok',false,'code','LOG_REMOVED');
    end if;
    return v_receipt.result || jsonb_build_object('replayed',true);
  end if;
  if v_date > v_today or v_date < v_today - 14 then
    raise exception 'Choose today or a date within the last 14 days.' using errcode='22023';
  end if;
  select title into v_title from public.curriculum_readings
    where id=p_lm_id and is_active and not structure_pending;
  if not found or exists (select 1 from unnest(v_ids) x where not exists (
    select 1 from public.reading_los where id=x and reading_id=p_lm_id
  )) then raise exception 'Choose outcomes from one current reading.' using errcode='22023'; end if;
  -- The cycle lock serializes against weekly closure. Historical dates outside
  -- the open cycle remain historical activity; they do not leak into its paper.
  select id into v_cycle_id from public.planning_cycles
    where user_id=v_uid and status='active' and v_date between starts_at_local and ends_at_local
    for share;
  v_task_id := 'log-' || gen_random_uuid()::text;
  insert into public.learning_activities(user_id,activity_type,description,lm_id,duration_minutes)
    values(v_uid,p_activity_type,btrim(p_description),p_lm_id,p_duration_minutes) returning id into v_activity_id;
  insert into public.plan_blocks(id,user_id,cycle_id,title,detail,day,local_date,duration,duration_minutes,
    task_type,origin,created_by,priority,placement,execution,lm_id,outcome_id,learning_activity_id,rationale)
    values(v_task_id,v_uid,v_cycle_id,
      (case p_activity_type when 'class' then 'Class: ' when 'external_practice' then 'Practised: ' else 'Studied: ' end)||v_title,
      btrim(p_description),v_date::text,v_date,'',null,'study','student','student','core','day_preferred','completed',
      p_lm_id,null,v_activity_id,'Learning already completed outside the planned work.');
  update public.learning_activities set related_task_id=v_task_id where id=v_activity_id;
  insert into public.block_scope_confirmations(user_id,block_id,outcome_id) select v_uid,v_task_id,x from unnest(v_ids) x;
  insert into public.task_events(user_id,task_id,event_type,payload,previous,actual_duration_minutes,notes)
    values(v_uid,v_task_id,'completed',jsonb_build_object('kind','learning_log','local_date',v_date,'timezone',v_tz,
      'activity_type',p_activity_type,'confirmed_outcomes',v_ids),'{}',p_duration_minutes,btrim(p_description));
  v_result := jsonb_build_object('ok',true,'taskId',v_task_id,'activityId',v_activity_id,'blocks',1,
    'outcomes',cardinality(v_ids),'date',v_date,'minutes',p_duration_minutes,'inCycle',v_cycle_id is not null,
    'evidenceRecorded',false,'replayed',false);
  insert into public.learning_log_commands(user_id,idempotency_key,request,result,task_id)
    values(v_uid,p_idempotency_key,v_request,v_result,v_task_id);
  return v_result;
end; $_$;


--
-- Name: rehearsal_item_defects(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rehearsal_item_defects(p_user uuid, p_item_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with ids as (select x.id, x.ord from unnest(p_item_ids) with ordinality as x(id, ord)),
  exposed as (
    select r.item_id from public.assessment_responses r where r.user_id = p_user
    union
    select fi.item_id from public.form_items fi join public.assessment_attempts a on a.form_id = fi.form_id
     where a.user_id = p_user and a.status not in ('ready', 'assembling')),
  pinned as (
    select fi.item_id from public.form_items fi join public.assessment_attempts a on a.form_id = fi.form_id
      join public.mock_rehearsals r on r.id = a.rehearsal_id
     where a.user_id = p_user and r.status in ('ready', 'in_progress')),
  seen_fam as (select distinct i.family_id from (select item_id from exposed union select item_id from pinned) e join public.assessment_items i on i.id = e.item_id where i.family_id is not null),
  rows as (
    select ids.id, ids.ord, i.family_id, i.review_status, i.held_out, i.item_version,
           row_number() over (partition by ids.id order by ids.ord) as dup_item,
           case when i.family_id is null then 1 else row_number() over (partition by i.family_id order by ids.ord) end as dup_family
      from ids left join public.assessment_items i on i.id = ids.id)
  select coalesce(jsonb_agg(jsonb_build_object('itemId', d.id, 'code', d.code) order by d.ord), '[]'::jsonb) from (
    select r.id, r.ord, case
      when r.review_status is null then 'NOT_FOUND'
      when r.dup_item > 1 then 'DUPLICATE_ITEM'
      when r.review_status <> 'reviewed' then 'NOT_REVIEWED'
      when not r.held_out then 'NOT_HELD_OUT'
      when not exists (select 1 from public.item_review_decisions d where d.item_id = r.id and d.item_version = r.item_version and d.decision = 'approve') then 'NO_APPROVAL'
      when exists (select 1 from exposed e where e.item_id = r.id) then 'SEEN'
      when exists (select 1 from pinned p where p.item_id = r.id) then 'PINNED_ELSEWHERE'
      when r.family_id is not null and exists (select 1 from seen_fam s where s.family_id = r.family_id) then 'SEEN_FAMILY'
      when r.family_id is null then 'UNKNOWN_FAMILY'
      when r.dup_family > 1 then 'DUPLICATE_FAMILY'
      else null end as code
    from rows r) d
  where d.code is not null
$$;


--
-- Name: repair_resolution_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_resolution_policy() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  select jsonb_build_object('version', 'unset', 'autoClose', false, 'minValidQuestions', null)
$$;


--
-- Name: repair_source_version(uuid, uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_source_version(p_user uuid, p_cycle uuid, p_thread_ids uuid[], p_attempt uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(concat_ws('|',
    (select concat_ws(':', c.id::text, c.status, c.revision::text, coalesce(c.ends_at_local::text, '')) from public.planning_cycles c where c.id = p_cycle and c.user_id = p_user),
    (select coalesce(string_agg(concat_ws(':', b.id, b.revision, b.execution, coalesce(b.cancelled_at::text, ''), coalesce(b.local_date::text, ''), coalesce(b.duration_minutes::text, '')), ',' order by b.id), '')
       from public.plan_blocks b where b.user_id = p_user and b.cycle_id = p_cycle),
    (select coalesce(string_agg(concat_ws(':', t.id::text, t.status, t.revision::text, t.occurrence_count::text, coalesce(t.latest_attempt_id::text, ''), coalesce(t.latest_check_state, '')), ',' order by t.id::text), '')
       from public.repair_threads t where t.user_id = p_user and t.id = any(p_thread_ids)),
    (select coalesce(string_agg(e.id::text || ':' || e.validity || ':' || coalesce(e.validity_reason, '') || ':' || coalesce(e.superseded_by_event_id::text, ''), ',' order by e.id::text), '')
       from public.evidence_events e where e.user_id = p_user and e.attempt_id = p_attempt),
    (select coalesce(string_agg(to_jsonb(k)::text, ',' order by k.id::text), '') from public.calendar_commitments k where k.user_id = p_user and k.status = 'active'),
    (select coalesce(string_agg(to_jsonb(w)::text, ',' order by w.id::text), '') from public.availability_windows w where w.user_id = p_user and w.status = 'active')
  ))
$$;


--
-- Name: replace_roadmap(uuid, boolean, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_roadmap(p_user uuid, p_activate boolean, p_roadmap jsonb, p_milestones jsonb, p_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_existing uuid;
begin
  if p_user is null or p_hash is null or length(p_hash) < 8 then raise exception 'Invalid roadmap request'; end if;
  perform public.scope_lock(p_user);
  select id into v_existing from public.study_roadmaps
   where user_id = p_user and inputs->>'hash' = p_hash and (status = 'active' or (status = 'draft' and not p_activate))
   order by generated_at desc limit 1;
  if v_existing is not null then return jsonb_build_object('ok', true, 'id', v_existing, 'replayed', true); end if;

  update public.study_roadmaps set status = 'superseded'
   where user_id = p_user and status = any (case when p_activate then array['draft', 'active'] else array['draft'] end);
  insert into public.study_roadmaps (user_id, exam_window_id, target_date, route, status, phases, inputs, feasibility, accepted_at)
  values (p_user, nullif(p_roadmap->>'exam_window_id', '')::uuid, (p_roadmap->>'target_date')::date, p_roadmap->>'route',
          case when p_activate then 'active' else 'draft' end, p_roadmap->'phases', coalesce(p_roadmap->'inputs', '{}'::jsonb) || jsonb_build_object('hash', p_hash),
          p_roadmap->'feasibility', case when p_activate then now() end)
  returning id into v_id;
  insert into public.roadmap_milestones (roadmap_id, user_id, phase, topic_ref, sequence, planned_start_week, planned_end_week, planned_start_date, planned_end_date, effort_weight)
  select v_id, p_user, m->>'phase', m->>'topic_ref', (m->>'sequence')::smallint, (m->>'planned_start_week')::smallint, (m->>'planned_end_week')::smallint,
         (m->>'planned_start_date')::date, (m->>'planned_end_date')::date, coalesce((m->>'effort_weight')::numeric, 0)
    from jsonb_array_elements(coalesce(p_milestones, '[]'::jsonb)) m;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;


--
-- Name: reserve_batch_budget(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_batch_budget(p_batch uuid, p_claim uuid, p_requests integer, p_tokens integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_b public.item_batches%rowtype; v_max_r int; v_max_t bigint; v_wall int;
begin
  select * into v_b from public.item_batches where id = p_batch for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_b.status not in ('running', 'queued') then return jsonb_build_object('ok', false, 'code', case when v_b.status = 'budget_exhausted' then 'BUDGET' else 'CANCELLED' end); end if;
  if not exists (select 1 from public.item_batch_cells where batch_id = p_batch and claim_token = p_claim and status = 'running') then return jsonb_build_object('ok', false, 'code', 'STALE_CLAIM'); end if;
  v_max_r := coalesce((v_b.budget->>'maxRequests')::int, 0); v_max_t := coalesce((v_b.budget->>'maxTokens')::bigint, 0); v_wall := coalesce((v_b.budget->>'wallSeconds')::int, 0);
  if (v_max_r > 0 and v_b.requests_reserved + p_requests > v_max_r) or (v_max_t > 0 and v_b.tokens_reserved + p_tokens > v_max_t)
     or (v_wall > 0 and v_b.started_at is not null and v_b.started_at + make_interval(secs => v_wall) < now()) then
    perform public._stop_batch_budget(p_batch, 'The batch budget was used up before this request could be sent.');
    return jsonb_build_object('ok', false, 'code', 'BUDGET');
  end if;
  update public.item_batches set requests_reserved = requests_reserved + p_requests, tokens_reserved = tokens_reserved + p_tokens where id = p_batch;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: resolve_item_challenge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_item_challenge(p_challenge_id uuid, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid;
  v_is_reviewer boolean;
  v_challenge record;
  v_concept uuid;
  v_thread record;
  v_cancelled_tasks int := 0;
  v_cancelled_threads int := 0;
  v_task record;
  v_att uuid;
begin
  v_user_id := auth.uid();
  select count(*) > 0 into v_is_reviewer from public.user_roles where user_id = v_user_id and role = 'diagnostic_reviewer';
  if not v_is_reviewer then raise exception 'Unauthorized'; end if;

  select attempt_id into v_att from public.item_challenges where id = p_challenge_id;
  if v_att is null then raise exception 'Challenge not found'; end if;
  perform 1 from public.assessment_attempts where id = v_att for update;
  select * into v_challenge from public.item_challenges where id = p_challenge_id for update;
  if v_challenge.status != 'pending' then raise exception 'Challenge already resolved'; end if;
  if p_resolution not in ('resolved_voided', 'resolved_kept') then raise exception 'Invalid resolution'; end if;

  update public.item_challenges set status = p_resolution, resolved_at = now() where id = p_challenge_id;

  if p_resolution = 'resolved_kept' then
    update public.evidence_events set validity = 'valid', validity_reason = 'challenge_kept'
    where attempt_id = v_challenge.attempt_id and item_id = v_challenge.item_id and user_id = v_challenge.user_id;
  else
    update public.evidence_events set validity = 'voided', validity_reason = 'challenge_voided'
    where attempt_id = v_challenge.attempt_id and item_id = v_challenge.item_id and user_id = v_challenge.user_id;
    -- The attempt stays 'scored' so the student can still read it; its revision tells readers the figures changed.
    perform public._rescore_attempt(v_challenge.attempt_id, p_challenge_id, 'challenge_voided');

    for v_concept in select distinct concept_id from public.evidence_events
      where attempt_id = v_challenge.attempt_id and item_id = v_challenge.item_id and user_id = v_challenge.user_id loop
      -- Is there ANY other valid miss/unstable evidence for this concept? Then the gap is still justified.
      if exists (select 1 from public.evidence_events e where e.user_id = v_challenge.user_id and e.concept_id = v_concept
                   and e.validity = 'valid' and e.evidence_state in ('needs_repair', 'unstable')) then continue; end if;
      for v_thread in select * from public.repair_threads t where t.user_id = v_challenge.user_id and t.concept_id = v_concept
                        and t.status not in ('closed', 'cancelled', 'superseded') for update loop
        update public.repair_threads set status = 'cancelled', closure_reason = 'evidence_voided', closed_at = now(), updated_at = now(), revision = revision + 1 where id = v_thread.id;
        insert into public.repair_thread_events(thread_id, event_type, details)
          values (v_thread.id, 'cancelled', jsonb_build_object('reason', 'evidence_voided', 'challengeId', p_challenge_id));
        v_cancelled_threads := v_cancelled_threads + 1;
        -- Cancel only work that has not started. Anything started or finished is the student's history and stays.
        for v_task in select b.id, b.execution from public.plan_blocks b
            where b.user_id = v_challenge.user_id and b.repair_thread_id = v_thread.id and b.cancelled_at is null
              and b.execution in ('not_started', 'deferred')
              and not exists (select 1 from public.plan_blocks s where s.continued_from_task_id = b.id) loop
          update public.plan_blocks set cancelled_at = now(), cancellation_reason = 'evidence_voided', cancellation_source_id = p_challenge_id::text where id = v_task.id;
          insert into public.task_events(user_id, task_id, event_type, payload, previous)
            values (v_challenge.user_id, v_task.id, 'origin_invalidated', jsonb_build_object('reason', 'evidence_voided', 'challengeId', p_challenge_id), jsonb_build_object('execution', v_task.execution));
          v_cancelled_tasks := v_cancelled_tasks + 1;
        end loop;
      end loop;
    end loop;
    -- A re-check whose every repair is cancelled no longer has a reason to exist (if it has not been started).
    for v_task in select b.id from public.plan_blocks b
        where b.user_id = v_challenge.user_id and b.task_type = 'recheck' and b.cancelled_at is null and b.execution in ('not_started', 'deferred') and b.attempt_id is null
          and exists (select 1 from public.repair_check_threads l where l.check_task_id = b.id)
          and not exists (select 1 from public.repair_check_threads l join public.repair_threads t on t.id = l.thread_id
                           where l.check_task_id = b.id and t.status not in ('closed', 'cancelled', 'superseded')) loop
      update public.plan_blocks set cancelled_at = now(), cancellation_reason = 'evidence_voided', cancellation_source_id = p_challenge_id::text where id = v_task.id;
      insert into public.task_events(user_id, task_id, event_type, payload, previous)
        values (v_challenge.user_id, v_task.id, 'origin_invalidated', jsonb_build_object('reason', 'evidence_voided', 'challengeId', p_challenge_id), '{}'::jsonb);
      v_cancelled_tasks := v_cancelled_tasks + 1;
    end loop;
  end if;

  return json_build_object('ok', true, 'challengeId', p_challenge_id, 'resolution', p_resolution,
    'cancelledThreads', v_cancelled_threads, 'cancelledTasks', v_cancelled_tasks)::jsonb;
end;
$$;


--
-- Name: reverse_redistribution(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_redistribution(p_user uuid, p_source text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_rec public.redistribution_receipts%rowtype; v_c jsonb; v_row public.plan_blocks%rowtype; v_back jsonb := '[]'::jsonb; v_kept jsonb := '[]'::jsonb;
begin
  perform public.scope_lock(p_user);
  select * into v_rec from public.redistribution_receipts where source_task_id = p_source and user_id = p_user and reversed_at is null for update;
  if not found then return jsonb_build_object('ok', true, 'reversed', '[]'::jsonb, 'kept', '[]'::jsonb); end if;
  for v_c in select value from jsonb_array_elements(v_rec.changes) order by value->>'task_id' loop
    select * into v_row from public.plan_blocks where id = v_c->>'task_id' and user_id = p_user for update;
    if found and v_row.execution = 'not_started' and v_row.duration_minutes = (v_c->>'after')::int then
      update public.plan_blocks set duration_minutes = (v_c->>'before')::int, duration = (v_c->>'before') where id = v_row.id;
      v_back := v_back || jsonb_build_array(v_c);
    else v_kept := v_kept || jsonb_build_array(v_c); end if;
  end loop;
  update public.redistribution_receipts set reversed_at = now() where id = v_rec.id;
  return jsonb_build_object('ok', true, 'reversed', v_back, 'kept', v_kept);
end $$;


--
-- Name: save_attempt_response(uuid, text, integer, integer, integer, integer, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_attempt_response(p_attempt_id uuid, p_item_id text, p_selected_option integer, p_confidence integer, p_active_seconds integer, p_interrupted_seconds integer, p_flagged boolean, p_client_seq bigint DEFAULT NULL::bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_attempt public.assessment_attempts%rowtype;
  v_key smallint;
  v_options jsonb;
  v_correct boolean;
  v_existing public.assessment_responses%rowtype;
  v_id uuid;
begin
  if v_user is null then raise exception 'Unauthorized'; end if;
  if p_confidence is null or p_confidence not in (1, 3, 5) then raise exception 'Confidence is required'; end if;

  select * into v_attempt from public.assessment_attempts where id = p_attempt_id and user_id = v_user for update;
  if not found then raise exception 'Attempt not found'; end if;
  if v_attempt.status not in ('ready', 'in_progress', 'assembling') then raise exception 'Attempt is %', v_attempt.status; end if;
  if v_attempt.paused_at is not null then raise exception 'Attempt is paused'; end if;
  if v_attempt.rehearsal_id is not null and v_attempt.deadline_at is null then raise exception 'Session not started'; end if;
  -- A timed session accepts answers until its deadline (plus a few seconds' grace for the last save).
  if v_attempt.deadline_at is not null and now() > v_attempt.deadline_at + interval '10 seconds' then raise exception 'Time is up'; end if;

  if not exists (select 1 from public.form_items where form_id = v_attempt.form_id and item_id = p_item_id) then raise exception 'Item not in form'; end if;
  select key_index, options into v_key, v_options from public.assessment_items where id = p_item_id;
  if v_key is null then raise exception 'Item not found'; end if;
  if p_selected_option is null or p_selected_option < 0 or p_selected_option >= jsonb_array_length(v_options) then raise exception 'That option does not exist'; end if;
  v_correct := (p_selected_option = v_key);

  select * into v_existing from public.assessment_responses where attempt_id = p_attempt_id and item_id = p_item_id;
  if found then
    -- Ordering: the attempt row is locked above, so requests are serial, but they can ARRIVE out of order (a slow earlier request, a second tab, a
    -- retry). A choice stamped older than the stored one must not replace it; the same stamp is a retry and is idempotent.
    if p_client_seq is not null and v_existing.client_seq is not null and p_client_seq < v_existing.client_seq then
      raise exception 'Stale answer' using errcode = 'ST409';
    end if;
    update public.assessment_responses set client_seq = nullif(greatest(coalesce(client_seq, 0), coalesce(p_client_seq, 0)), 0),
      selected_option_index = p_selected_option, is_correct = v_correct, self_reported_confidence = p_confidence,
      active_seconds = greatest(coalesce(active_seconds, 0), coalesce(p_active_seconds, 0)),
      interrupted_seconds = greatest(interrupted_seconds, coalesce(p_interrupted_seconds, 0)),
      flagged = coalesce(p_flagged, flagged), answered_at = now(),
      changed_count = changed_count + case when selected_option_index is distinct from p_selected_option or self_reported_confidence is distinct from p_confidence then 1 else 0 end,
      elapsed_seconds = greatest(coalesce(elapsed_seconds, 0), coalesce(p_active_seconds, 0))
    where id = v_existing.id returning id into v_id;
  else
    insert into public.assessment_responses (user_id, attempt_id, item_id, selected_option_index, is_correct, self_reported_confidence,
      elapsed_seconds, active_seconds, interrupted_seconds, flagged, answered_at, client_seq)
    values (v_user, p_attempt_id, p_item_id, p_selected_option, v_correct, p_confidence,
      p_active_seconds, p_active_seconds, coalesce(p_interrupted_seconds, 0), coalesce(p_flagged, false), now(), p_client_seq)
    returning id into v_id;
  end if;

  if v_attempt.status in ('ready', 'assembling') then
    update public.assessment_attempts set status = 'in_progress', started_at = coalesce(started_at, now()) where id = p_attempt_id;
  end if;
  return json_build_object('id', v_id);
end;
$$;


--
-- Name: scope_lock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scope_lock(p_user uuid) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select pg_advisory_xact_lock(hashtextextended('scope:' || p_user::text, 0))
$$;


--
-- Name: scope_write_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scope_write_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_user uuid;
begin
  v_user := case when tg_op = 'DELETE' then old.user_id else new.user_id end;
  if v_user is not null then perform public.scope_lock(v_user); end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;


--
-- Name: scope_write_lock_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.scope_write_lock_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_user uuid;
begin
  select s.user_id into v_user from public.class_sessions s where s.id = case when tg_op = 'DELETE' then old.session_id else new.session_id end;
  if v_user is not null then perform public.scope_lock(v_user); end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;


--
-- Name: set_item_holdout(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_item_holdout(p_family_id uuid, p_item_id text, p_held_out boolean, p_reason text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_reason text := coalesce(btrim(p_reason), '');
begin
  if v_uid is null or not public.is_item_reviewer() then return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'message', 'Only a reviewer can change a hold-out.'); end if;
  if p_held_out and char_length(v_reason) < 3 then return jsonb_build_object('ok', false, 'code', 'NOTE_REQUIRED', 'message', 'Say why this is held out.'); end if;
  if p_family_id is not null then
    update public.item_families set held_out = p_held_out, held_out_reason = case when p_held_out then v_reason else null end,
      held_out_by = v_uid, held_out_at = now() where id = p_family_id;
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown family.'); end if;
    update public.assessment_items set held_out = p_held_out where family_id = p_family_id;
  elsif p_item_id is not null then
    -- Family unknown: only this one item is held out. Its unknown relatives cannot be inferred from a text hash.
    update public.assessment_items set held_out = p_held_out where id = p_item_id and family_id is null;
    if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'message', 'Unknown item, or it belongs to a family (hold out the family).'); end if;
    insert into public.item_revisions(item_id, item_version, kind, actor_id, summary)
      select id, item_version, 'holdout', v_uid, case when p_held_out then 'Held out: ' || v_reason else 'Hold-out released' end from public.assessment_items where id = p_item_id;
  else
    return jsonb_build_object('ok', false, 'code', 'INVALID', 'message', 'Name a family or an item.');
  end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: set_task_execution(uuid, text, integer, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_task_execution(p_user_id uuid, p_task_id text, p_expected_revision integer, p_execution text, p_actual_duration_minutes integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_task public.plan_blocks%rowtype;
  v_before jsonb;
  v_request jsonb;
  v_receipt public.task_execution_commands%rowtype;
  v_event_id uuid;
  v_event_type text;
begin
  if v_user_id is null or v_user_id is distinct from p_user_id then
    raise exception 'Sign in to update your task.' using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users where id = v_user_id and email_confirmed_at is not null) then
    raise exception 'Verify your email before using your plan.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = v_user_id and onboarding_status = 'complete') then
    raise exception 'Complete setup before updating your plan.' using errcode = '42501';
  end if;
  if p_expected_revision is null or p_expected_revision < 1
    or p_execution is null or p_execution not in ('not_started', 'in_progress', 'partial', 'completed', 'skipped', 'deferred')
    or (p_actual_duration_minutes is not null and p_actual_duration_minutes not between 0 and 1440)
    or (p_note is not null and length(p_note) > 2000) then
    raise exception 'Invalid task execution input.' using errcode = '22023';
  end if;

  -- Lock only the owned task. Concurrent retries serialize here; another
  -- learner cannot discover the task, its receipt or its current revision.
  select * into v_task from public.plan_blocks
    where id = p_task_id and user_id = v_user_id for update;
  if not found then
    raise exception 'Task not found.' using errcode = 'P0002';
  end if;
  -- A paper or a repair re-check is completed by being taken and scored, never by the student marking the task done: this command cannot
  -- represent one as finished, started or partly done. (Deferring or skipping it is still a statement the student can make.)
  if v_task.task_type in ('diagnostic', 'recheck') and p_execution in ('completed', 'partial', 'in_progress') then
    raise exception 'SYSTEM_ASSESSMENT: a % is completed by taking and scoring it, not by marking it done', case v_task.task_type when 'diagnostic' then 'paper' else 'check' end using errcode = '22023';
  end if;
  v_request := jsonb_build_object('execution', p_execution,
    'actual_duration_minutes', p_actual_duration_minutes, 'note', p_note);
  select * into v_receipt from public.task_execution_commands
    where task_id = p_task_id and expected_revision = p_expected_revision and user_id = v_user_id;
  if found then
    if v_receipt.request = v_request then
      return jsonb_build_object('ok', true, 'replayed', true, 'task', to_jsonb(v_task), 'eventId', v_receipt.event_id);
    end if;
    return jsonb_build_object('ok', false, 'code', 'REVISION_MISMATCH', 'current', to_jsonb(v_task));
  end if;
  if v_task.revision <> p_expected_revision then
    return jsonb_build_object('ok', false, 'code', 'REVISION_MISMATCH', 'current', to_jsonb(v_task));
  end if;
  if v_task.execution = 'cancelled' then
    raise exception 'This task was cancelled. Review its origin before restoring it.' using errcode = '22023';
  end if;

  v_before := jsonb_build_object('local_date', v_task.local_date, 'starts_at', v_task.starts_at,
    'duration_minutes', v_task.duration_minutes, 'placement', v_task.placement,
    'execution', v_task.execution, 'revision', v_task.revision);
  -- Every accepted execution command advances the revision, even recording
  -- actual time against an otherwise unchanged state. The existing revision
  -- trigger also sets this to old+1 (it does not increment it twice).
  update public.plan_blocks set execution = p_execution, revision = revision + 1
    where id = p_task_id and user_id = v_user_id returning * into v_task;
  v_event_type := case p_execution
    when 'not_started' then 'undone' when 'in_progress' then 'started'
    else p_execution end;
  insert into public.task_events(user_id, task_id, event_type, payload, previous, actual_duration_minutes, notes)
    values (v_user_id, p_task_id, v_event_type,
      jsonb_build_object('execution', p_execution, 'note', p_note), v_before, p_actual_duration_minutes, p_note)
    returning id into v_event_id;
  insert into public.task_execution_commands(task_id, expected_revision, user_id, request, event_id)
    values (p_task_id, p_expected_revision, v_user_id, v_request, v_event_id);
  -- No evidence, confidence, curriculum scope or calendar redistribution is
  -- guessed here. Only the task and its factual activity history are committed.
  return jsonb_build_object('ok', true, 'replayed', false, 'task', to_jsonb(v_task), 'eventId', v_event_id);
end;
$$;


--
-- Name: split_study_task(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_study_task(p_user_id uuid, p_task_id text, p_expected_revision integer, p_first_minutes integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_task public.plan_blocks%rowtype;
  v_second public.plan_blocks%rowtype;
  v_receipt public.task_split_commands%rowtype;
  v_group uuid;
  v_first integer;
  v_original jsonb;
begin
  if auth.uid() is null or auth.uid() is distinct from p_user_id
    or not exists (select 1 from auth.users where id = auth.uid() and email_confirmed_at is not null)
    or not exists (select 1 from public.profiles where id = auth.uid() and onboarding_status = 'complete') then
    raise exception 'Verify your account and finish setup before editing your plan.' using errcode = '42501';
  end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'A valid task revision is required.' using errcode = '22023';
  end if;
  select * into v_task from public.plan_blocks where id = p_task_id and user_id = p_user_id for update;
  if not found then raise exception 'Task not found.' using errcode = 'P0002'; end if;
  select * into v_receipt from public.task_split_commands where task_id = p_task_id and expected_revision = p_expected_revision and user_id = p_user_id;
  if found then
    if v_receipt.requested_minutes is not distinct from p_first_minutes and v_receipt.second_task_id is not null then
      return jsonb_build_object('ok',true,'task',to_jsonb(v_task),'secondId',v_receipt.second_task_id,'replayed',true);
    end if;
    return jsonb_build_object('ok',false,'code','REVISION_MISMATCH','current',to_jsonb(v_task));
  end if;
  if v_task.revision <> p_expected_revision then
    return jsonb_build_object('ok',false,'code','REVISION_MISMATCH','current',to_jsonb(v_task));
  end if;
  if v_task.task_type is null or v_task.task_type not in ('study','review','class_consolidation')
    or v_task.execution not in ('not_started','in_progress','partial') or v_task.cancelled_at is not null
    or v_task.is_protected_commitment or v_task.duration_minutes is null or v_task.duration_minutes < 30 then
    raise exception 'Split unfinished study or review work of at least 30 minutes. Tests and protected commitments stay intact.' using errcode = '22023';
  end if;
  v_first := coalesce(p_first_minutes, floor(v_task.duration_minutes / 10.0)::integer * 5);
  if v_first < 15 or v_first > v_task.duration_minutes - 15 or v_first % 5 <> 0 then
    raise exception 'Each sitting needs at least 15 minutes; use a whole 5-minute split point.' using errcode = '22023';
  end if;
  v_original := to_jsonb(v_task);
  v_group := v_task.scope_group_id;
  if v_group is null then
    insert into public.task_scope_groups(user_id,original_task_id,expected_parts,original_scope)
      values (p_user_id,p_task_id,2,v_original) returning id into v_group;
  else
    -- The group row serializes concurrent splits of different sittings.
    update public.task_scope_groups set expected_parts = expected_parts + 1 where id = v_group and user_id = p_user_id;
    if not found then raise exception 'The shared learning scope could not be checked.' using errcode = '22023'; end if;
  end if;
  -- Copy the complete row (LOS, reading, purpose, provenance and method), then
  -- override only the new sitting's identity, execution, placement and length.
  v_second := jsonb_populate_record(null::public.plan_blocks, v_original || jsonb_build_object(
    'id','task-' || gen_random_uuid()::text,'title',v_task.title || ' (continued)',
    'scope_group_id',v_group,'duration_minutes',v_task.duration_minutes - v_first,
    'duration',(v_task.duration_minutes - v_first)::text,'execution','not_started',
    'starts_at',null,'local_date',null,'placement','floating','state','floating',
    'revision',1,'updated_at',now(),'created_by','student'
  ));
  update public.plan_blocks set duration_minutes = v_first, duration = v_first::text,
    scope_group_id = v_group, revision = revision + 1
    where id = p_task_id and user_id = p_user_id returning * into v_task;
  insert into public.plan_blocks select (v_second).*;
  insert into public.task_events(user_id,task_id,event_type,payload,previous) values
    (p_user_id,p_task_id,'split',jsonb_build_object('splitInto',v_second.id,'firstDuration',v_first,'secondDuration',v_second.duration_minutes,'scope_group_id',v_group),v_original),
    (p_user_id,v_second.id,'created',jsonb_build_object('splitFrom',p_task_id,'scope_group_id',v_group),'{}'::jsonb);
  insert into public.task_split_commands(task_id,expected_revision,user_id,requested_minutes,second_task_id)
    values (p_task_id,p_expected_revision,p_user_id,p_first_minutes,v_second.id);
  return jsonb_build_object('ok',true,'task',to_jsonb(v_task),'secondId',v_second.id,'replayed',false);
end; $$;


--
-- Name: start_assessment_paper(uuid, text, text, uuid, text, text, uuid, text[], integer, jsonb, jsonb, jsonb, jsonb, jsonb, text, text, integer, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_assessment_paper(p_user uuid, p_kind text, p_open_key text, p_cycle uuid, p_paper_kind text, p_purpose text, p_manifest uuid, p_item_ids text[], p_min integer, p_requested_scope jsonb, p_constraints jsonb, p_requested jsonb, p_coverage jsonb, p_scope jsonb, p_scope_label text, p_scope_revision text, p_time_limit integer, p_link_block text, p_link_weekly boolean, p_scope_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_open public.assessment_attempts%rowtype;
  v_bp uuid; v_form uuid; v_attempt uuid; v_defects jsonb; v_block text;
  v_n int := coalesce(array_length(p_item_ids, 1), 0);
begin
  if p_cycle is not null and not exists (select 1 from public.planning_cycles c where c.id = p_cycle and c.user_id = p_user and c.status = 'active') then
    return jsonb_build_object('ok', false, 'code', 'CYCLE_CHANGED');
  end if;
  if p_open_key is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_user::text || ':' || coalesce(p_kind, '') || ':' || p_open_key, 0));
    select * into v_open from public.assessment_attempts
     where user_id = p_user and attempt_kind is not distinct from p_kind and open_key = p_open_key and status in ('ready', 'in_progress', 'assembling')
     order by started_at desc nulls last limit 1;
    if found then
      return jsonb_build_object('ok', true, 'resumed', true, 'attemptId', v_open.id, 'questions', (select count(*) from public.form_items where form_id = v_open.form_id));
    end if;
  end if;
  -- Scope writers update or lock plan rows through their own commands; holding the rows FOR SHARE makes them wait for this
  -- reservation, and the version is compared AFTER the lock so an edit that landed since the student looked is seen.
  if p_scope_source is not null then
    perform public.scope_lock(p_user);
    if public.paper_scope_source(p_user) is distinct from p_scope_source then
      return jsonb_build_object('ok', false, 'code', 'SCOPE_CHANGED');
    end if;
  end if;
  if v_n < p_min then return jsonb_build_object('ok', false, 'code', 'BANK_INSUFFICIENT', 'deliverable', v_n, 'needed', p_min); end if;
  if v_n > 90 then raise exception 'A paper cannot exceed 90 questions.' using errcode = '22023'; end if;
  v_defects := public.paper_item_defects(p_user, p_item_ids);
  if jsonb_array_length(v_defects) > 0 then return jsonb_build_object('ok', false, 'code', 'BANK_CHANGED', 'defects', v_defects); end if;

  insert into public.assessment_blueprints(manifest_id, purpose, requested_scope, constraints) values (p_manifest, p_purpose, p_requested_scope, p_constraints) returning id into v_bp;
  insert into public.assessment_forms(blueprint_id, delivery_mode) values (v_bp, 'fixed') returning id into v_form;
  insert into public.form_items(form_id, item_id, sequence_number) select v_form, x.item, x.ord from unnest(p_item_ids) with ordinality as x(item, ord);
  insert into public.assessment_attempts(user_id, form_id, delivery_mode, status, attempt_kind, paper_kind, cycle_id, open_key, requested_blueprint, delivered_coverage, eligibility_policy,
                                         time_limit_minutes, deadline_at)
    values (p_user, v_form, 'fixed', 'ready', p_kind, p_paper_kind, p_cycle, p_open_key, p_requested, p_coverage, 'approved-version-v1',
            p_time_limit, case when p_time_limit is null then null else now() + make_interval(mins => p_time_limit) end) returning id into v_attempt;
  if p_scope is not null then
    insert into public.paper_scope_snapshots(user_id, cycle_id, purpose, revision, scope, attempt_id)
      values (p_user, p_cycle, p_scope_label, coalesce(p_scope_revision, 'n/a'), p_scope, v_attempt);
  end if;
  if p_link_block is not null then
    update public.plan_blocks set attempt_id = v_attempt where id = p_link_block and user_id = p_user and attempt_id is null returning id into v_block;
    if v_block is null then raise exception 'BLOCK_ALREADY_CLAIMED' using errcode = 'P0001'; end if;
  elsif p_link_weekly and p_cycle is not null then
    update public.plan_blocks set attempt_id = v_attempt
     where id = (select b.id from public.plan_blocks b where b.user_id = p_user and b.cycle_id = p_cycle and b.task_type = 'diagnostic' and b.attempt_id is null order by b.local_date limit 1 for update skip locked);
  end if;
  return jsonb_build_object('ok', true, 'resumed', false, 'attemptId', v_attempt, 'questions', v_n);
end; $$;


--
-- Name: start_paper_checked(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_paper_checked(p_user uuid, p_evidence text, p_levels jsonb, p_paper jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.scope_lock(p_user);
  if p_evidence is not null and public.difficulty_evidence_version(p_user) is distinct from p_evidence then
    return jsonb_build_object('ok', false, 'code', 'DECISION_CHANGED');
  end if;
  if not public._lock_check_levels(p_paper->'itemIds', p_levels) then return jsonb_build_object('ok', false, 'code', 'DECISION_CHANGED'); end if;
  return public._reserve_paper_json(p_user, p_paper);
end $$;


--
-- Name: start_rehearsal(uuid, uuid, uuid, text[], text[], jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_rehearsal(p_user uuid, p_appointment uuid, p_manifest uuid, p_s1 text[], p_s2 text[], p_blueprint jsonb, p_version text, p_coverage jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_appt public.mock_appointments%rowtype; v_open public.mock_rehearsals%rowtype; v_r uuid; v_defects jsonb; v_s int; v_ids text[]; v_bp uuid; v_form uuid; v_att uuid;
  v_attempts jsonb := '[]'::jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('rehearsal:' || p_user::text || ':' || p_appointment::text, 0));
  select * into v_appt from public.mock_appointments where id = p_appointment and user_id = p_user for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NO_APPOINTMENT'); end if;
  if v_appt.kind <> 'internal_rehearsal' then return jsonb_build_object('ok', false, 'code', 'NOT_INTERNAL'); end if;
  if v_appt.status <> 'planned' then return jsonb_build_object('ok', false, 'code', 'APPOINTMENT_CLOSED'); end if;
  select * into v_open from public.mock_rehearsals where appointment_id = p_appointment and status in ('ready', 'in_progress');
  if found then return jsonb_build_object('ok', true, 'resumed', true, 'rehearsalId', v_open.id); end if;
  if coalesce(array_length(p_s1, 1), 0) <> 90 or coalesce(array_length(p_s2, 1), 0) <> 90 then
    return jsonb_build_object('ok', false, 'code', 'BANK_INSUFFICIENT', 'deliverable', jsonb_build_array(coalesce(array_length(p_s1, 1), 0), coalesce(array_length(p_s2, 1), 0)));
  end if;
  v_defects := public.rehearsal_item_defects(p_user, p_s1 || p_s2);
  if jsonb_array_length(v_defects) > 0 then return jsonb_build_object('ok', false, 'code', 'BANK_CHANGED', 'defects', v_defects); end if;

  insert into public.mock_rehearsals (user_id, appointment_id, manifest_id, blueprint_version, blueprint) values (p_user, p_appointment, p_manifest, p_version, p_blueprint) returning id into v_r;
  perform set_config('app.holdout_form', 'on', true);
  for v_s in 1..2 loop
    v_ids := case when v_s = 1 then p_s1 else p_s2 end;
    insert into public.assessment_blueprints (manifest_id, purpose, requested_scope, constraints)
      values (p_manifest, 'mock_session', jsonb_build_object('kind', 'rehearsal', 'rehearsalId', v_r, 'session', v_s), jsonb_build_object('questions', 90, 'minutes', 135, 'heldOut', true, 'eligibility', 'approved-version-v1', 'blueprintVersion', p_version))
      returning id into v_bp;
    insert into public.assessment_forms (blueprint_id, delivery_mode, rehearsal_id, session_no) values (v_bp, 'fixed', v_r, v_s) returning id into v_form;
    insert into public.form_items (form_id, item_id, sequence_number) select v_form, x.item, x.ord from unnest(v_ids) with ordinality as x(item, ord);
    -- deadline_at stays NULL until the student explicitly starts the session.
    insert into public.assessment_attempts (user_id, form_id, delivery_mode, status, attempt_kind, paper_kind, open_key, requested_blueprint, delivered_coverage, eligibility_policy, time_limit_minutes, rehearsal_id, session_no)
      values (p_user, v_form, 'fixed', 'ready', 'mock', 'mixed', 'rehearsal:' || v_r || ':s' || v_s, p_blueprint, coalesce(p_coverage->(v_s::text), '{}'::jsonb), 'approved-version-v1', 135, v_r, v_s) returning id into v_att;
    v_attempts := v_attempts || jsonb_build_array(v_att);
  end loop;
  perform set_config('app.holdout_form', 'off', true);
  return jsonb_build_object('ok', true, 'resumed', false, 'rehearsalId', v_r, 'attempts', v_attempts);
end $$;


--
-- Name: start_rehearsal_session(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_rehearsal_session(p_user uuid, p_attempt uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_a public.assessment_attempts%rowtype; v_r public.mock_rehearsals%rowtype; v_prev public.assessment_attempts%rowtype;
begin
  select * into v_a from public.assessment_attempts where id = p_attempt and user_id = p_user and rehearsal_id is not null for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  select * into v_r from public.mock_rehearsals where id = v_a.rehearsal_id for update;
  if v_r.status in ('cancelled', 'abandoned') then return jsonb_build_object('ok', false, 'code', 'REHEARSAL_CLOSED'); end if;
  if v_a.status in ('scored', 'expired', 'submitted', 'abandoned', 'rescored', 'partially_voided') then return jsonb_build_object('ok', false, 'code', 'SESSION_ENDED'); end if;
  if v_a.deadline_at is not null then return jsonb_build_object('ok', true, 'started', false, 'deadlineAt', v_a.deadline_at); end if;
  if v_a.session_no = 2 then
    select * into v_prev from public.assessment_attempts where rehearsal_id = v_a.rehearsal_id and session_no = 1;
    if v_prev.status not in ('scored', 'expired', 'rescored', 'partially_voided', 'abandoned') then return jsonb_build_object('ok', false, 'code', 'SESSION_1_OPEN'); end if;
  end if;
  update public.assessment_attempts set status = 'in_progress', started_at = now(), deadline_at = now() + make_interval(mins => time_limit_minutes) where id = p_attempt returning * into v_a;
  update public.mock_rehearsals set status = 'in_progress' where id = v_r.id and status = 'ready';
  return jsonb_build_object('ok', true, 'started', true, 'deadlineAt', v_a.deadline_at);
end $$;


--
-- Name: start_repair_check(uuid, text, text[], uuid, jsonb, jsonb, jsonb, jsonb, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_repair_check(p_user uuid, p_check_task_id text, p_item_ids text[], p_manifest uuid, p_blueprint jsonb, p_constraints jsonb, p_requested jsonb, p_coverage jsonb, p_scope jsonb, p_min_questions integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_task public.plan_blocks%rowtype;
  v_open public.assessment_attempts%rowtype;
  v_waiting uuid[];
  v_bp uuid; v_form uuid; v_attempt uuid;
  v_n int := coalesce(array_length(p_item_ids, 1), 0);
begin
  -- planning input serialization
  perform public.scope_lock(p_user);
  select * into v_task from public.plan_blocks where id = p_check_task_id and user_id = p_user for update;
  if not found or v_task.task_type <> 'recheck' or v_task.cancelled_at is not null or v_task.execution in ('completed', 'skipped', 'cancelled') then
    return jsonb_build_object('ok', false, 'code', 'CHECK_UNAVAILABLE');
  end if;
  if exists (select 1 from public.plan_blocks s where s.continued_from_task_id = v_task.id) then
    return jsonb_build_object('ok', false, 'code', 'CHECK_UNAVAILABLE');
  end if;

  -- An attempt already started for this check is resumed even if its own questions are no longer "unseen".
  if v_task.attempt_id is not null then
    select * into v_open from public.assessment_attempts where id = v_task.attempt_id and user_id = p_user and status in ('ready', 'in_progress');
    if found then return jsonb_build_object('ok', true, 'resumed', true, 'attemptId', v_open.id,
        'questions', (select count(*) from public.form_items where form_id = v_open.form_id)); end if;
  end if;

  select array_agg(t.id) into v_waiting from public.repair_check_threads l join public.repair_threads t on t.id = l.thread_id
    where l.check_task_id = p_check_task_id and t.user_id = p_user and t.status not in ('closed', 'cancelled', 'superseded') and t.status <> 'awaiting_recheck';
  if v_waiting is not null then return jsonb_build_object('ok', false, 'code', 'WAITING_ON_REPAIRS', 'threadIds', to_jsonb(v_waiting)); end if;
  if not exists (select 1 from public.repair_check_threads l join public.repair_threads t on t.id = l.thread_id
                  where l.check_task_id = p_check_task_id and t.user_id = p_user and t.status = 'awaiting_recheck') then
    return jsonb_build_object('ok', false, 'code', 'NOTHING_TO_CHECK');
  end if;

  if v_n < p_min_questions then return jsonb_build_object('ok', false, 'code', 'BANK_INSUFFICIENT', 'deliverable', v_n, 'needed', p_min_questions); end if;
  if v_n > 90 then raise exception 'A paper cannot exceed 90 questions.' using errcode = '22023'; end if;
  if jsonb_array_length(public.paper_item_defects(p_user, p_item_ids, true)) > 0 then
    return jsonb_build_object('ok', false, 'code', 'BANK_CHANGED');
  end if;
  -- Every question must belong to a concept of a repair this check is for. An unrelated concept cannot fill the paper.
  if exists (select 1 from public.assessment_items i where i.id = any(p_item_ids) and (i.concept_id is null or not exists (
      select 1 from public.repair_check_threads l join public.repair_threads t on t.id = l.thread_id
       where l.check_task_id = p_check_task_id and t.concept_id = i.concept_id))) then
    raise exception 'A question is outside the repairs this check is for.' using errcode = '22023';
  end if;

  insert into public.assessment_blueprints(manifest_id, purpose, requested_scope, constraints) values (p_manifest, 'repair_recheck', p_blueprint, p_constraints) returning id into v_bp;
  insert into public.assessment_forms(blueprint_id, delivery_mode) values (v_bp, 'fixed') returning id into v_form;
  insert into public.form_items(form_id, item_id, sequence_number) select v_form, x.item, x.ord from unnest(p_item_ids) with ordinality as x(item, ord);
  insert into public.assessment_attempts(user_id, form_id, delivery_mode, status, attempt_kind, cycle_id, open_key, requested_blueprint, delivered_coverage, eligibility_policy)
    values (p_user, v_form, 'fixed', 'ready', 'repair', v_task.cycle_id, 'check:' || p_check_task_id, p_requested, p_coverage, 'approved-version-v1') returning id into v_attempt;
  insert into public.paper_scope_snapshots(user_id, cycle_id, purpose, revision, scope, attempt_id)
    values (p_user, v_task.cycle_id, 'repair_check', 'repair-loop-1', p_scope, v_attempt);
  update public.plan_blocks set attempt_id = v_attempt where id = p_check_task_id;
  return jsonb_build_object('ok', true, 'resumed', false, 'attemptId', v_attempt, 'questions', v_n);
end; $$;


--
-- Name: store_batch_cell(uuid, integer, uuid, jsonb, jsonb, text, text, text, jsonb, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_batch_cell(p_batch uuid, p_ordinal integer, p_claim uuid, p_item jsonb, p_gates jsonb, p_verdict text, p_reason text, p_model text, p_extra jsonb, p_generate_ms integer, p_usage jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_c public.item_batch_cells%rowtype; v_b public.item_batches%rowtype; v_id text; v_family uuid; v_fp text := p_item->>'semantic_fingerprint';
begin
  select * into v_b from public.item_batches where id = p_batch for share;
  select * into v_c from public.item_batch_cells where batch_id = p_batch and ordinal = p_ordinal for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_c.claim_token is distinct from p_claim then
    update public.item_batch_attempts set outcome = 'stale_refused', finished_at = now() where batch_id = p_batch and ordinal = p_ordinal and claim_token = p_claim and outcome is null;
    return jsonb_build_object('ok', false, 'code', 'STALE_CLAIM');
  end if;
  if v_c.status = 'drafted' then return jsonb_build_object('ok', true, 'repeated', true, 'itemId', v_c.item_id); end if;
  if v_b.status in ('cancelled', 'budget_exhausted') then return jsonb_build_object('ok', false, 'code', 'CANCELLED'); end if;
  if v_c.status <> 'running' then return jsonb_build_object('ok', false, 'code', 'NOT_RUNNING'); end if;
  v_id := 'bq-' || left(replace(p_batch::text, '-', ''), 8) || '-' || p_ordinal;
  -- Equivalent output from two workers is decided here, under a lock on the fingerprint, not in either worker's memory.
  if v_fp is not null then
    perform pg_advisory_xact_lock(hashtext('fp:' || v_fp));
    if exists (select 1 from public.assessment_items where semantic_fingerprint = v_fp and id <> v_id) then
      update public.item_batch_cells set status = case when attempts >= v_b.max_attempts then 'failed' else 'pending' end, lease_until = null, verdict = 'DUPLICATE',
          defect_codes = array['DUPLICATE_OUTPUT'], failure_reason = 'An equivalent question already exists (same normalised construction).', generate_ms = p_generate_ms, provider_usage = p_usage, updated_at = now()
        where batch_id = p_batch and ordinal = p_ordinal;
      update public.item_batch_attempts set outcome = 'duplicate', code = 'DUPLICATE_OUTPUT', finished_at = now(), ms = p_generate_ms, usage = p_usage where batch_id = p_batch and ordinal = p_ordinal and claim_token = p_claim;
      perform public._settle_batch(p_batch);
      return jsonb_build_object('ok', false, 'code', 'DUPLICATE_OUTPUT');
    end if;
  end if;
  insert into public.item_families(family_key, note, construction_status) values ('fam-' || v_id, 'Provisional: one unconfirmed construction from batch ' || v_b.label, 'provisional') on conflict (family_key) do nothing;
  select id into v_family from public.item_families where family_key = 'fam-' || v_id;
  insert into public.assessment_items(id, lm_id, learning_objective, verification_intent, difficulty, stem, options, per_option_feedback, provenance, review_status,
      concept_id, cognition, item_form, intended_difficulty, key_index, item_card, semantic_fingerprint, generator_model, outcome_id, family_id, batch_id)
    values (v_id, p_item->>'lm_id', p_item->>'learning_objective', p_item->>'verification_intent', (p_item->>'difficulty')::numeric, p_item->>'stem', p_item->'options',
      p_item->'per_option_feedback', 'Generated candidate, batch ' || v_b.label || ' (' || v_b.curriculum_version || ')', 'draft',
      (p_item->>'concept_id')::uuid, p_item->>'cognition', p_item->>'item_form', p_item->>'intended_difficulty', (p_item->>'key_index')::int, p_item->'item_card',
      v_fp, p_item->>'generator_model', p_item->>'outcome_id', v_family, p_batch)
    on conflict (id) do nothing;
  insert into public.item_revisions(item_id, item_version, kind, summary) values (v_id, 1, 'created', 'Generated in batch ' || v_b.label);
  perform public._write_item_verdict(v_id, 1, p_gates, p_verdict, p_reason, p_model, p_extra);
  update public.item_batch_cells set status = 'drafted', item_id = v_id, verdict = p_verdict, failure_reason = null, lease_until = null,
    generate_ms = p_generate_ms, provider_usage = p_usage, updated_at = now() where batch_id = p_batch and ordinal = p_ordinal;
  update public.item_batch_attempts set outcome = 'drafted', code = p_verdict, finished_at = now(), ms = p_generate_ms, usage = p_usage where batch_id = p_batch and ordinal = p_ordinal and claim_token = p_claim;
  perform public._settle_batch(p_batch);
  return jsonb_build_object('ok', true, 'itemId', v_id);
end $$;


--
-- Name: store_item_verification(text, integer, jsonb, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_item_verification(p_item_id text, p_expected_version integer, p_gates jsonb, p_verdict text, p_reason text, p_model text, p_extra jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_item public.assessment_items%rowtype; v_status text;
begin
  select * into v_item from public.assessment_items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'NOT_FOUND'); end if;
  if v_item.item_version <> p_expected_version then return jsonb_build_object('ok', false, 'code', 'STALE_VERSION', 'message', 'The item was edited while it was being checked; the result was discarded.'); end if;
  if v_item.review_status in ('reviewed', 'deprecated') then return jsonb_build_object('ok', false, 'code', 'IMMUTABLE', 'message', 'A published or retired item is not re-checked in place; edit it to create a new version.'); end if;
  v_status := public._write_item_verdict(p_item_id, p_expected_version, p_gates, p_verdict, p_reason, p_model, p_extra);
  return jsonb_build_object('ok', true, 'status', v_status, 'verdict', p_verdict);
end $$;


--
-- Name: sync_repair_thread_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_repair_thread_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_thread uuid := coalesce(new.repair_thread_id, old.repair_thread_id);
  v_type text := coalesce(new.task_type, old.task_type);
  v_status text; v_total int; v_done int; v_started int; v_next text;
begin
  if v_thread is null or v_type is distinct from 'repair' then return coalesce(new, old); end if;
  select status into v_status from public.repair_threads where id = v_thread for update;
  if v_status is null or v_status in ('closed', 'cancelled', 'superseded') then return coalesce(new, old); end if;
  if v_status in ('open', 'proposed') and tg_op <> 'INSERT' then return coalesce(new, old); end if;
  -- Logical portions: not cancelled, and not already continued by a later week's task.
  select count(*), count(*) filter (where b.execution = 'completed'), count(*) filter (where b.execution in ('in_progress', 'partial'))
    into v_total, v_done, v_started
  from public.plan_blocks b
  where b.repair_thread_id = v_thread and b.task_type = 'repair' and b.cancelled_at is null and b.execution <> 'cancelled'
    and not exists (select 1 from public.plan_blocks s where s.continued_from_task_id = b.id);
  v_next := case when v_total = 0 then 'open' when v_done = v_total then 'awaiting_recheck'
                 when v_started > 0 or v_done > 0 then 'in_progress' else 'scheduled' end;
  if v_next is distinct from v_status then
    update public.repair_threads set status = v_next, revision = revision + 1, updated_at = now() where id = v_thread;
    insert into public.repair_thread_events(thread_id, event_type, details)
      values (v_thread, 'status_changed', jsonb_build_object('from', v_status, 'to', v_next, 'portions', v_total, 'done', v_done));
  end if;
  return coalesce(new, old);
end; $$;


--
-- Name: update_planning_profile(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_planning_profile(p_user uuid, p_patch jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_patch is null or jsonb_typeof(p_patch)<>'object' or exists (
    select 1 from jsonb_object_keys(p_patch) k where k not in ('display_name','max_session_minutes','prep_mode','classes_completed_at')
  ) then raise exception 'Invalid profile patch'; end if;
  perform public.scope_lock(p_user);
  update public.profiles set
    display_name=case when p_patch ? 'display_name' then p_patch->>'display_name' else display_name end,
    max_session_minutes=case when p_patch ? 'max_session_minutes' then (p_patch->>'max_session_minutes')::smallint else max_session_minutes end,
    prep_mode=case when p_patch ? 'prep_mode' then p_patch->>'prep_mode' else prep_mode end,
    classes_completed_at=case when p_patch ? 'classes_completed_at' then (p_patch->>'classes_completed_at')::date else classes_completed_at end,
    updated_at=now()
  where id=p_user;
  if not found then raise exception 'Profile not found'; end if;
end $$;


--
-- Name: user_module_state_protect_verified(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_module_state_protect_verified() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.source = 'self_report' then
    if new.coverage_state = 'verified' and (tg_op = 'INSERT' or old.coverage_state <> 'verified') then
      raise exception 'SELF_REPORT_CANNOT_VERIFY' using errcode = 'CV409', detail = new.lm_id;
    end if;
    if tg_op = 'UPDATE' and (old.coverage_state = 'verified' or old.source = 'diagnostic')
       and (old.coverage_state, old.source) is distinct from (new.coverage_state, new.source) then
      raise exception 'VERIFIED_COVERAGE_PROTECTED' using errcode = 'CV409', detail = new.lm_id;
    end if;
  end if;
  return new;
end $$;


--
-- Name: weekly_source_version(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_source_version(p_user uuid, p_cycle uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(concat_ws('|',
    (select coalesce(string_agg(concat_ws(':', id, revision, execution, coalesce(cancelled_at::text, ''), coalesce(local_date::text, ''), coalesce(duration_minutes::text, '')), ',' order by id), '')
       from public.plan_blocks where user_id = p_user and cycle_id = p_cycle),
    (select coalesce(string_agg(c.block_id || ':' || c.outcome_id, ',' order by c.block_id, c.outcome_id), '')
       from public.block_scope_confirmations c where c.user_id = p_user
        and c.block_id in (select id from public.plan_blocks where user_id = p_user and cycle_id = p_cycle)),
    (select coalesce(string_agg(a.id::text || ':' || a.status, ',' order by a.id::text), '')
       from public.assessment_attempts a where a.user_id = p_user and a.cycle_id = p_cycle),
    (select coalesce(string_agg(to_jsonb(k)::text, ',' order by k.id::text), '')
       from public.calendar_commitments k where k.user_id = p_user and k.status = 'active'),
    (select coalesce(string_agg(to_jsonb(x)::text, ',' order by x.id::text), '')
       from public.commitment_exceptions x where x.user_id = p_user),
    (select coalesce(string_agg(to_jsonb(e)::text, ',' order by e.id::text), '')
       from public.exam_attempts e where e.user_id = p_user and e.status = 'active'),
    (select p.classes_completed_at::text from public.profiles p where p.id = p_user),
    (select coalesce(string_agg(to_jsonb(w)::text, ',' order by w.id::text), '')
       from public.availability_windows w where w.user_id = p_user and w.status = 'active'),
    (select coalesce(string_agg(to_jsonb(r)::text, ',' order by r.id::text), '')
       from public.repair_threads r where r.user_id = p_user and r.status in ('open', 'proposed', 'scheduled', 'in_progress', 'awaiting_recheck')),
    (select coalesce(string_agg(m.lm_id || ':' || m.coverage_state, ',' order by m.lm_id), '')
       from public.user_module_state m where m.user_id = p_user),
    (select coalesce(string_agg(u.topic_id || ':' || u.level || ':' || array_to_string(u.lm_ids, '+'), ',' order by u.topic_id), '')
       from public.user_entry_uncertainty u where u.user_id = p_user),
    (select coalesce(string_agg(c.week_start::text || ':' || c.choice || ':' || coalesce(c.appointment_id::text, ''), ',' order by c.week_start), '')
       from public.cycle_assessment_choices c where c.user_id = p_user),
    (select coalesce(string_agg(o.id::text || ':' || o.outcome || ':' || coalesce(o.actual_date::text, ''), ',' order by o.id::text), '')
       from public.mock_outcomes o where o.user_id = p_user),
    (select coalesce(string_agg(s.suggestion_id || ':' || s.task_id, ',' order by s.suggestion_id, s.task_id), '')
       from public.checkpoint_suggestion_tasks s where s.user_id = p_user),
    (select coalesce(string_agg(a.id::text || ':' || a.version || ':' || a.status, ',' order by a.id::text), '')
       from public.mock_appointments a where a.user_id = p_user),
    (select coalesce(string_agg(r.id::text || ':' || r.status, ',' order by r.id::text), '')
       from public.mock_rehearsals r where r.user_id = p_user),
    (select coalesce(c.sat_on::text, '') from public.exam_completion c where c.user_id = p_user),
    (select coalesce(md5(string_agg(e.id::text || ':' || e.validity || ':' || coalesce(e.validity_reason, '') || ':' || coalesce(e.superseded_by_event_id::text, ''), ',' order by e.id::text)), '')
       from public.evidence_events e where e.user_id = p_user),
    (select concat_ws(',', j->>'exam_window_id', j->>'exam_date', j->>'prep_mode', j->>'class_pattern', j->>'max_session_minutes', j->>'timezone', j->>'stage', j->>'mock_date', j->>'mock_kind',
                      j->>'mock_start_time', j->>'mock_duration_minutes', j->>'mock_label', j->>'mock_version')
       from (select to_jsonb(p) as j from public.profiles p where p.id = p_user) x)
  ))
$$;


