    CONSTRAINT account_deletions_outcome_check CHECK ((outcome = ANY (ARRAY['deleted'::text, 'failed'::text])))
);


--
-- Name: assessment_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assessment_attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    status text DEFAULT 'in_progress'::text NOT NULL,
    score smallint,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    form_id uuid,
    delivery_mode text DEFAULT 'adaptive'::text NOT NULL,
    idempotency_key text,
    evidence_mode text,
    scoring_policy_version text,
    evidence_policy_version text,
    valid_response_count integer,
    correct_response_count integer,
    result_revision integer DEFAULT 1 NOT NULL,
    rescored_at timestamp with time zone,
    attempt_kind text,
    paper_kind text,
    cycle_id uuid,
    time_limit_minutes integer,
    deadline_at timestamp with time zone,
    paused_at timestamp with time zone,
    paused_seconds integer DEFAULT 0 NOT NULL,
    submitted_at timestamp with time zone,
    requested_blueprint jsonb,
    delivered_coverage jsonb,
    open_key text,
    eligibility_policy text,
    rehearsal_id uuid,
    session_no smallint,
    result_viewed_at timestamp with time zone,
    delivered_count integer,
    omitted_count integer,
    scoreable_count integer,
    CONSTRAINT assessment_attempts_attempt_kind_check CHECK ((attempt_kind = ANY (ARRAY['weekly'::text, 'reading'::text, 'subject'::text, 'repair'::text, 'mock'::text, 'module'::text, 'other'::text, 'practice'::text]))),
    CONSTRAINT assessment_attempts_delivery_mode_check CHECK ((delivery_mode = ANY (ARRAY['adaptive'::text, 'fixed'::text]))),
    CONSTRAINT assessment_attempts_evidence_mode_check CHECK ((evidence_mode = ANY (ARRAY['evidence'::text, 'practice'::text]))),
    CONSTRAINT assessment_attempts_paper_kind_check CHECK ((paper_kind = ANY (ARRAY['diagnostic'::text, 'revisionary'::text, 'mixed'::text]))),
    CONSTRAINT assessment_attempts_rehearsal_pair CHECK (((rehearsal_id IS NULL) = (session_no IS NULL))),
    CONSTRAINT assessment_attempts_score_check CHECK (((score >= 0) AND (score <= 100))),
    CONSTRAINT assessment_attempts_session_no_check CHECK ((session_no = ANY (ARRAY[1, 2]))),
    CONSTRAINT assessment_attempts_status_check CHECK ((status = ANY (ARRAY['assembling'::text, 'ready'::text, 'in_progress'::text, 'submitted'::text, 'scored'::text, 'partially_voided'::text, 'rescored'::text, 'abandoned'::text, 'expired'::text])))
);


