CREATE TABLE public.assessment_items (
    id text NOT NULL,
    lm_id text NOT NULL,
    learning_objective text NOT NULL,
    verification_intent text NOT NULL,
    difficulty numeric(5,2) DEFAULT 1.0 NOT NULL,
    stem text NOT NULL,
    options jsonb DEFAULT '[]'::jsonb NOT NULL,
    per_option_feedback jsonb DEFAULT '{}'::jsonb NOT NULL,
    provenance text NOT NULL,
    review_status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    concept_id uuid,
    cognition text,
    item_form text,
    intended_difficulty text,
    item_version integer DEFAULT 1 NOT NULL,
    solution_hash text,
    key_index smallint,
    item_card jsonb DEFAULT '{}'::jsonb NOT NULL,
    semantic_fingerprint text,
    generator_model text,
    verifier_model text,
    verified_at timestamp with time zone,
    reviewed_at timestamp with time zone,
    outcome_id text,
    family_id uuid,
    held_out boolean DEFAULT false NOT NULL,
    supersedes_item_id text,
    batch_id uuid,
    CONSTRAINT assessment_items_cognition_check CHECK ((cognition = ANY (ARRAY['recall'::text, 'interpret'::text, 'apply'::text, 'calculate'::text, 'compare'::text, 'diagnose'::text, 'integrate'::text]))),
    CONSTRAINT assessment_items_intended_difficulty_check CHECK ((intended_difficulty = ANY (ARRAY['foundation'::text, 'standard'::text, 'difficult'::text, 'stretch'::text]))),
    CONSTRAINT assessment_items_item_form_check CHECK ((item_form = ANY (ARRAY['direct'::text, 'scenario'::text, 'data_table'::text, 'calculation'::text, 'exception'::text, 'integrated'::text]))),
    CONSTRAINT assessment_items_review_status_check CHECK ((review_status = ANY (ARRAY['draft'::text, 'verified'::text, 'reviewed'::text, 'deprecated'::text])))
);


--
-- Name: assessment_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assessment_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attempt_id uuid NOT NULL,
    item_id text NOT NULL,
    user_id uuid NOT NULL,
    selected_option_index smallint,
    is_correct boolean,
    self_reported_confidence smallint,
    demonstrated_understanding boolean,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    elapsed_seconds integer,
    is_flagged boolean DEFAULT false NOT NULL,
