);


--
-- Name: item_confirmed_difficulty; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.item_confirmed_difficulty WITH (security_invoker='true') AS
 SELECT DISTINCT ON (item_id, item_version) item_id,
    item_version,
    level,
    rationale,
    reviewer_id,
    created_at,
    id AS review_id
   FROM public.item_difficulty_reviews r
  ORDER BY item_id, item_version, created_at DESC, id DESC;


