    CONSTRAINT profiles_class_pattern_check CHECK ((class_pattern = ANY (ARRAY['none'::text, 'fixed'::text, 'variable'::text, 'mixed'::text]))),
    CONSTRAINT profiles_diagnostic_day_check CHECK (((diagnostic_day IS NULL) OR ((diagnostic_day >= 0) AND (diagnostic_day <= 6)))),
    CONSTRAINT profiles_exam_sitting_check CHECK (((exam_sitting IS NULL) OR (exam_sitting = ANY (ARRAY['february'::text, 'may'::text, 'august'::text, 'november'::text])))),
    CONSTRAINT profiles_max_session_minutes_check CHECK (((max_session_minutes IS NULL) OR (max_session_minutes = ANY (ARRAY[20, 30, 45, 60, 90])))),
    CONSTRAINT profiles_mock_kind_check CHECK ((((mock_date IS NULL) AND (mock_kind IS NULL)) OR ((mock_date IS NOT NULL) AND (mock_kind = ANY (ARRAY['provider_mock'::text, 'school_checkpoint'::text, 'other'::text, 'internal_rehearsal'::text]))))),
    CONSTRAINT profiles_mock_timing_check CHECK ((((mock_date IS NOT NULL) OR ((mock_start_time IS NULL) AND (mock_duration_minutes IS NULL) AND (mock_label IS NULL))) AND ((mock_duration_minutes IS NULL) OR ((mock_duration_minutes >= 15) AND (mock_duration_minutes <= 480))) AND ((mock_label IS NULL) OR ((char_length(mock_label) >= 1) AND (char_length(mock_label) <= 80))))),
    CONSTRAINT profiles_onboarding_status_check CHECK ((onboarding_status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'review_ready'::text, 'complete'::text]))),
    CONSTRAINT profiles_onboarding_step_check CHECK (((onboarding_step >= 0) AND (onboarding_step <= 6))),
    CONSTRAINT profiles_prep_mode_check CHECK (((prep_mode IS NULL) OR (prep_mode = ANY (ARRAY['self_study'::text, 'self_paced_course'::text, 'instructor_led'::text, 'hybrid'::text])))),
    CONSTRAINT profiles_registered_exam_date_check CHECK ((NOT ((registered = true) AND (onboarding_status = 'complete'::text) AND (exam_date IS NULL)))),
    CONSTRAINT profiles_week_availability_mode_check CHECK ((week_availability_mode = ANY (ARRAY['windows'::text, 'varies'::text, 'none_this_week'::text])))
);


