CREATE VIEW public.rehearsal_eligible_items WITH (security_invoker='true') AS
 SELECT id,
    lm_id,
    learning_objective,
    verification_intent,
    difficulty,
    stem,
    options,
    per_option_feedback,
    provenance,
    review_status,
    created_at,
    concept_id,
    cognition,
    item_form,
    intended_difficulty,
    item_version,
    solution_hash,
    key_index,
    item_card,
    semantic_fingerprint,
    generator_model,
    verifier_model,
    verified_at,
    reviewed_at,
    outcome_id,
    family_id,
    held_out,
    supersedes_item_id,
    batch_id
   FROM public.assessment_items i
  WHERE ((review_status = 'reviewed'::text) AND (held_out = true) AND (EXISTS ( SELECT 1
           FROM public.item_review_decisions d
          WHERE ((d.item_id = i.id) AND (d.item_version = i.item_version) AND (d.decision = 'approve'::text)))));


