    CONSTRAINT repair_threads_status_check CHECK ((status = ANY (ARRAY['open'::text, 'proposed'::text, 'scheduled'::text, 'in_progress'::text, 'awaiting_recheck'::text, 'closed'::text, 'cancelled'::text, 'superseded'::text])))
